window.__D("text/likkutei-sichot/c144",{"p":[[1300221061,"<h3>שמיני ב*</h3>\nא. די לעצטע מס׳ פון די ששה סדרי משנה¹ — מס׳ עוקצין² — רעדט וועגן די פרטי דינים פון טומאת אוכלין וטומאת משקין (וואָס שטייען בפרש־תנו³), און די לעצטע הלכה⁴ פון דער מס׳ איז: חלות דבש מאימתי מיטמאות משום משקה, בית שמאי אומרים משיהרהר⁵ [לויט אַ צווייטער גירסא⁶: משיחרחר] בית הלל אומרים משירסק.\nבית שמאי האַלטן אַז גלייך ווי דער מענטש איז מהרהר במחשבתו⁷ „לרדות הדבש“ באַקומט עס אַ דין משקה און עס ווערט טמא בטומאת משקין; משא״כ לויט בית הלל איז עס מיטמא משום משקה ערשט „משירסק“ וואָס דאָן ווערט עס אַ משקה בפועל⁸.\nווייטער, אין דער משנה שלאחרי זה (די לעצטע משנה פון ששה סדרי משנה)⁹ שטייט: אמר ר׳ יהושע בן לוי עתיד הקב״ה להנחיל לכל צדיק וצדיק שלש מאות ועשרה עולמות שנאמר¹⁰ להנחיל אוהבי יש ואוצרותיהם אמלא. אמר ר׳ שמעון בן חלפתא לא מצא הקב״ה כלי מחזיק ברכה לישראל אלא השלום שנאמר¹¹ ה׳ עוז לעמו יתן ה׳ יברך את עמו בשלום.\nדאַרף מען פאַרשטיין: וואָס איז די שייכות פון דער לעצטער משנה — די מאמרים פון ר׳ יהושע בן לוי און ר׳ שמעון בן חלפתא — צו דער משנה שלפנ״ז (די פלוגתא צווישן ב״ש און ב״ה בנוגע חלות דבש)?\nדער רמב״ם¹² (און נאָך מפרשים¹³) זיינען מבאר: „לפי שהשלים כל דיני ההלכה . . חתם הדברים בגמול“ — ד.ה. די משנה האָט טאַקע ניט קיין המשך בתוכן צו דער משנה שלפני׳, נאָר דאָס איז אַ סיום אויף גאַנץ ששה סדרי משנה¹⁴, בכדי „להודיע בחתימת המש־",[["","","*) וסיום סדר טהרות וכל הש״ס משנה (ראה הערה הבאה). וראה בארוכה סה״ש תשמ״ח ח״ב ע׳ 645 ואילך."],["1","1","לפי הסדר הרגיל בששה סדרי משנה זמ״ן נק״ט. וראה הנסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111064\" data-slug=\"likkutei-sichot\" data-id=\"1300111064\">לקו״ש חי״א ע׳ 56</a> הערה 13. ועוד."],["2","2","כ״ה בדפוסי משניות וש״ס לפנינו. וכ״כ בפירוש — הרמב״ם בהקדמתו לפיה״מ. המאירי בפתיחתו. ועוד. — לדעת הר״ש (ריש מס׳ טהרות) מס׳ טהרות באה לאחרי מס׳ עוקצין, „אמנם רובם ככולם המחברים והמפרשים אינם מודים בזה להר״ש“ (סמיכת חכמים בהקדמה (ע, סע״ג))."],["3","3","יא, לד."],["4","4","פ״ג מי״א."],["5","5","גירסת י״א בפירוש רב האי גאון, ר״ש, רא״ש, הערוך (מע׳ חרחר), רע״ב. ועוד."],["6","6","עיקר הגירסא במקומות שבהערה הקודמת. פיה״מ להרמב״ם. ועוד. וכ״ה בנדפס."],["7","7","כ״ה במקומות שבהערה 5. ובתפא״י כאן שע״י דיבור. וראה משנה אחרונה. ואכ״מ."],["8","8","ראה פיה״מ ופי׳ הרא״ש. וראה משנה אחרונה."],["9","9","בחילופי גרסאות למשניות דמשנה זו „ליתא בכי״מ“. וראה מלאכת שלמה כאן (משנה יא)."],["10","10","משלי ח, כא."],["11","11","תהלים כט, יא."],["12","12","בפיה״מ כאן."],["13","13","רא״ש ורע״ב."],["14","14","ולהעיר שמצינו עד״ז בנוגע לתחלת הש״ס — מס׳ ברכות — שאינה שייכת כ״כ לסדר זרעים כ״א היא הקדמה לכללות שתא סדרי משנה (ראה פסקי הריא״ז ריש ברכות (הובא ג״כ בהגהה בהקדמת פיה״מ להרמב״ם ובמלאכת שלמה ריש *) אבל צ״ע אם פי׳ משנה זו הוא להרא״ש — ראה מלאכת שלמה (שבהערה 9) דהרא״ש סיים פי׳ המשנה בבבא דחלות דבש. ואולי הוא הוספת המדפיסים מפיה״מ להרמב״ם (בשינוי לשון, או נוסחא אחרינא). ובמלאכת שלמה (משנה יב) העתיק בשם הרמב״ם כלשון הרא״ש."]]],[1300221062,"נה מתן שכרן של צדיקים שלומדים ומקיימים כל מה שכתוב במשנה“¹⁵.\nלויט אבער ווי מען געפינט אין דער גמרא בכ״מ¹⁶ אַז מען איז מבאר דעם טעם הסמיכות פון משניות אפילו ווען זיי שטייען (זו אחר זו) אין באַזונדערע מסכתות, ועאכו״כ צוויי משניות פון דעם זעלבן פרק¹⁷ — לכאורה יש מקום צו זוכן און מבאר זיין אויך די שייכות פון די צוויי משניות — (אע״פ שטעם הרמב״ם בתקפו עומד — עכ״פ להמתיק וכו׳).\nוי״ל אַז דער תוכן משנה הסמוכה צום סיום המשניות (בענין שכר המצות), די פלוגתא צווישן ב״ש און ב״ה בנוגע חלות דבש, האָט אַ שייכות צו דעם ענין שכר מצוה וואָס רעדט זיך בסיום המשניות¹⁸.\nב. ובהקדם ההסברה אין דברי המפרשים הנ״ל — אַז דער סיום פון ששה סדרי משנה במאמרים הנ״ל איז בכדי צו מודיע זיין ענין מתן שכרן של צדיקים — דלכאורה איז ניט פאַר־שטאַנדיק:\nדאָ רעדט זיך דאָך וועגן צדיקים און ווי זיי האַלטן שוין ביים „סיום“ פון ששה סדרי משנה — שלימות בלימוד התורה — כללות התושבע״פ און ווי אַ צדיק לערנט עס — איז דאָך לכאורה פשוט ומובן, אַז זיי האַלטן שוין געוויס ביי דעם אופן העבודה לויט ציווי המשנה נאָך בסדר נזיקין — „משמשין את הרב שלא ע״מ לקבל פרס“¹⁹, ניט צוליב שכר, נאָר לשמה;\nזאת ועוד: דער פסוק, וואָס ווערט געבראַכט אין דער משנה גופא, זאָגט: „להנחיל אוהבי יש“ — די וואָס דינען דעם אויבערשטן מאהבה, וואָס דאָס מיינט (ווי דער רמב״ם איז מבאר בארוכה²⁰) אַז זיי טוען זייער עבודה לשמה, ניט לשם שכר נאָר „עושה האמת מפני שהוא אמת“²¹,\n(אמת טאַקע אַז דער וואָס איז „עושה האמת מפני שהוא אמת“ איז מובטח (ווי דער רמב״ם זאָגט דאַרט²¹) אַז „סוף הטובה לבא בגללה“, אָבער ניט דאָס איז די שלימות צו וועלכער ער שטרעבט צו דערגרייכן מיט זיין עבודה; ביי אַן עובד ה׳ מאהבה איז דער ענין פון „סוף הטובה לבא בגללה“ נאָר אַ דבר טפל וצדדי, און דער עיקר ביי אים איז וואָס ער האָט זוכה געווען צו דינען דעם אויבערשטן לשמה) —\nאון וויבאַלד אַז דער עיקר ותכלית אין עבודת התומ״צ איז לשמה און ניט לקבל שכר — ווי איז מתאים, אַז ביים סיום פון אַלע ששה סדרי משנה, וואָס דאָס מיינט אַ מצב פון תכלית ושלימות נעלה בעבודת ה׳ כו׳, זאָל די חתימה זיין (ניט אַז „נפשו קשורה באהבת השם כו׳“²² נאָר) וואָס ער וועט האָבן ש״י עולמות כו׳ — אלס גמול ושכר פאַר עבודת התומ״צ?!²³",[["","","ברכות). וראה גם המאירי בפתיחתו (קרוב לסופה) ובהקדמתו למס׳ ברכות)."],["15","15","לשון הרע״ב."],["16","16","ראה ריש מס׳ תענית; סוטה; מכות. ועוד."],["17","17","דבאותה מסכת לכו״ע יש סדר למשנה (ב״ק קב, סע״א), ומכש״כ באותו פרק."],["18","18","ראה גם חשק שלמה לסוף עוקצין."],["19","19","אבות פ״א מ״ג."],["20","20","הל׳ תשובה פ״י ה״ב ואילך. פיה״מ סנהדרין חלק בהקדמה."],["21","21","לשון הרמב״ם הל׳ תשובה שם."],["22","22","ל׳ הרמב״ם שם ה״ג."],["23","23","להעיר גם מ<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201045\" data-slug=\"likkutei-sichot\" data-id=\"1300201045\">לקו״ש ח״כ ע׳ 45</a>; „הדרן“ למס׳ אבות ס״ג ואילך (ס׳ ביאורים לפרקי אבות (קה״ת) בסופו). ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201051\" data-slug=\"likkutei-sichot\" data-id=\"1300201051\">לקו״ש שם (ע׳ 51</a> ואילך) נת׳ שאצל עובד מאהבה גם הענין דשכר מצות הוא חלק מענין"]]],[1300221063,"מוז מען זאָגן, אַז די זאַך פון „להנחיל כו׳ ש״י עולמות“ וואָס רעדט זיך אין דער משנה דאָ, איז ניט אַן ענין פון שכר מצות במובנו הרגיל²⁴ — אַ תשלום פון עולמות פאַר עבודה להשם, נאָר דאָס איז אַ העכערע שלימות בעבודה, אַן עלי׳ צו וועלכער דער עובד מאהבה דערגרייכט ע״י עבודתו²⁵.\nג. און דאָס איז נקודת השייכות צווישן דער משנה מיט דער משנה שלפני׳ — פלוגתת ב״ש וב״ה בחלות דבש:\nמהטעמים (ע״ד הרמז) וואָס די לעצטע הלכות (אין משנה) — חיתום המשנה, שהכל הולך אחר החיתום²⁶ — זיינען בנוגע „דבורים“ און „דבש“, איז ווייל „דבורים“ זיינען כביאור חז״ל²⁷ מרמז אויף שלימות העבודה, עבודה לשמה (כדלקמן סעיף ז), וואָס די עבודה איז אַ הכנה והקדמה צו „עתיד הקב״ה להנחיל לכל צדיק כו׳“ — די שלימות צו וועלכער מען דערגרייכט ע״י עבודה ווי עבודת דבורים;\nאון די סברות אין פלוגתת ב״ש וב״ה אין דער פלוגתא (בחלות דבש)\n— וואָס איז (ווי גערעדט כמה פעמים²⁸) פאַרבונדן מיטן חילוק כללי צווישן זייערע שיטות צי „אזלינן בתר בכח“ אדער „אזלינן בתר בפועל“: ב״ש האלט אַז „אזלינן בתר בכח“ און דערי־בער באַקומט עס אַ דין משקה גלייך „משיחרחר“, אדער אפילו „משיהרהר“ (ווייל בכח איז עס שוין משקה, אע״פ אַז ס׳איז נאָך ווייט פון משקה בפועל); און ב״ה האלט „אזלינן בתר בפועל“ און דעריבער האָט עס ניט קיין דין משקה ביז עס ווערט משקה בפועל „משיר־סק“ —\nבראַנגען אַרויס אַ נפק״מ אין דעם כללות הענין פון מטרת בריאת האדם עלי ארץ וואָס איז „נבראתי לשמש את קוני“²⁹ (כדלקמן סעיף ח ואילך), ובמילא (אויך) — אַ נפק״מ בנוגע דער שלימות האדם ע״י עבודתו. ובמילא דורך נאָכן פלוגתת ב״ש וב״ה הנ״ל ווערט בעסער פאַרשטאַנדיק דער סיום המשניות „עתיד הקב״ה להנחיל כו׳“.\nד. לשון המשנה וועלכער איז לשון קצרה³⁰ ובתכלית הדיוק: „עתיד הקב״ה להנחיל כו׳ ש״י עולמות“ — איז לכאורה, ווי פאַסט דאָ „להנחיל“, אַן ענין של ירושה³¹? — ירושה איז ניט פאַרבונדן מיט דער עבודה פון דעם יורש (אויב נאָר ער איז געבאָרן געווארן³² בקורבה פון אַ יורש, איז ער בדרך ממילא יורש) — איז ווען עס רעדט זיך וועגן מתן שכרן של צדיקים, האָט געדאַרפט שטיין „עתיד הקב״ה ליתן“ (אדער כיו״ב)?\nדי תמי׳ איז נאָך גרעסער: דער זעל־בער מאמר ווערט געבראַכט אין מס׳",[["","","המצוה גופא (שלכן הבטיח הקב״ה לאברהם — אוהבי. ראה רמב״ם שם — (לך טו, א) „שכרך הרבה מאד“), ע״ש, אבל מובן, שאי״ז בערך לעצם המצוה עצמה, ולא הו״ל לסיים המשניות בענין טפל."],["24","24","ועפ״ז — לשון „גמול“, „שכר“ שבמפרשים הנ״ל הוא שם המושאל."],["25","25","ראה גם משנה אחרונה כאן: והשכר ההוא הוא ידיעת האלקות כו׳."],["26","26","ברכות יב, א."],["27","27","דב״ר פ״א, ו."],["28","28","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011160\" data-slug=\"likkutei-sichot\" data-id=\"1300011160\">לקו״ש ח״א ע׳ 146</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061070\" data-slug=\"likkutei-sichot\" data-id=\"1300061070\">ח״ו ע׳ 70</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071126\" data-slug=\"likkutei-sichot\" data-id=\"1300071126\">ח״ז ע׳ 114</a>. ועוד."],["29","29","קידושין בסופה."],["30","30","הקדמת הרמב״ם בפיה״מ ד״ה אחרי כן ראה להסתפק."],["31","31","כדיוק התוי״ט (ועוד) כאן. וראה שו״ת נוב״י מהד״ת חיו״ד סקס״א (בתי׳ הקושיא שבהערה 34)."],["32","32","או ע״י נישואין (ראה כתובות פג, א ואילך. ב״ב קח, א. קיא, ב)."]]],[1300221064,"סנהדרין³³, און דאַרט שטייט טאַקע „עתיד הקב״ה ליתן לכל צדיק וצדיק ש״י עולמות“!\nוי״ל הביאור אַז — היא הנותנת³⁴: דער מאמר אין מס׳ סנהדרין וועלכער איז געזאָגט געווארן דורך אמורא רבא בר מרי רעדט טאַקע וועגן שכר המצות, און דעריבער זאָגט ער „עתיד הקב״ה ליתן“;\nאבער אין דער משנה — וואָס קומט אלס סיום וחיתום המשניות — רעדט זיך ניט וועגן שכר המצות (בפשטות), נאָר (כנ״ל) וועגן דער שלימות צו וועל־כער דער צדיק דערגרייכט על ידי עבודתו מאהבה. און דעריבער איז ריב״ל³⁵ מדייק „עתיד הקב״ה להנחיל“ — ווייל אָט די שלימות איז בדוגמת ובגדרי ירושה.\nה. בנוגע ירושה, איז ידוע וואָס דער ראַגאַטשאַוער³⁶ איז מבאר אַז אַ יורש איז ניט אַ צווייטע מציאות וואָס באַ־קומט נכסים פון דעם מוריש, נאָר (בלשון הכתוב³⁷) „תחת אבותיך יהיו בניך“ — דער יורש שטייט במקום המוריש, אַ יורש איז איין זאַך מיטן מוריש („עצם האב“ בלשונו).\nועד״ז איז בנוגע צו אַ אידן: די שלימות וואָס ווערט אויפגעטאָן דורך דעם וואָס אַ איד לערנט תורה און איז מקיים מצות איז וואָס ישראל אורייתא וקוב״ה כולא חד („ג׳ . . מתקשראן דא בדא קב״ה אורייתא וישראל“³⁸, ווערט כולא חד) ועד״ז³⁹ דורך קיום המצות לשון צוותא וחיבור — אַ איד ווערט כביכול איין זאַך מיטן נותן התורה ומצווה המצות, דעם אויבערשטן אליין.\nאון דאָס איז דער פשט פון „להנחיל אוהבי יש“: דער רמב״ם⁴⁰ איז מבאר אַז דער לשון „יש“ ווייזט אויף „מציאות התמידית אשר אין לה תכלית“⁴¹, און „להנחיל אוהבי יש“ מיינט: „לאוהבי אנחיל את היש המוחלט“, ווייל „כל נפש שתזכה לחיי העוה״ב לא תכלה לעולם“.\nווי קען אַ נברא, אַ בעל גבול, „נעמען“ אַ „יש המוחלט“, אַ „מציאות התמידית“ — אַן ענין פון נצחיות און בלתי בעל גבול? איז דער פסוק מבאר ומדגיש „להנחיל אוהבי יש“: אידן באַ־קומען עס ניט אלס אַ מקבל פון אַ נותן, אַ צווייטע מציאות וועלכע נעמט עס פונעם „נותן“, נאָר אידן זיינען דאָס נוחל אלס יורש וואָס איז איין זאַך מיטן מוריש: אידן זיינען „בנים“ להקב״ה⁴² — און דעריבער, בשעת אַ איד לערנט תורה און איז מקיים מצות ווערט נתגלה ווי ער איז איין מציאות מיטן אמתי׳ן „יש המוחלט“⁴³ („מציאות התמידית“), „אותי אתם לוקחים“⁴⁴.",[["33","33","ק, סע״א. וראה הערה הבאה."],["34","34","ע״פ המבואר בפנים מתורצת קושיית המפרשים — מה מוסיף המאמר (בשם אמורא) בסנהדרין שם על המפורש במשנה."],["35","35","ראה רמב״ם בסוף הקדמתו לפיה״מ שהי׳ תנא, וראה תוי״ט, מלאכת שלמה ועוד כאן."],["36","36","שו״ת צפע״נ דווינסק ח״א סקי״ח. ווארשא ח״ב סקי״ח. ועוד."],["37","37","תהלים מה, יז. וראה ב״ב קנט, א."],["38","38","זח״ג עג, א."],["39","39","אף שחילוק ביניהן גופא ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא פכ״ג</a>. ועוד."],["40","40","בפיה״מ כאן. ועד״ז ברא״ש (וראה לעיל שוה״ג להערה 13)."],["41","41","כ״ה הלשון בהעתקת קאפח. ובפיה״מ לפנינו הוא בשינוי לשון."],["42","42","שמות ד, כב. ראה יד, א. אבות פ״ג מי״ד. ובכ״מ."],["43","43","ראה גם מאמרי אדה״א בראשית ע׳ נח (וש״נ). סד״ה אריב״ל (סה״מ קונטרסים ח״ב תב, א) וסה״מ ה׳ש״ת (ע׳ 49) דלהנחיל אוהבי יש הו״ע יש האמיתי."],["44","44","שמו״ר פל״ג, ו (וראה שם, א). ויק״ר פ״ל, יג. ועוד. ע״פ המבואר בפנים יובן ג״כ מה שמביא התנא"]]],[1300221065,"ו. דערפון איז פאַרשטאַנדיק בנוגע דעם עונג וואָס קומט דערפון אַרויס לצדיקים\n— וואָס דאָס איז דער פירוש אין דברי ריב״ל „עתיד הקב״ה להנחיל לכל צדיק וצדיק ש״י עולמות“, ווי דער רמב״ם⁴⁰ איז מבאר, אַז דאָס מיינט אַז דער תענוג פון עוה״ב איז „שלש מאות ועשר פעמים“ ווי „כל התענוגות העולם הזה“⁴¹ —\nדאָס איז ניט דער עונג פון די צדיקים ווי זיי זיינען פאַר זיך [בלשון החסי־דות⁴⁵: דער „נחת רוח לנברא“ — דער נחת רוח וואָס ווערט באַם אידן אלס שכר וואָס ער האָט מקיים געווען דעם אויבערשטנ׳ס רצון], נאָר דאָס איז דער תענוג פון אויבערשטן כביכול („נחת רוח לבורא“), כמחז״ל⁴⁶ „נחת רוח לפני שאמרתי ונעשה רצוני“:\nוויבאַלד אידן זיינען איין זאַך מיטן „מוריש“, זיינען זיי „נוחל“ כביכול דעם תענוג הבורא.\n[און ווי דער רמב״ם⁴⁰ איז גלייך מבאר, אַז דאָס ווי ריב״ל נוצט אַ מספר פון „שלש מאות ועשרה“ איז „על דרך ההערה בלבד“⁴¹, אבער לפי האמת איז דאָס אַ תענוג בלתי מוגבל].\nאון דאָס איז דער חילוק צווישן שכר מצות און „להנחיל כו׳ אוהבי יש“:\nדער תענוג וואָס קומט אַן צום אדם אלס שכר העבודה — וואָס קבלת שכר ווייזט אַז דער מקבל השכר איז אַ מצי־אות פאַר זיך (וועמען מען דאַרף באַ־לוינען פאַר זיין אַרבעט) — איז דער תענוג וויפל אַן אדם אלס נברא קען פאַרנעמען;\nמשא״כ דער ענין פון „עתיד הקב״ה להנחיל כו׳ אוהבי יש“ איז דער „נחת רוח לבורא“ (און ענין פון „יש המוחלט“), וואָס דאָס איז ניט דער ענין פון שכר מצוה, נאָר דאָס איז די „עצם המצוה“⁴⁵. און דאָס קומט אַן צום אדם בדרך נחלה — ווייל ער איז איין זאַך כביכול מיטן אויבערשטן.",[["","","בהמשך למאמרו של ריב״ל את מאמר ר׳ שמעון בן חלפתא „לא מצא הקב״ה כלי מחזיק ברכה לישראל אלא השלום שנאמר (תהלים כט, יא) ה׳ עוז לעמו יתן ה׳ יברך את עמו בשלום“ — דלכאורה אינו מובן: א) מהי השייכות ביניהם? ב) בכל אופן הו״ל להקדים מאמרו של ר״ש בן חלפתא שהי׳ קודם לריב״ל (כקושיית התוי״ט. וראה גם מלאכת שלמה. ועוד) — אלא דלכאורה קשה לאידך גיסא מאחר ש„עתיד הקב״ה להנחיל כו׳ אוהבי יש“ אינו מובן איך אפשר שהאדם נוחל „יש המוחלט“ ואעפ״כ ישאר במציאותו, נברא מוגבל [ובפרט לפי ההכרעה בקבלה וחסידות (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380138\" data-slug=\"likkutei-torah\" data-id=\"4001380138\">לקו״ת צו טו, ג</a>. דרמ״צ יד, ב. ובכ״מ) כדעת הרמב״ן דעוה״ב הוא לנשמות בגופים דוקא]? וע״ז מביא מאמרו של ר״ש בן חלפתא „לא מצא הקב״ה כלי מחזיק ברכה לישראל אלא השלום“ — שהכלי המחזיק ברכה זו (דלהנחיל אוהבי יש) לישראל* הוא השלום, שענינו של שלום הוא לחבר שני הפכים ומנוגדים, ולכן פועל החיבור של „יש המוחלט“ עם נברא מוגבל**. *) ומתורץ עפ״ז אומרו כאן „לישראל“, דמשמע דרק עבור ישראל הוי השלום כלי מחזיק ברכה, ולא לשאר עמים (וראה הלשון בדב״ר ס״פ שופטים: לא מצא כו׳ מחזיק כל הברכות לברכן בו אלא השלום) — כי כוונת ר״ש בן חלפתא אינה למעלת השלום בכלל, כ״א לזה שהוא „כלי מחזיק ברכה“ המיוחדת לישראל (בניו של הקב״ה) — „להנחיל אוהבי יש“. **) עפ״ז מובן ג״כ למה הביא גם תחילת הכתוב „ה׳ עוז לעמו יתן“ — דלכאורה אינו נוגע לענין השלום (וראה תוי״ט ועוד כאן) — כי ענינו של „שלום“ כאן הוא מה שנותן עוז להנברא לקבל ה„יש המוחלט“, הבלתי בע״ג. וראה סנהדרין ק, ב."],["45","45","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380828\" data-slug=\"likkutei-torah\" data-id=\"4001380828\">לקו״ת ראה כח, רע״א</a>. המשך וככה תרל״ז פי״ב. לקו״ש ח״ה ע׳ 244."],["46","46","פרש״י ויקרא א, ט. פנחס כח, ח מספרי עה״פ (וכ״ה בספרי שלח טו, ג. וראה רש״י שם)."]]],[1300221066,"ז. דאָס איז דער טעם פאַרוואָס דער „להנחיל . . יש“ איז „לאוהבי“ דוקא. ווייל ווען קען דער אדם צוקומען צום ענין פון „להנחיל אוהבי יש“ — בעת אַז אויך זיין עבודה איז אין אַזאַ אופן, אַז ער טראַכט ניט וועגן זיך, נאָר ער טוט אינגאַנצן לשמה — פאַרן אויבערשטנ׳ס וועגן.\nכל זמן דער אדם טראַכט וועגן אַן ענין של שכר, אדער וועגן זיך בכלל (זיין עלי׳) — איז ניט שייך אַז ער זאָל ווערן איין זאַך מיט „יש המוחלט“ און „מציאות התמידית“ וואָס איז אינגאַנצן העכער פון גדר הנבראים.\nדוקא ווען זיין עבודה איז אינגאַנצן לשמה — ער איז ניט קיין מציאות פאַר זיך, ער טראַכט נאָר וועגן דער עצם המצוה (וואָס דערפון ווערט דער „נחת רוח לפני שאמרתי ונעשה רצוני“) — ווערט דער „אותי אתם לוקחים“, ובמילא — „להנחיל אוהבי יש“.\n[ע״ד ווי מען געפינט אין הלכה, אַז אַן אמת׳ער „עבד“, עבד ע״פ תורת אמת, איז ניט קיין מציאות פאַר זיך, זיין גאַנצע מציאות איז — „מציאות האדון“⁴⁷].\nאון דאָס איז אויך דער רמז אין דעם, וואָס די משניות שלפנ״ז ריידן וועגן „כוורת דבורים“ און „חלות דבש“ — ווייל די עבודה פון אידן אין דעם אופן פון לשמה איז אַנגעדייטעט אין דעם וואָס אידן זיינען צוגעגליכן געווארן צו „דבורים“. ווי עס שטייט אין מדרש⁴⁸: „כדבורים היו בני . . מה הדבורה הזאת כל מה שהיא מסגלת מסגלת לבעלי׳, כך כל מה שישראל מסגלין מצות ומעשים טובים הם מסגלים לאביהם שבשמים“.\nוכמבואר בלקו״ת⁴⁹ אַז די עבודה באופן זה קומט פון דער הכרה אַז „תכלית המכוון בבריאת האדם אינו בשביל האדם עצמו לבד, אף שבאמת עלייתו נפלאה מאד, עכ״ז לא זו לבד הוא תכלית המכוון כ״א לכבודו ית׳“. וכמחז״ל⁵⁰ „אני נבראתי לשמש את קוני“.\nח. עפ״ז קען מען אויך מבאר זיין די שייכות פון דער משנה צו פלוגתת ב״ש וב״ה ביי חלות דבש — ובהקדים: אין דעם לשון הנ״ל (פון לקו״ת) איז מודגש אַז לפועל קומט צו דער־אדם דורך זיין עבודה למטה צו אַן עלי׳ נפלאה מאד, ס׳איז נאָר אַז „לא זו לבד הוא תכלית המכוון“⁵¹.\nאיז אין דעם דאָ אַ חילוק צווישן שיטת ב״ש (וואָס האַלטן „אזלינן בתר בכח“) און שיטת ב״ה (אַז „אזלינן בתר בפועל“) — אויף ווי טיף דער ענין (די עלי׳) איז תופס מקום⁵²:\nאויב „אזלינן בתר בכח“, אַז דער עיקר פון יעדן ענין איז ווי עס שטייט „בכח“ — קומט אויס, אַז די ירידת הנשמה למטה (דער „בפועל“) טוט ניט אויף קיין מעלה (חדשה) אין דער נשמה לגבי ווי זי איז געווען קודם ירידתה. ווייל דער עיקר הענין — דער „כח“ אויף דורכ־פירן די עבודה למטה — איז שוין דאָ אין דער נשמה נאָך איידער זי איז יורד למטה.",[["47","47","ראה חי׳ הרשב״א לקידושין כג, ב. וראה בארוכה המשך תרס״ו ע׳ שכו ואילך."],["48","48","דב״ר פ״א, ו (הובא בלקו״ת שבהערה הבאה)."],["49","49","ראה כה, סע״ד (ואילך)."],["50","50","קידושין בסופה."],["51","51","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151260\" data-slug=\"likkutei-sichot\" data-id=\"1300151260\">לקו״ש חט״ו ס״ע 247</a> ואילך (ובהערות 52, 54 שם). ח״כ ע׳ 284 הערה 30. וש״נ."],["52","52","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211017\" data-slug=\"likkutei-sichot\" data-id=\"1300211017\">לקו״ש חכ״א ע׳ 17</a>."]]],[1300221067,"נאָך מער: בנדו״ד דאַרף מען אפילו ניט האַבן דעם „פועל“ אלס אַ „בחינה“ אויפן „כח“⁵³ הנשמה צו דורכפירן איר עבודה למטה — ווייל ס׳איז אַ זיכערע זאַך אַז סוף־סוף וועט יעדע נשמה דורכפירן איר שליחות בעלמא דין כמש״נ⁵⁴ לבלתי ידח ממנו נדח, ועוד וג״ז עיקר — כלפי שמיא גליא אַז זי וועט דאָס דורכפירן;\nקומט אויס, אַז לויט ב״ש איז ניטאַ קיין ארט צו זאָגן אַז די עלי׳ נפלאה פון דעם אדם איז אַן אויפטו וחידוש וואָס צוליב דעם אדם דאַרף זיין ירידת הנשמה למטה בפועל; און דאָס וואָס די נשמה איז יורד למטה איז (לגמרי ניט צוליב דעם עילוי וואָס ווערט אויפגעטאָן אין דער נשמה, נאָר) בלויז „לסגל לבעלי׳“, כדי צו דורכפירן די כוונה פון אויבערשטן, וואָס נתאווה הקב״ה להיות לו דירה בתחתונים — און פאַר דעם ענין איז ניט גענוג וואָס די נשמה האָט „בכח“ צו מאכן די דירה, נאָר דער תחתון דאַרף בפועל נשתנה ווערן צו זיין אַ דירה לו ית׳, עס מוז זיין די פעולה אין דעם תחתון, ובמילא — ירידת הנשמה למטה בפועל⁵⁵.\nמשא״כ לויט שיטת בית הלל אַז „אזלינן בתר בפועל“, קומט אויס, אַז די ירידת הנשמה למטה טוט אויף אַ מעלה (אויך) אין דער נשמה (וואָס זי האָט פריער ניט געהאַט) — ווייל דוקא דורך ירידה למטה ברענגט זי אַרויס אירע כוחות מן הכח אל הפועל (וואָס לויט ב״ה איז דאָס דער עיקר פון יעדן ענין).\nאון דעריבער, לויט בית הלל, אע״פ אַז דער עיקר הענין פון ירידת הנשמה למטה איז „לכבודו ית׳“ — אני נבראתי לשמש את קוני, בכדי צו דורכפירן די כוונה פון „דירה בתחתונים“, און דאָס דאַרף זיין די כוונה פון דעם אדם בעבודתו — פונדעסטוועגן, איז זיין עבודה למטה אַן ענין וואָס טוט אויף אַ חידוש אויך אין אים.\nט. דער חילוק הנ״ל צווישן ב״ש און ב״ה גיט אויך אַ הסברה אין זייער פלוגתא⁵⁶ — „הללו (ב״ש⁵⁷) אומרים נוח לו לאדם שלא נברא יותר משנברא, והללו (ב״ה⁵⁷) אומרים נוח לו לאדם שנברא יותר משלא נברא. נמנו וגמרו נוח לו לאדם שלא נברא יותר משנברא עכשיו שנברא יפשפש במעשיו“.\nאין לקו״ת דאַרט⁵⁸ איז מבואר דער פשט אין דעם מאמר חז״ל: זיי זאָגן ניט „טוב לו שלא נברא“ — ווייל ס׳איז בודאי דאָ אַ טובה פאַר דער נשמה דורך ירידתה למטה, וואָס זי באַקומט אַן „עלי׳ גדולה ונפלאה לאין קץ“; נאָר דער פשט איז — „נוח וקל הי׳ לו שלא נברא“, ווייל דער „תכלית המכוון בבריאתו“ איז אַז „לא יעבוד לגרמי׳ ולקבל פרס“, נאָר בלויז „לשמש את קונו“, וואָס דאָס איז אַן עבודה קשה ביותר, און ס׳איז „נוח וקל לו“ אַז ער זאָל דאָס ניט דאַרפן טאָן.\nשטעלט זיך לפ״ז די שאלה: וואָס איז די הוי אמינא פון בית הלל צו זאָגן אַז „נוח (וקל) לו לאדם שנברא יותר משלא נברא“?",[["53","53","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101079\" data-slug=\"likkutei-sichot\" data-id=\"1300101079\">לקו״ש ח״י ע׳ 79</a>, שזהו ענינו של „פועל“ לדעת ב״ש."],["54","54","ש״ב יד, יד. — הובא בהל׳ ת״ת לאדה״ז פ״ד סוס״ג. <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא ספל״ט</a>."],["55","55","ראה בכ״ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201297\" data-slug=\"likkutei-sichot\" data-id=\"1300201297\">לקו״ש ח״כ ע׳ 284</a>."],["56","56","עירובין יג, ב."],["57","57","כ״ה בפשטות, ש„הללו“ הא׳ הם דברי ב״ש — בהתאם להסדר „נחלקו ב״ש וב״ה“ (וראה רדב״ז הל׳ מע״ש פ״י ה״ג. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161002\" data-slug=\"likkutei-sichot\" data-id=\"1300161002\">לקו״ש חט״ז ע׳ 2</a>). ובפרט שבכ״מ מקדים רבינו הקדוש דברי ב״ש לב״ה (ריטב״א עירובין שם. וראה תוד״ה שנים חגיגה טז, סע״א)."],["58","58","שם כט, א."]]],[1300221068,"איז דער ביאור אין דעם: לויט ב״ש איז טאַקע מלכתחילה פשוט אַז דער גאַנצער ענין פון ירידת הנשמה למטה איז (ניט בשביל (עליית) הנשמה, נאָר) בלויז „לכבודו ית׳“. וכנ״ל, אַז צוליב עליית הנשמה דאַרף מען ניט די ירידה בפועל, ס׳איז גענוג דער „בכח“. ובמילא איז פשוט אַז „נוח לו לאדם שלא נברא כו׳“ — ווייל פאַר אים („לו“) איז ניטאַ קיין חידוש דורך ירידתו למטה, ס׳איז נאָר לכבודו ית׳.\nמשא״כ לויט ב״ה איז דאָ אַן אַרט צו זאָגן, אַז ס׳איז „נוח לו לאדם שנברא יותר משלא נברא“, ווייל ווען ער וואָלט ניט „נברא“ געווארן, וואָלט ער קיין שייכות ניט געהאַט צו דער „עלי׳ גדולה ונפלאה לאין קץ“. און וויבאַלד אַזוי, איז דער תענוג דערפון וואָס די נשמה האָט פון דער עלי׳ אַ סך גרעסער ווי דער צער הנשמה בירידתה למטה, ביז אַז ס׳איז „נוח לו שנברא“ (פילנדיק אַז דאָס וועט ברענגען אַן עלי׳ נפלאה (תענוג עצום), למרות דעם איצטיקן צער), ווי „לא נברא“ און ניט האָבן קיין שייכות צו דער עלי׳ גדולה ונפלאה.\nאַבער „נמנו וגמרו נוח לו לאדם שלא נברא יותר משנברא“ — ווייל אע״פ אַז די נשמה וועט לפועל צוקומען בירי־דתה למטה צו דער „עלי׳ גדולה ונפלאה לאין קץ“, איז אַבער ניט דאָס דאַרף זיין מחשבת האדם בשעת עבודתו. ער דאַרף טאָן זיין עבודה אינגאַנצן „לא לגרמי׳ ולקבל פרס“, נאָר בלויז „לשמש את קונו“, לגמרי ניט טראַכטן וועגן זיך און זיינע עליות. און דעריבער, איז „נוח וקל לו שלא נברא יותר משנברא“⁵⁹.\nיו״ד. און דאָס איז אויך די שייכות פון דער משנה פון „חלות דבש“ צו דער משנה האחרונה „עתיד הקב״ה להנחיל כו׳“:\nפריער ברענגט די משנה פלוגתת ב״ש וב״ה צי „אזלינן בתר בכח“ אדער „אזלינן בתר בפועל“, וואָס לפ״ז וואָלט געווען אַן ארט צו זאָגן, אַז לדעת ב״ה איז די עליית (ושכר) האדם דער עיקר הטעם (אדער עכ״פ אַ טעם שווה) פון זיין ירידה למטה;\nאיז די משנה ממשיך — בדוגמת צו „נמנו וגמרו“ הנ״ל — „אמר ריב״ל עתיד הקב״ה להנחיל כו׳ אוהבי יש“: לכולי עלמא (פון משנה הקודמת), אויך לדעת ב״ה, איז די מטרה ותכלית העבודה של הנשמה למטה (ניט איר שכר ועלי׳, נאָר) ווי דער דבש פון דבורים „לסגל לבעלי׳“ — צו דורכ־פירן רצונו און כוונתו של הקב״ה, וואָס דריקט זיך אויס אין דעם וואָס די נשמה ווערט איין זאַך, כביכול, מיטן „יש המוחלט“, „המציאות התמידית“.\nאעפ״כ מיינט עס ניט אַז עס וועט לגמרי ניט זיין קיין שכר ועלי׳ פאַר דער נשמה — דאָס וועט אויך זיין. און דער־פאַר ברענגט ריב״ל אויך דעם המשך הפסוק⁶⁰ (וואָס קומט נאָך די ווערטער „להנחיל אוהבי יש“) — „ואוצרותיהם",[["59","59","ועפ״ז מפרש בלקו״ת שם גם „ועכשיו שנברא יפשפש במעשיו“, שהכוונה — שידע שנברא (לא בשביל עליותיו, כ״א) לשמש את קונו."],["60","60","דלכאורה 1) אינו שייך לכאן, 2) ויתרה מזה — זהו בסתירה להמאמר, דמפורש שיש יותר מהענין דש״י עולמות. ואדרבא: לולא דרש ריב״ל מובן ומוכרח סיום הכתוב, כי „להנחיל אוהבי יש“ פירושו רק ש„יש אתי נחלה רבה“ (רש״י ועוד עה״פ) שיכול להנחיל, ו„אוצרותיהם אמלא“ שינחיל בפועל. ועיין זח״א בהקדמה (ו, א). אבל לפי רבי״ל ש„להנחיל אוהבי יש“ קאי על ש״י עולמות שעתיד הקב״ה להנחיל לכל צדיק וצדיק, פשיטא שאין למלא אוצרות בש״י עולמות!"]]],[1300221069,"אמלא“, וואָס דאָס גייט אויף די אוצרות של הצדיקים (בעוה״ז)⁶¹: וויבאַלד דער אויבערשטער איז „אינו מקפח שכר כל ברי׳“⁶², באַקומט דעריבער די נשמה אויך אַן ענין של שכר (אלס נברא).\nאבער דער ענין פון „ואוצרותיהם אמלא“ ברענגט ניט ריב״ל אין זיין עצם המאמר („עתיד הקב״ה להנחיל כו׳ ולמלא אוצרותיהם“), נאָר בלויז בדרך אגב, ברענגענדיק דעם פסוק „להנחיל אוהבי יש“ — ווייל אין זיין עצם מאמר רעדט ער וועגן דער עיקר שלימות דלעתיד, נאָר כדי צו אָנדייטן אויך אויפן שכר (כפשוטו — של) הנשמה, וואָס קומט בדרך טפל ואינו תופס מקום לגבי יש המוחלט, ברענגט ער אויך דעם סיום הפסוק „ואוצרותיהם אמלא“.\nיא. ועוד יש לומר בזה:\nס׳איז ידוע⁶³ אַז לעתיד לבא וועט זיין הלכה כבית שמאי. וואָס איינער פון די ביאורים וואָס מען קען אין דעם זאָגן (ע״פ הנ״ל) איז:\nבזמן הזה ווען דער אדם פילט זיין מציאות, איז הלכה כבית הלל און מען זאָגט דעם אדם אַז זיין עבודה טוט אויף אַן עלי׳ אין אים; משא״כ לעתיד לבא ווען עס וועט זיין דער „ונגלה כבוד ה׳ וראו כל בשר יחדיו כי פי ה׳ דבר“⁶⁴ און אידן ווערן בפועל איינס זאַך מיטן „יש המוחלט“ און „מציאות התמידית“ — דעמאָלט וועט די מציאות האדם לגמרי ניט תופס מקום זיין, און דער גאַנצער אויפטו וועט באַשטיין בלויז אין „להנחיל אוהבי יש“.\nאון דערפאַר, ריב״ל גופא, וואָס רעדט וועגן דעם זמן דלעתיד, און אין דעם גופא — אין סיום המשניות (ווי מען שטייט לאחרי גמר העבודה — במצב דשלימות הצדיק) — זאָגט ער נאָר „עתיד הקב״ה להנחיל לכל צדיק וצדיק כו׳“:\nנאָר אַזוי ווי דער לימוד המשנה איז פאַרט בעוה״ב, ברענגט ער אויך דעם סיום הכתוב פון „ואוצרותיהם אמלא“, אַז דער אויבערשטער וועט אויך ממלא זיין די אוצרות של הצדיקים.\n(משיחות י״ט כסלו ומוצאי ש״פ וישב ומקץ תשל״ח)",[["61","61","תוי״ט כאן (מרע״ב אבות פ״ה מי״ט). — וע״פ המבואר בפנים מתורצת התמי׳ מה מוסיף „ואוצרותיהם אמלא“ בעוה״ז לגבי „להנחיל אוהבי יש“ (ש״י עולמות). וראה עוד ביאור בהתוועדות (ראה סה״ש תשמ״ט ח״ב ע׳ 733 ואילך), ש„ואוצרותיהם אמלא“ הוא למעלה מ„להנחיל אוהבי יש“ — כי קאי על אוצר של יר״ש, שאינו בידי שמים (ברכות לג, ב. וראה בחיי תבוא כח, נח), כ״א למעלה מבחי׳ „שמים“ (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380368\" data-slug=\"likkutei-torah\" data-id=\"4001380368\">לקו״ת במדבר טו, א</a>-ב). וראה גם סד״ה אריב״ל (הנ״ל הערה 43). ועפ״ז מבאר שם ג״כ למה שכר זה לא נתפרש בהמשנה."],["62","62","מכילתא (ורש״י) משפטים כב, ל. הובא בלקו״ת שם כח, ד."],["63","63","מק״מ לזח״א יז, ב. לקו״ת ד״ה ויקח קרח ספ״ד."],["64","64","ישעי׳ מ, ה."]]],[1300221070,"<h3>תזריע</h3>\nא. ס'איז א מנהג ישראל, אז ביים אריינברענגען א קינד לבריתו של אאע\"ה זיינען זיך משתתף א זוג „קוואטערס\" (איש ואשתו וכו'). די „קוואטערין\" ברענגט דעם קינד צום טיר פון ביהכנ\"ס (אדער חדר) וואו מ'איז מל דעם קינד, און דער „קוואטער\" נעמט פון איר דעם קינד און ברענגט אים צום „כסא של אליהו\"¹.\n„מנהג ישראל תורה היא\"² — איז מובן, אז אויך אט דער מנהג ביי אידן איז „תורה היא\"³.\nויש לומר, אז אויף דעם ענין — דאס וואס אן אשה (חאטש אויף איר איז ניטא די מצוה למול וכו' — כדלקמן) איז איינגעפירט בדוקא⁴ אז זי זאל מסייע זיין צו מצות מילה⁵, איז דא א כעין סמך ורמז⁶ בפרשתנו:",[["1","1","ראה מג\"א ס' תקנא סק\"ג. פמ\"ג שם. שערי תשובה שם. ובערוך השלחן יו\"ד סרס\"ה סל\"ה, ושם: ואשה מחזקת התנוק בכר או בכסת ובעלה לוקח מידה או בחור ובתולה והוא מוליכו למקום הכסא של אליהו. ובשו\"ת לבושי מכלול (להרי\"ה הובנער) ס' חי אות מם (הובאו דבריו בספר ברית אבות (מונקאטש תרנ\"ח) על הלכות מילה ס\"ה אות כח בסופו): עכשיו חולקין כבוד יותר להקוואטער גם לפעמים לובש בגדי שבת ושמעתי דנקרא כן מלשון כבוד טיער דכבודו אצל הפתח כו' — משום דמפזר ממון על הברי\"ם יותר מכל הכיבודין ע\"כ חולקים לו כבוד (בעלי' לתורה) ומנהג ישראל תורה הוא. וראה לקמן הערה 3."],["2","2","ראה תוד\"ה נפסל (מנחות כ, ב). ושם: מנהג אבותינו תורה היא. ועד\"ז במהרי\"ל הובא ברמ\"א שו\"ע יו\"ד סשע\"ו ס\"ד. ובמנהגים ישנים מדורא ע' 153 „והמנהג תורה היא\". וראה ירושלמי פסחים פ\"ד ה\"א."],["3","3","ע\"ד מקור מנהג זה — ראה רמ\"א יו\"ד סרס\"ה ס\"יא (ממהרי\"ל): ואין לאשה להיות סנדק לתינוק במקום שאפשר . . ומ\"מ היא עוזרת לבעלה ומביאה התינוק עד בית הכנסת ואז לוקח האיש ממנה ונעשה סנדק. ובמהרי\"ל הלכות מילה קרוב לסופו: האשה שהיא בעלת ברית ליטול הילד מהיולדת להוליכו לבית הכנסת להמול תוליכנו עד פתח בית הכנסת ולא תכנס אל תוכו להיות ג\"כ סנדיק לשם להמול הילד על ברכי' כו' ואמר דיש אנשים כשנעשו סנדיקין ואין נשותיהן עמהם הולכים בעצמם כו' (הובא גם במטה משה ח\"ז עניני מילה פ\"ד אות ה. ושם גם מתשב\"ץ (קטן) סשצ\"ז. וראה מטה משה שם סדר המילה וברכותי' בתחלתו). ועד\"ז בכללי המילה לר' יעקב הגוזר (ע' 64 בהוצאת ברלין תרנ\"ב: ירושלים תשל\"א) ונושא אותו אשת בעל ברית בהדר לביהכ\"נ. ומשמע דעצם המנהג מקורו מהשתתפות האשה בסנדקאות כאשת בעל הברית — סנדק (וראה גם מהרי\"ל שם. כללי המילה שם ע' 66. מטה משה שם (אות ג) הראי' שמביאין ממדרש תהלים (באבער) מזמור לה (וביל\"ש שם) „בברכי אני נעשה סינדיקנוס לילדים\", ועד\"ז באור זרוע הל' מילה סק\"ז. רוקח סק\"ח. ועוד). וכן משמע בלקט יושר (לתלמיד בעל תרומת הדשן) יו\"ד ע' נב (ברליז תרס\"ג), ושם נזכר מפורש „קבאטר\" (אלא שהכוונה שם לסנדק). וראה גם שו\"ת יוסף אומץ (להחיד\"א) ספ\"ה. כתר שם טוב גאגין ח\"ב סתרל\"ט, תרסא-ב (ושם גם בשורש ובפירוש המלה „סנדקות\". וראה גם הערות באבער למדרש תהלים שם)."],["4","4","להעיר מהשקו\"ט באיגוד לולב וטוית ציצית והטלתן ע\"י נשים (טושו\"ע (ודאדה\"ז) או\"ח ר\"ס יד (ס\"ב) ובנ\"כ שם. וש\"נ. מג\"א סתרמ\"ט סק\"ח, ובפרמ\"ג ומחצית השקל שם. וש\"נ)."],["5","5","ראה מג\"א שבהערה 1: הנשים רגילות ג\"כ ללבוש בגדי שבת היינו לפי שזה הוא עיקר מצותם. וראה מחצית השקל ושערי תשובה שם. וראה שו\"ת חת\"ס יו\"ד סי' קסב. ובמהרי\"ל שם: שהוא ואשתו תוך ל' לובשים בגדי שבת כשהן בעלי ברית. וראה בשאר ספרים שנסמנו בהערה 3 ולקמן הערה 17."],["6","6","להעיר משו\"ת הרשב\"א (ח\"א ס\"ט) — הובא לקמן בפנים — בכל דבר שיש קבלה ביד הזקנים והזקנות כו' רק שקבלו אותה דור אחר דור עד משה רבינו ע\"ה או עד הנביאים ופעמים יהי' הענין ההוא נרמז בכתוב."]]],[1300221071,"דער פסוק „וביום השמיני ימול בשר ערלתו\"⁷ — מצות מילה⁸ — שטייט אין דער פרשה פון „אשה כי תזריע⁹ (וילדה זכר)\", וועלכע רעדט וועגן „תורת היולדת גו'\"¹⁰ און בהמשך צו דעם פסוק אשה גו' עצמו גלייך נאך עם.\nהגם אז די מצוה פון „וביום השמיני ימול\" איז דער חיוב וואס ליגט על האב¹¹ (למול את בנו), משא\"כ אן אשה איז אין דעם ניט מחוייב, ווי די גמרא לערנט אפ¹² (ביז אז ס'איז דא א שקו\"ט און מחלוקת צי אן אשה איז כשרה למול¹³) — אעפ\"כ שטייט די מצוה אין דער פרשה וועגן א יולדת¹⁴, און וואו דער איש (בעל) ווערט גאר ניט דערמאנט (און אויך אין דעם פסוק גופא „וביום השמיני ימול בשר ערלתו\" שטייט ניט (בפירוש) אז דאס דארף טאן דער אב¹⁵).\nוואס דאס איז כנ\"ל, (עכ\"פ) א רמז אז אן אשה¹⁶ האט א שייכות צו מצות מילה, וואס דריקט זיך דירעקט אויס אין דעם וואס זי איז א קוואטערין ביי א ברית.\nב. בכמה מקומות איז ביי אידן דער מנהג¹⁷ ניט צו נעמען אן אשה מעוברת אלס „קוואטערין\" (ברענגען דעם קינד לביהכנ\"ס). און וויבאלד אז אזוי איז דער מנהג ישראל (בכו\"כ מקומות¹⁸), איז מובן, אז אויך דאס האט אן ארט און „תורה היא\" (וכתשובת הרשב\"א הידועה*¹⁸, אז אפילו א מנהג, קבלה ביד זקנים וזקנות כו' קען מען עס ניט דוחה זיין מיט קושיות וכו'¹⁹).\nאויף דעם מנהג (אז א מעוברת זאל ניט זיין קיין קוואטערין) ווערן געבראכט כמה טעמים²⁰ — צוליב סכנה, מחמת חשש עין הרע ועוד — אבער ע\"פ הידוע אינעם גודל הדיוק במנהגי",[["7","7","יב, ג."],["8","8","ובירושלמי (קידושין פ\"א ה\"ז) ילפינן מכאן המצוה למול את בנו. וכ\"ה במנין המצות שבריש ספר היד (ראה כס\"מ ריש הל' מילה). שאילתות אחרי ס' צג. חרדים (מ\"ע מה\"ת התלויות בראש הגוף) פ\"ז. סמ\"ג מ\"ע כח. ועוד. וגם להבבלי (קידושין כט, א) שילפינן זה מהכתוב־ (וירא כא, ד) „וימל אברהם את יצחק בנו\" [וברמב\"ם בסהמ\"צ מ\"ע רטו יליף מהכתוב בלך (יז, י־ד) הנאמר באברהם. ובחינוך (מצוה ב) למד מהכתוב בלך שם (ואת בריתי גו') וממשיך: ונפלה בסדר אשה כי תזריע דכתיב וביום השמיני גו'] — הרי כמה עיקרי דינים במילה ילפינן מהכתוב בפרשתנו (ראה שבת קל, א־ב. קלה, סע\"א. ועוד). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410117\" data-slug=\"likkutei-sichot\" data-id=\"1301410117\">לקו\"ש ח\"ל ע' 53</a> ואילך."],["9","9","להעיר שבכמה ספרים נקראת כן כל הסדרה („אשה כי תזריע\") ברמב\"ם הל' תפלה פי\"ג ה\"ב. סדר תפלות שלו. חינוך שם. ובהכותרת למצוה קסו. ובס' הרס\"ג קריאת התורה נק' „אשה\"."],["10","10","לשון הכתוב פרשתנו יב, ז."],["11","11","כ\"ה בירושלמי שם. סמ\"ג שם. חרדים שם. ועוד. וכן משמע בשאלתות שם. וברמב\"ם במנין המצות שם הלשון „למול את הבן\". וראה לשונו בריש הל' מילה שם, סהמ\"צ שם, ובשאר מקומות שבהערה 8. ואכ\"מ."],["12","12","קידושין שם."],["13","13","ראה ע\"ז כז, א. תוס' שם. טושו\"ע יו\"ד ר\"ס רסד ובנ\"כ שם."],["14","14","ראה הנסמן לקמן הערה 16. ולהעיר מתיב\"ע עה\"פ: וביומא תמינאי תשתרי וברא יתגזר בשר ערלתי'. וראה לקמן בסוף השיחה. וש\"נ."],["15","15","ראה רא\"ב עה\"פ. וראה מראה הפנים לירושלמי שם. תו\"ת כאן אות כה. לקו\"ש חי\"א שם (בהערה 26)."],["16","16","להעיר משו\"ת יוסף אומץ שם בנוגע אשה יולדת סנדק."],["17","17","כ\"ה בספר ברית אבות על הל' מילה ס\"ה אות כו („מרגלא בפומי דנשי\"), ושם הביא גם מלקוטי ספר. זוכר הברית (אונגוואר תרצ\"א) סי\"ט אות יג. ובמכתב עוז בתחלת הספר (מבעמח\"ס מנחת אלעזר)."],["18","18","צריך בירור א\"כ הוא בכל מקום. *18) נסמן לעיל הערה 6."],["19","19","ראה לשונו שם לפנ\"ז: שאין משגיחין בחקירה כנגד הקבלה."],["20","20","בספרים הנ\"ל (הערה 17). *) ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111052\" data-slug=\"likkutei-sichot\" data-id=\"1300111052\">לקו\"ש חי\"א ע' 44</a> ואילך הערה 19, 26."]]],[1300221072,"ישראל, איז מסתבר צו זאגן, אז דער מנהג איז ניט פארבונדן מיט א זייטיקער סיבה אדער חשש (מצד סכנה להעובר וכיו\"ב) נאר ער האט א שייכות און איז נוגע צום עצם ענין ומנהג פון קוואטער.\nוי\"ל — בנוגע צו טעמי המנהגים בכלל: פי' ודיוק הלשון „מנהג (ישראל) תורה היא\"²¹: א) דאס איז א זאך וואס האט א תוקף פון תורה ואין לשנות (ע\"ד „מנהג אבותינו בידינו\", „אל תשנו מנהג אבותיכם\"²²), ב) דער מנהג איז אויך א הוראה (תורה היא) אויפ'ן תוכן הענין המיוחד²³ (המצוה) אין וועלכן ער איז.\nג. ויש לומר הביאור בזה, ובהקדם: עד\"ז (ווי ס'איז דער מנהג הנ\"ל פון „קוואטער\" בא א ברית) געפינט מען אויך בא נשואי חתן וכלה (וואס תכליתם איז דער ענין פון פרו ורבו²⁴, הולדת בנים ובנות) — אז א זוג שושבינים²⁵ (אונטערפירער) פירן די חתן²⁶ וכלה צו דער חופה²⁷.\nאון אויך בא דעם איז מנהג ישראל אז אן אשה מעוברת זאל ניט זיין די אונטערפירערין²⁸.\nשטייט אין ספרים²⁸, אז די ביידע מנהגים בשייכות צו אן אשה מעוברת — אז זי זאל ניט זיין א „קוואטערין\" (ביי א ברית מילה) און ניט קיין „שושבינה\" (בא א חופה) — „חד מנהגא הוא\". עפ\"ז איז פארשטאנדיק, אז דער טעם פון די ביידע מנהגים איז אויך חד הוא.\nד. ויש לומר דער ביאור בפשטות²⁹:",[["21","21","ראה לעיל הערה 2."],["22","22","ראה ירושלמי פסחים שם."],["23","23","להעיר עד\"ז מההסברה במצות הוכיח תוכיח, דאי\"ז ענין ומצוה בפ\"ע, כ\"א פרט בכל מצוה והמצוה שעלי' מוכיח. ועד\"ז י\"ל בהמצות שמצד חינוך. ולהעיר גם מהשקו\"ט — באיסורי דרבנן (שישנם באיסורי תורה) אם הוי עליהם שם האיסור דאורייתא או איסור דרבנן בפ\"ע השווה בכולם. ועד\"ז בחצי שיעור אם הוה לכל אחד שם בפני עצמו או הוא הוי דין אחד בכל האיסורים (ראה בכל הנ\"ל צפע\"נ הל' איסורי ביאה פ\"א ה\"ח. וראה שם הל' שבת פ\"א ה\"ד. ועוד). ועד\"ז באיסור לפני עיור (ראה שו\"ת צפע\"נ (ירושלים תשכ\"ה) סי' ה, וש\"נ). ראה בכהנ\"ל לקוטי ביאורים (להרי\"ש' קארף) ח\"ב ע' פב ואילך. וש\"נ. ואכ\"מ."],["24","24","עד שלדעת כמה הטעם שאין מברכין שהחיינו בנישואין מפני שתכליתם פו\"ר (ראה אנציקלופדי' תלמודית ע' ברכת הזמן ע' תמג, וש\"נ). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171174\" data-slug=\"likkutei-sichot\" data-id=\"1300171174\">לקו\"ש חי\"ז ע' 174־5</a> ובהנסמן שם."],["25","25","להעיר ממדרש חזית הובא במהרי\"ל הל' מילה שם (רוקח שם. ספר כללי המילה שם ע' 66) הקב\"ה נעשה שושבין (לאברהם אבינו ותפס לו כבעל ברית כו') שנאמר (נחמ' ט, יח) וכרת עמו הברית. וראה מדרש הגדול ס\"פ לך: תלתא שושבנין הו' לאברהם ענר כו'. ולהעיר ממטה משה שם אות ד: מצאתי כתיב מעשה שבקשו לחסיד להיות בעל ברית ולהיות שושבין לחתן אמר כו'."],["26","26","ראה ראב\"ע שמות ד, כה: ומנהג הנשים לקרוא לבן כאשר יומל חתן. ובכללי המילה (שם ע' 64) ומלבישו לו לקטן כמו\"כ בגדים נאים כו' כיום חתונתו. ועד\"ז במט\"מ שם: ואח\"כ מלבישין הילד מעיל כחתן כי נקרא חתן שנאמר חתן דמים למולות, ולוקח אותו האשה שהיא בעלת ברית כו'."],["27","27","להעיר מפרדס (שער כג פ\"ח — ע' חופה בסופו): והת\"ת והמלכות חתן וכלה בתוך חופתם ע\"י היסוד שהוא השושבין. וראה קה\"י ע' שושבינים וע' שושבינין."],["28","28","כ\"כ המנחת אלעזר במכתב עוז שם."],["29","29","הביאור בהשיחה לא בא לקבוע ולהכריח שכצ\"ל המנהג שמעוברת לא תהי' שושבינה או קוואטערין, כ\"א רק להסביר טעם המנהג — לדעת אלה שנוהגין כן. לא עלתה בידי לברר מנהג חב\"ד בזה. — והרי צער גדול הוא לאם המעוברת שלא תהי' שושבינה בחתונת בנה או בתה וכיו\"ב (וגם — מילתא דתמי' רבתי). משא\"כ באם תסובב גם היא (ובעלה) את החו\"כ ועוד זוג (נוסף על הורי הכלה). וכלפי שמיא גליא מי מהם בגדר שושבינים ממש."]]],[1300221073,"מען געפינט אין שו\"ע³⁰ בקשר צום „מנהג כפרות בערב יום כפור\"³¹, אז (בנוסף צו דער תרנגולת לכפרה פאר זיך) נעמט אן אשה מעוברת אויך א תרנגול לכפרה פארן עובר. ס'איז נאר וואס אין דעם גופא זיינען פאראן צווי דיעות, צי ס'איז גענוג תרנגול אחד ותרנגולת אחת, ווייל אויב דער עובר איז א נקבה איז גענוג איין תרנגולת פאר דער מוטער און דעם עובר צוזאמען³² (וואָרום צווי אנשים מתכפרים דורך איין תרנגול און צווי נשים — דורך איין תרנגולת³³); אָדער מ'דארף האבן דריי עופות — צווי תרנגולות און איין תרנגול: איין תרנגולת פאר דער מוטער, און א תרנגול ותרנגולת³⁴ „בשביל ספק הולד\"³⁵.\nאון אזוי איז דער מנהג, ווי דער מנהג האריז\"ל³⁴ אז א מעוברת נעמט דריי עופות³⁶.\nעפ\"ז איז מובן בעניננו — די צווי מנהגים הנ\"ל בקשר צו אן אשה מעוברת:\nמנהג ישראל איז, אז סיי די שושבינין פון חתן וכלה סיי די קוואטערס ביי א ברית מילה — זאלן זיין דוקא צווי — אן איש ואשה (אדער צווי פון יעדערן)³⁷. און דערפאר איז דער מנהג ישראל ניט צו נעמען אן אשה מעוברת, ווייל דאמאלס איז דא נאך איינער — הולד (והראי', דער ולד דארף האבן א כפרה פאר זיך); ובמילא קומט אויס אז דא זיינען דריי שושבינין אדער קוואטערס, און עס איז אויך ניט בשווה³⁸ מספר האנשים והנשים, וואס עס קען זיין אז אויך דאס איז נוגע.\nה. לכאורה קען מען אויף דעם פרעגן: די אונטערפירערין אדער קוואָ־",[["30","30","או\"ח סתר\"ה ואדה\"ז שם ס\"ג."],["31","31","כ\"ה הכותרת דהסימן בשו\"ע (ודאדה\"ז) שם."],["32","32","כ\"ה במהרי\"ל הל' ערב יו\"כ. הובא בב\"ח שם. מט\"מ ח\"ה סי' תתלח. וכן הוא ברמ\"א שם (ע\"פ פירוש המג\"א ופרי\"ח שם). לבוש שם. ועוד."],["33","33","כן מפורש בלבוש, מג\"א ואדה\"ז שם. וצ\"ע בביאור הגר\"א שם דמבאר דברי הרמ\"א בנוגע לעובר נקבה — „דקיימא לן עובר ירך אמו\" (וראה גם פרמ\"ג (א\"א) שם). — דלכאורה, א\"כ למה צריכה ליקח תרנגול בפ\"ע אולי תלד זכר ולא אמרינן בזה עובר ירך אמו? ראה דעת תורה למהרש\"ם שם. ואולי כוונתו ע\"ד המבואר לקמן בפנים סעיף ו. ואכ\"מ."],["34","34","דעת האריז\"ל הובאה במג\"א שם משל\"ה (רלו, ריש ע\"ב)*. דיעה הב' בשו\"ע אדה\"ז שם. ובב\"ח שם: מצאתי העתק ממרדכי קטן עוברות צריכות ג' כפרות. וכן משמע בדרכי משה שם (אות ב): ועוד נוהגין ליקח למעוברות ב' תרנגולות ותרנגול א' מספק שמא תלד בן או בת\"י**. וכ\"כ באלי' זוטא שם (סק\"ד) ואלי' רבה שם (סק\"ח). *) כ\"ה בשער הכוונות דרושי יו\"כ בתחלתו. פע\"ח שכ\"ז פ\"א. סידור האריז\"ל — להר\"ש מרשקוב — (ערב יו\"כ סדר כפרות). סי' קול יעקב. **) ומה שהביא ממהרי\"ל הוא רק על עצם הענין „ליקח כפרה לעובר\", כמפורש בלשונו."],["35","35","לשון אדה\"ז בסידורו בסדר כפרות (ולא הביא שם דיעה הא'). וראה דיוק הלשון במקומות הנ\"ל, ובשער הכוונות, סידור האריז\"ל, פע\"ח ושל\"ה שם."],["36","36","לא חיישינן לתאומים (כמ\"ש הב\"ח שם ממרדכי קטן. פמ\"ג שם) — כיון דמיעוטא הוא והמדובר הוא במנהג. וצ\"ע בזמננו דלפעמים רבות יודעים ברור אשר „תאומים בבטנה\", ועל בירור זה סומכים בנוגע לפקו\"נ בשבת ויהכ\"פ וכיו\"ב — איך תתנהג ב„כפרות\", או שנאמר דכיון דלא שכיחא כו', ובפרט בנדו\"ד דבלאה\"כ י\"א לפטור כמה זכרים בתרנגול א' כו'."],["37","37","בנוגע לקוואטער — ראה הערה 1, 3. ולהעיר מלשון הטור סי' רסה (מרב צמח גאון) ובפרישה שם סק\"כ. ובנוגע לשושבינים — קהלת יעקב הנ\"ל. וברמ\"א יו\"ד סי' שצא ס\"ג: כדרך ארצנו ששני אנשים מכניסין החתן תחת החופה."],["38","38","גם להגר\"א בשו\"ע שם (הנ\"ל הערה 33)."]]],[1300221074,"טערין איז די מוטער (ניט דער עובר) — מיט וואס איז דאס אנדערש ווי ווען עס שטייען אונטער דער חופה נאך ווער, וואס מען איז ניט מקפיד אויף דעם.\nאיז דער חילוק בפשטות: די אנדערע זיינען דארט ניט אלס שושבין אדער קוואטער. משא\"כ דער עובר, וואס איז א טייל פון דער מוטער, איז ער אויך במילא אלס (א טייל פון) קוואטער אדער שושבינה.\n[ולהעיר עד\"ז אין הלכה³⁹: דער דין „נמצא א' מהם קרוב או פסול עדותן בטילה\" איז דוקא ווען זיי זיינען פאראייניקט אלע אלס עדות — „נתכוונו כולם להעיד\", אדער אז זיי זיינען (אויך) געקומען אין ב\"ד להעיד; אבער ווען דער קרוב או פסול האט בשעת הראי' ניט מכוין געווען להעיד וכיו\"ב, איז עדותן (פון די אנדערע כשר\"ע עדות) ניט בטילה, ווייל דער קרוב או פסול זיינען ניט אין דעם גדר פון אן עד].\nוא\"ו. כד דייקת שפיר אין דעם ענין הנ\"ל י\"ל עוד: פון מנהג כפרות הנ\"ל בנוגע אן אשה מעוברת, איז מובן —\nניט אז דער עובר ווערט פארעכנט אלס א באזונדערע מציאות — וואָרום אויב אזוי איז ניט פארשטאנדיק: וואס פאר א „כפרה\" (וכיו\"ב)⁴⁰ דארף האבן אן עובר במעי אמו? — נאר\nאז דער עובר איז משנה מציאות אמו, מוסיף אין איר מציאות באופן אז זי אליין ווערט גערעכנט ווי צווי (דריי), און דעריבער דארף איר כפרה (אלס אן אשה מעוברת) באשטיין פון צווי (און לויט דער צווייטער דיעה, מצד דעם ספק, פון דריי) עופות.\nוי\"ל הסברה בזה: ווען די מעוברת האט געגעסן דבר האסור און עס איז געווארן דם ובשר מבשרה און צריכה כפרה — איז אכילתה געווארן דם כו' פון לב האשה און פון לב העובר וכו'.\nבסגנון אחר, כולל יותר: טאן א זאך וואס צריך כפרה קומט ע\"י האדם וועלכער באשטייט פון אלע זיינע אברים וכו' וכולם מתכפרים. און אויב דאס איז אן אשה מעוברת האט זי אויך כל חלקי העובר בתוכה (נאך אידער א) ירך שזוקקים לכפרה.\nדאס הייסט, אז דאס וואס זי נעמט א תרנגול שמא תלד זכר, איז ניט דערפאר ווייל דער תרנגול איז א כפרה פאר דעם עובר (טאמער איז ער א זכר), נאר דורך דעם וואס „תלד זכר\" איז איגלאי מילתא אז זייענדיק א מעוברת איז איר מציאות געווען אזא, וואס פאדערט אויך א תרנגול לכפרתה⁴¹.\nועפ\"ז איז מובן, אז דאס וואס מ'נעמט ניט קיין אשה מעוברת אלס שושבינה אדער קוואטערין, איז ניט ווייל דער עובר (פאר זיך) איז א דריטער (שושבין אדער קוואטער), נאר ווייל די אשה מעוברת עצמה ווערט גערעכנט מער ווי אשה אחת, וכנ\"ל.",[["39","39","ראה טושו\"ע חו\"מ ר\"ס לו ובנ\"כ שם."],["40","40","ראה מהרי\"ל ומט\"מ שם: כשאוחז התרנגול בידו להתכפר בו. וראה השקו\"ט באלי' זוטא ואלי' רבה וביאורי הגר\"א שם דהוי דוגמת קרבן חובה (וראה מחה\"ש ופרמ\"ג שם). וראה מטה אפרים שם ס\"ה. [וראה שו\"ע אדה\"ז שם ס\"א, מרמ\"א ולבוש: וסומכין עליו ידיהם דוגמת סמיכה בקרבן (ומוסיף אדה\"ז מלבוש שם) ושוחטין אותו מיד דתיכף לסמיכה שחיטה]. ובסידור אדה\"ז מכתבי האריז\"ל ושל\"ה הנ\"ל שם: ונקרא כפרה כמו שעיר המשתלח, ע\"ש."],["41","41","ולהעיר מהשקו\"ט בגדר עובר ירך אמו (בהנסמן בביאור הגר\"א שם. שד\"ח כללים מע' ע' כלל סב. צפע\"נ לסנהדרין פ, ב. בתוד\"ה עובר. דעת תורה שם). ואכ\"מ."]]],[1300221075,"ז. עס פאדערט זיך אבער נאך ביאור, וואס מ'איז מדייק צו נעמען אן איש ואשה דוקא:\nבשלמא ביי שושבינין דחתן וכלה י\"ל אז דאס איז כנגד החתן והכלה⁴²; אבער וואס איז דער דיוק צו נעמען דוקא אן איש ואשה ביי קוואטער (דברית מילה)?\nוכנ\"ל (סוף סעיף ב) איז מסתבר, אז דער דיוק האט א שייכות („תורה\") צום תוכן ענין פון מילה.\nוי\"ל (בדא\"פ) בהקדם ביאור הענין פון שושבינין ביי א חתן וכלה:\nענינם פון שושבינין בפשטות איז⁴³: היות אז חתן וכלה זיינען ביז איצט געווען פרעמד און וויט איינער פון צווייטן, און דערפאר איז פאר זיי שווער (מצד הבושה וכו') צו איבערשטעלן זיך מיטאמאל אין א מצב פון קירוב וכו' ביי זייער חתונה — דעריבער דארפן זיי האבן דעם סיוע פון שושבינין, וועלכע זיינען רעים⁴⁴ צו דעם חתן און צו דער כלה, כדי זיי תומך זיין, מחזק און מעודד זיין אין דעם קירוב זל\"ז.\nאון דאס איז דער טעם אויפן מנהג ישראל אז די שושבינין זאלן זיין אן איש ואשה — און א זוג נשוי — וואָרום ס'איז מובן ופשוט, אז אויף צו מעודד זיין דעם חתן איז מתאים אן איש, און א נשוי, וועלכער איז שוין דורכגעגאנגען ענין הנישואין: ועד\"ז די שושבינה פאר דער כלה — אן אשה נשואה.\nח. אלע ענינים דלמטה ווערן נשתלשל פון זייער שורש למעלה — עד\"ז בעניננו:\nדער ענין פון שושבינין דאיש ואשה בא א חתן וכלה דא למטה, נעמט זיך דערפון וואס אזוי איז דאס געווען בא חתן וכלה בשרשם ועיקרם — די נישואין פון הקב\"ה (כביכול) מיט אידן⁴⁵, ביום חתונתו זה מתן תורה⁴⁶, זיינען געווען⁴⁷ דערביי צווי שושבינין: שושבינא דמלכא — משה, שושבינא דמטרוניתא — אהרן⁴⁸:\nמשה איז דער שושבין מצד החתן — ער איז מקרב און ממשיך אלקות מלמעלה למטה צו אידן (בדוגמא, כביכול, ווי דער שושבין של החתן וועלכער פירט דעם חתן צו דער כלה); און אהרן איז דער שושבין מצד הכלה — ער איז מעלה און מקרב אידן מלמטה למעלה, ביז אז זיי זאלן נתייחד ווערן מיטן אויבערשטן (בדוגמא צו דער שושבינה פון",[["42","42","ראה כתובות יב, א. וראה קה\"י הנ\"ל."],["43","43","בכל הבא לקמן ראה תו\"א פא, א. אוה\"ת תצוה ע' א'תקסג ואילך. וש\"נ."],["44","44","„בפרשב\"ם פ\"ט דב\"ב דף קמ\"ד ע\"ב הביא דמתרגמינן בש\"ב סי' טז טז רעה דוד שושבינא דדוד\" (אוה\"ת שם). וראה סנהדרין פ\"ג מ\"ה ובפיה\"מ להרמב\"ם שם."],["45","45","וכל שיר השירים מיוסד ע\"ז, כידוע במדרשי חז\"ל."],["46","46","שה\"ש ג, יא (פרש\"י שם). תענית כו, ב במשנה. וראה פרש\"י יתרו (יט, יז) ממכילתא: לקראת האלקים, מגיד שהשכינה יצאה לקראתם כחתן היוצא לקראת כלה. ובכ\"מ במדרשי חז\"ל."],["47","47","ראה מט\"מ חלק ג' בהכנסת כלה (פ\"א סוף אות א): ועוד שכל המנהגים של חתן וכלה אנו למדין ממ\"ת שהשם הי' מראה עצמו כחתן נגד כלה שהם ישראל כמוש\"כ התשב\"ץ סי' תסז. ולכך מכניסין אותם תחת החופה כויתיצבו בתחתית ההר. ובתר\"א (צח, סע\"ד) מתרץ עפ\"ז למה שינו הסדר להקדים חופה לקידושין. וראה מט\"מ שם (ריש אות ב) הנהגות בשושבינים „זורקין נרות דולקות כו' רמז למ\"ת שנאמר (יתרו יט, טז) ויהי קולות וברקים\". ועוד."],["48","48","ראה זח\"א רסו, ב. ח\"ב מט, ב. ח\"ג כ, א (ברע\"מ). נג, ב. ערה, ב. וראה (ובהבא לקמן) עד\"ז החסידות בהנסמן לעיל הערה 43. אוה\"ת משפטים ע' א'שח ואילך. ספר הערכים חב\"ד ח\"ב ע' כז ואילך, לז ואילך, וש\"נ."]]],[1300221076,"דער כלה, וועלכע פירט איר צום חתן)⁴⁹.\nאון דער צורך פון די שושבינין ביי דעם יחוד פון הקב\"ה מיט אידן איז מפני זה וואס די נשמה פון א אידן, איז ירדה בריחוק גדול מאיגרא רמא לבירא עמיקתא אינעם העלם והסתר פון וועלט, און עס איז דא דער הרגש הבושה והיראה (בעת הקירוב) פון גדלות הא־ל, דער רוממות פון דעם אויבערשטן.\nאון דעריבער דארף מען האבן א שושבין מצד ה„כלה\", מצד אידן, וואס מדריגתו וענינו ופעולתו איז בחי' אשה (עושה רצון בעלה) — צו מעלה זיין די אידן צום אויבערשטן; און א שושבין מצד החתן, וואס מדריגתו וענינו ופעולתו איז בחי' איש (והוא ימשול בך) — צו ממשיך זיין אלקות מלמעלה למטה צו און אין אידן.\nט. און דאס איז אויך דער טעם וואס די שושבינין זיינען פארבונדן מיט דער שמחה בעת הנישואין⁵⁰, וואָרום⁵¹ דער ענין השמחה נעמט זיך דערפון וואס עס טוט זיך אויף א דבר חדש — און דאס איז דאך דער ענין פון א חתונה; ווען אן איש און אשה, וועלכע זיינען געווען אפגעטיילט און וויט איינער פון צווייטן זינט זיי זיינען געבארן (וואָרום בעצם איז דאך יעדער איינער א פלג גופא⁵²) — און די שושבינין ברענגען זיי צוזאמען, צו א קירוב ויחוד — רופט עס אריס א שמחה נפלאה.\nועד\"ז ברוחניות הענינים: מצד ירידתה למטה, איז די נשמה געווארן (כאילו ווי) נפרד ורחוק פון דעם מצב און דרגא פון איר יחוד ודביקות מיטן אויבערשטן, ווי די נשמות בהיותן למעלה; און ווען אידן ווי זיי געפינען זיך למטה ווערן דבוק ומיוחד מיטן אויבערשטן דורך תורה ומצות (און זיי זיינען מברר ומעלה די ענינים הגשמיים, די ניצוצות הקדושה וואס ירדו ממדרגתם ונתרחקו און געפינען זיך למטה אין זיי) — ווערט דורכדעם אויפגעטאן א שמחה נפלאה.\nוי\"ל אז דאס איז דער טעם וואס מתן תורה ווערט אנגערופן „יום חתונתו וביום שמחת לבו\"⁵³: פאר⁵⁴ מ\"ת איז געווען די גזירה אז „עליונים לא ירדו לתחתונים ותחתונים לא יעלו לעליונים\"*⁵⁴; און במ\"ת, ווען עס איז געווען די חופה וקידושין⁵⁵ פון דעם אוי־",[["49","49","ראה עירובין יח, ריש ע\"ב: ויביאה אל האדם מלמד שעשה הקב\"ה שושבינות לאדה\"ר מכאן לגדול שיעשה שושבינות לקטן. וראה פרש\"י שם (ובברכות (סא, א) ואבות דר\"נ (פ\"ד, ד בסופו): שושבין. ובשינוי לשון קצת). וראה ב\"ר רפ\"ח. ולכאורה באדה\"ר לא הי' שייך הענין דריחוק מקום (שהרי הי' עצם מעצמי — בראשית ב, כג) — ראה לקמן בפנים, ולא בושה (דולא יתבוששו — שם, כה), ועכצ\"ל שהיא שושבינות מסוג אחר (ראה בנין יהושע לאדר\"נ שם). ובב\"ר פ\"ח, יג: מיכאל וגבריאל הם היו שושבינין של אדם הראשון. ובפדר\"א ספי\"ב: והיו מלאכי השרת כמו שושבינים המשמרים את החופות, וברד\"ל שם (אות נח) שהוא\"ע אחר בשושבינין."],["50","50","ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370493\" data-slug=\"torah-or\" data-id=\"3901370493\">תו\"א קיא, א</a> ואילך. המשך זאת חנוכת המזבח תר\"מ פ\"י (ס\"ע יג ואילך)."],["51","51","ראה גם מאמרי אדה\"ז — אתהלך לאוניא בתחלתו ד\"ה ענין הילולא דרשב\"י."],["52","52","זח\"ג ז, ב. קט, ב. רצו, א. וראה יבמות (סג, א): אינו אדם (לכאורה ה\"ז עוד פחות מ„פלג גופא\")."],["53","53","ראה תו\"א פא, א. ובמשנה תענית שם זה בנין בית המקדש (שבו הי' השלימות דושכנתי בתוכם). וראה אוה\"ת תצוה ע' א'תרנט."],["54","54","והסדר: בתחלה כלולים עליונים ותחתונים במציאות אחת ואח\"כ ויבדל גו' ועד מ\"ת כו'. *54) תנחומא וארא טו."],["55","55","ראה במדב\"ר פי\"ב, ח בסופו. תו\"א שבהערה 47."]]],[1300221077,"בערשטן מיט אידן, איז בטל געווארן די גזירה, עס איז געווארן דער חיבור ויחוד פון דעם אויבערשטן מיט אידן ווי אידן געפינען זיך אין וועלט דא למטה, (ועל ידם מיט כל עניני העולם), און דערפאר איז דאס — „שמחת לבו\".\nיו\"ד. ע\"פ כל הנ\"ל איז אויך מובן דער תוכן ענין פון קוואטער בא א ברית מילה, און שייכותו צו דעם ענין השושבינין בא א חתונה:\nדי שלימות ופנימיות ענין היחוד פון דעם אויבערשטן מיט אידן ווערט אויפגעטאן דורך ברית מילה; דעמאלט טוט זיך אויף דער ענין פון „בריתי בבשרכם לברית עולם\"⁵⁶, אז דער ברית פון א אידן מיטן אויבערשטן איז חתום אין בשר הגשמי פון א אידן.\nד.ה. אט דער חידוש פון מ\"ת, טוט זיך אויף באופן גלוי בא ברית מילה, אז „עליונים\" (רוחניות) זיינען יורד „למטה\", און „תחתונים\" (גשמיות) זיינען עולה למעלה, ביז אז דער גוף הגשמי פון א אידן ווערט, כביכול, בברית מיט דעם אויבערשטן.\n[וואָרום דער קישור וחיבור פון אידן מיטן אויבערשטן דורך אנדערע מצות — וואס יעדער מצוה איז (מלשון) צוותא וחיבור⁵⁷ — איז ניט ניכר אויף אזוי פיל אין דעם גוף האדם וואס איז מקיים א מצוה ווי דאס איז ביי דער מצוה פון מילה⁵⁸].\nוואס דאס גיט אויך א תוספת ביאור אין דעם וואס דער אלטער רבי זאגט אין שולחן ערוך⁵⁹, אז „תחלת כניסת נפש זו הקדושה\" איז „במצות מילה\"⁶⁰.\nאון דעריבער כשם ווי די שושבינין בא חתן וכלה זיינען אן איש ואשה, ווייל ענינם איז צו מסייע זיין אין דעם קירוב ויחוד — דער שושבין מצד החתן און די שושבינה מצד הכלה — עד\"ז איז אין שרש הענין פון חיבור פון איש ואשה, אין דעם יחוד פון דעם אויבערשטן מיט אידן, וואס קומט בגלוי בא א ברית מילה, דריקט זיך דאס אויס (לויט דעם מנהג ישראל) אין די קוואטערס (כעין שושבינין) וואס באשטייען פון אן איש ואשה, וואס בתוכנם וענינם ברוחניות איז איש מרמז אויף דעם שושבין מצד המלך, מצד דעם אויבערשטן, און אשה — אויף שושבינא דמטרוניתא, מצד די אידן.\nאון דעריבער דארפן אויך ביי ברית מילה זיין (אזוי ווי שושבינין ביי א חתונה) דוקא אן איש און א אשה.\nיא. עפ\"ז איז אויך מובן פארוואס שמחה איז אן ענין עיקרי ביי ברית מילה (פונקט ווי דאס איז ביי א חתונה), וואס מ'געפינט דאס ניט אויף אזוי פיל ביי אנדערע מצות וכדרז\"ל⁶¹ אז שש אנכי על אמרתך מיינט עס מצות מילה (כאטש עס דארף זיין בא יעדער מצוה „עבדו את ה' בשמחה\"⁶²) ביז אז די גמרא⁶³ זאגט, אז דאס איז דער טעם וואס מ'איז מל לשמונה „מפני מה אמרה",[["56","56","לך יז, יג."],["57","57","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380272\" data-slug=\"likkutei-torah\" data-id=\"4001380272\">לקו\"ת בחקותי מה, ג</a> ובכ\"מ."],["58","58","להעיר מתניא קו\"א רד\"ה להבין מ\"ש בפע\"ח."],["59","59","או\"ח מהדא\"ת סוס\"ד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201246\" data-slug=\"likkutei-sichot\" data-id=\"1300201246\">לקו\"ש ח\"כ (ע' 246־7</a>) המקור לזה."],["60","60","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101045\" data-slug=\"likkutei-sichot\" data-id=\"1300101045\">לקו\"ש ח\"י ע' 45</a> ואילך."],["61","61","שבת קל, א ובפרש\"י ותוס' שם ד\"ה שש. ועייג\"כ מגילה טז, ב. כתובות ח, א. ועוד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071318\" data-slug=\"likkutei-sichot\" data-id=\"1300071318\">לקו\"ש ח\"ז ס\"ע 306</a> ואילך."],["62","62","תהלים ק, ב. וראה רמב\"ם סוף הל' לולב."],["63","63","נדה לא, ב. ובמדרש לק\"ט פרשתנו עה\"פ."]]],[1300221078,"תורה מילה לשמונה שלא יהו כולם שמחים ואביו ואמו עצבים\" (און ווי פארשטאנדיק פון מפרשים⁶⁴, לערנט מען דאס אפ פון דעם וואס די תורה שטעלט אריין „וביום השמיני ימול בשר ערלתו\" בפרשתנו גלייך נאך דעם וואס דער פסוק פירט אויס וועגן טומאת לידה שמסתיימת בשבעת ימים),\nוואָרום דער ענין השמחה וואס ווערט מצד אן ענין פון התחדשות, ווי ביי חתונה וואס ווערט אויפגעטאן א דבר חדש, אז יעזוב⁶⁵ איש את אביו גו' ודבק באשתו והיו לבשר אחד, כנ\"ל, איז דאס בשלימות ביי מצות מילה, וואס עס טוט זיך אויף דער פנימיות'דיקער חיבור ויחוד (איש ואשה) דעם אויבערשטן מיט אידן, בריתי בבשרכם לברית עולם.\n[וי\"ל אז בא אן אשה איז אדרבא — וויבאלד אז „כמאן דמהילא דמיא\"⁶⁶ ווערט דאס אויפגעטאן גלייך בא דער לידה]⁶⁷\nאון דורך דעם קיום פון די ביידע מצות הנ\"ל — פו\"ר (וואס איז דער תכלית פון חתונה — נשואי איש ואשה) און מצות מילה — איז מען זוכה בקרוב ממש צו דער גאולה האמיתית והשלימה וועט עס זיין די שלימות אין מילה — „ומל⁶⁸ ה\"א את לבבך ואת לבב זרעך\" און די שלימות ב„נישואין (פון אידן מיטן אויבערשטן) שנאמר⁶⁹ כי בועליך עושיך⁷⁰, און דעמאלט וועלן זיין די שושבינים — „משה ואהרן יהא עמנו\"⁷¹.\n(משיחות חמשה עשר בשבט וש\"פ יתרו ה'תשמ\"א)",[["64","64","ראה חדא\"ג שם. וראה כלי יקר ואוה\"ח ריש פרשתנו. ועוד. וראה מפרשי העו\"ש שם."],["65","65","בראשית ב, כד."],["66","66","ע\"ז כז, א."],["67","67","ועפ\"ז יובן הצורך שגם „אביו ואמו יהיו שמחים ולא יהיו עצבים\", אף שהעצבות שלהם אינה שייכת למצות מילה, כ\"א לפי שאסורין בתשמיש (פרש\"י נדה שם). כי מכיון שתוכן ענין המילה „החתונה\" היחוד דאיש ואשה, הקב\"ה עם בנ\"י, הרי צריך שיהי' גם כן באיש ואשה למטה, שלימות ענין הנישואין („ודבק באשתו והיו לבשר אחד\" — בראשית ב, כד) בהולדת בנים ובנות."],["68","68","נצבים ל, ו. וראה אגה\"ק ס\"ד."],["69","69","ישעי' נד, ה."],["70","70","שמו\"ר ספט\"ו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381320\" data-slug=\"likkutei-torah\" data-id=\"4001381320\">לקו\"ת שה\"ש מח, א</a>-ב. ועוד."],["71","71","תוד\"ה אחד (פסחים קיד, סע\"ב). וראה יומא ה, ב."]]],[1300221079,"<h3>תזריע ב</h3>\nא. אין אנהויב פון פרשת נגעי אדם שטייט¹): „אדם כי יהי׳ בעור בשרו גו׳”. דער פסוק נוצט דא דעם תואר „אדם”, וואס איז דער שם המעלה פון אידן (און דער העכסטער תואר פון די פיר תוארים אדם איש גבר אנוש)².\nאיז ידוע די שאלה³: ווי קומט עס, אז בשעת מ׳האלט ביי דער דרגא פון „אדם” זאל ביי אים זיין „בעור בשרו שאת גו׳”, נגעים — וואס טומאת צרעת איז פון די טומאות הכי חמורות⁴, און חז״ל⁵ זאגן אז „מצורע חשוב כמת”?\nאיז מבאר דער אלטער רבי⁶, אז היא הנותנת: דוקא דערפאר וואס עס רעדט זיך וועגן איינעם וואס איז אין דער דרגא פון „אדם” — וואס איז א „מדריגה גדולה . . שלימו דכולא” — איז ער לוקה בצרעת:\nדער ענין הנגעים „בעור בשרו” ווייזט, אז דער רע וואס איז גורם דעם נגע (ובמילא — דארף ער זיין בדוגמתו) איז ניט אין (דער פנימיות פון) דעם מענטשן\n[דער אלשיך⁷ איז מבאר, אז ביי רשעים, וואס „עיקרן טומאה”, מאכט ניט",[["1","1","פרשתנו יג, ב."],["2","2","זהר פרשתנו (מח, רע״א. ובכ״מ). וראה ספר הערכים חב״ד כרך א ערך אדם סעיף ט. וש״נ."],["3","3","ראה זהר שם. אלשיך ריש פרשתנו. וראה לקו״ת פרשתנו כב, ב (ובהגהות לשם באוה״ת ויקרא ע׳ רנב)."],["4","4","דמחוץ למחנה מושבו, מחוץ לג׳ מחנות, ולא יהו (אפילו) טמאין אחרין יושבין עמו (פרשתנו יג, מו. תו״כ ורש״י עה״פ. פסחים סז, א)."],["5","5","נדרים סד, ב."],["6","6","לקו״ת פרשתנו שם. סד״ה אדם כי יהי׳ תרס״ו, תרע״ה. וראה בכ״ז גם אלשיך שם."],["7","7","שם. אן עוון א רושם ביז עס זאל זיין ניכר „בעור בשרו”, ווייל „מין במינו אינו חוצץ”], נאר עס איז בלויז וואס ס׳איז פאר־בליבן „פסולת” ורע אין זיין חיצוניות — „בסוף לבושיו”, און דערפאר ווערט דערפון א נגע „בעור בשרו” (דוקא). דערמיט איז דער אלטער רבי אויך מבאר⁸ פארוואס „מצות נגעים אינו נהוג בזמננו זה אחר החורבן מפני שאינן מצויין כלל כו׳ אך מעשה נסים הם” (ווי ער ברענגט פון רמב״ם⁹) — ווייל ס׳איז „אינו בנמצא אצלינו” אזעלכע וואס זאלן ניט האבן קיין רע בפנימיות, „שאף הצדיק והטוב עדיין הרע קצת בפנימיות”, ובמילא איז דער רע ניט גורם קיין נגעים. ב. דארף מען פארשטיין: חז״ל זאגן¹⁰ אז דער ענין הנגעים קומט אלס עונש אויף חטא לשון הרע, וואס איז א חטא חמור ביותר, ביז ער איז שקול כנגד די ג׳ עבירות וואס „יהרג ---"],["8","8","ראה גם אלשיך שם (אבל לא הביא דברי הרמב״ם)."],["9","9","סוף הלכות טומאת צרעת (ראה סד״ה אדם כי יהי׳ הנ״ל (הערה 6), שהכוונה בלקו״ת היא למ״ש הרמב״ם בהלכה זו „אינו ממנהגו של עולם אלא אות ופלא הי׳ בישראל”. ומש״כ בלקו״ת „כמ״ש הרמב״ם” קאי אלפניו „שאינם מליחות המצוים”, ולאח״ז מבאר „שמצות נגעים כו׳ אינם מצויים כלל כו׳” — אבל מפורש ברמב״ם (הל׳ טומ״צ פי״א ה״ו) דנוהגת בפני הבית ושלא בפני הבית. — וראה תו״ש שמות מילואים סח״י הדעות בזה. — וראה פיה״מ נגעים פי״ב מ״ה. מורה נבוכים ח״ג ספמ״ז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181145\" data-slug=\"likkutei-sichot\" data-id=\"1300181145\">לקו״ש חי״ח ע׳ 136</a> הערות 35־36). וראה לקמן ע׳ 72 הערה 36. ע׳ 75 הערה 53."],["10","10","ערכין טו, ב. — בערכין שם (טז, א) „על שבעה דברים כו׳”, אבל ברמב״ם שם הובא להלכה רק „להזהירן מלשון הרע”."]]],[1300221080,"ואל יעבור”, און „כאילו כופר בעיקר” (ווי דער רמב״ם איז מאריך אין הלכות דעות¹¹) — איז ווי קען מען זאגן, אז ער איז אן אדם השלם, זיין תואר איז אדם, וואס עס פעלט אים נאר דער בירור פון חיצוניות הרע?\nדי תמיהה אין דעם איז נאך גרע־סער: דער חומר פון „המספר בלשון הרע” ווערט געבראכט אין רמב״ם (אויך) אין דער זעלבער הלכה¹² וועל־כע דער אלטער רבי ברענגט אלס ראי׳ אז נגעים זיינען מעשה נסים וואס זיינען ניט מצוי בזמן הזה, און ער איז דארט מאריך ווי פון דיבור לשון הרע קען מען קומען (ר״ל) ביז צו כפירה בעיקר — און דא זאגט דער אלטער רבי אז מ׳רעדט וועגן אן אדם השלם?\nג. וועט מען דאס פארשטיין בהקדם הביאור אין המשך דברי הרמב״ם בהלכה הנ״ל:\nנאכדעם ווי דער רמב״ם איז מבאר אז נגעים קומען על חטא לשון הרע (און ברענגט דעם לימוד פון מרים) — איז ער ממשיך מיט אן ענין וואס האט לכאורה ניט קיין שייכות צו לשון הרע (ועאכו״כ ניט צו הל׳ טומאת צרעת), וזה לשונו:\n„קל וחומר (פון מרים׳ן) לבני אדם הרשעים הטפשים שמרבים לדבר גדולות ונפלאות . . וזה דרך ישיבת הלצים הרשעים בתחילה מרבין בדברי הבאי . . ומתוך כך באין לספר בגנות הצדיקים . . ומתוך כך יהי׳ להן הרגל לדבר בנביאים ולתת דופי בדבריהם . . ומתוך כך באין לדבר באלקים וכופרין בעיקר . . זו היא שיחת הרשעים שגורמת להן ישיבת קרנות וישיבת",[["11","11","פ״ז ה״ג."],["12","12","הל׳ טומאת צרעת שם. כנסיות של עמי הארץ וישיבת בתי משתאות עם שותי שכר, אבל שיחת כשרי ישראל אינה אלא בדברי תורה וחכמה, לפיכך הקב״ה עוזר על ידן ומזכה אותן בה כו׳”. דארף מען פארשטיין: א) דא רעדט מען דאך וועגן דעם איסור פון דיבור לשון הרע, וועלכער איז גורם צו טומאת צרעת — איז ווי פאסט דא אריין (— ובאריכות) וועגן שיחת הרשעים בכלל, און וועלכע הויבט זיך אן פון „דברי הבאי” (ניט — לשון הרע), און ענדיקט זיך מיט כפירה באלקים ר״ל? [אפילו מ׳זאל זאגן, אז וויבאלד לשון הרע איז א פרט אין „שיחת הרשעים”, איז דעריבער, רעדנדיק וועגן לשון הרע און דעם חומר דערפון, דארף דער רמב״ם (לחומר הדבר) מבאר זיין בזה, איז דער גנות פון שיחת הרשעים בכלל וכו׳ — האט עס ניט קיין ארט אין הלכות טומאת צרעת (וואס איז דער עונש בלויז אויף לשון הרע): די אריכות באלאנגט לכאורה נאר אין הלכות דעות, וואו ער רעדט פרטי הדינים ווי מען דארף זיין אפגעהיט פון דיבורים אסורים]. ב) אויב דער רמב״ם וויל דא ארויס־ברענגען דעם חומר האיסור פון לשון הרע, האט ער געדארפט ברענגען די לשונות חמורים וועלכע ער שרייבט אויף א מספר בלשון הרע אין הלכות דעות¹¹? נאך מער: אין הל׳ דעות¹¹ ברענגט דער רמב״ם דעם מאמר חז״ל¹³ „כל המספר בלשון הרע כאילו כופר בעיקר”, אז דער חטא פון לשון הרע ---"],["13","13","ערכין טו, ב."]]],[1300221081,"מצד עצמו איז חמור „כאילו כופר בעיקר”:\nמשא״כ דא זאגט ער, אז פון לשון הרע קומט שפעטער ארויס כפירה בעיקר — „ומתוך כך כו׳ ומתוך כך באין לדבר באלקים וכופרין בעיקר” (אבער ניט אז לשון הרע אליין איז „כאילו כופר בעיקר”).\nד. ויש לומר דעם ביאור בזה:\nמיט דער אריכות וועגן דעם אופן פון שיחת הרשעים, קומט דער רמב״ם מסביר זיין דעם גדר פון „לשון הרע”, וועלכער גיט צו פארשטיין פארוואס די תוצאה פון לשון הרע איז „צרעת”:\nאין לשון הרע זיינען פאראן צוויי ענינים:\nא) דאס רעדן לשון הרע (וועלכער קומט פון די מדות רעות פונעם מדבר — ער האט קנאה ושנאה, א.ז.ו) איז גורם היזק וכו׳ צו דעם וועמען ער באר־רעדט. ד.ה. דער עיקר חסרון דערביי איז וואס דער לשון הרע ברענגט (ארויס זיינע מדות רעות) ומזיק דעם צווייטן.\n— און וועגן דעם ענין אין לשון הרע רעדט דער רמב״ם אין הל׳ דעות, ווי מען זעט דארט דעם תוכן פון דעם גאנצן פרק, אז ער רעדט אלץ וועגן דיבורים והנהגות בלתי רצויים שמאדם לחבירו.\nב) לשון הרע — מצד דעם דיבור עצמו¹⁴: איינער וואס רעדט לשון הרע, ואפילו ניט בכוונה וכו׳ — איז דער דיבור גופא שלעפט אים אריין אין רע.\nווייל אע״פ אז דער כח הדבור איז לכאורה בלויז א כח חיצוני (א לבוש, און א לבוש חיצוני פון דעם נפש), איז ער אבער פארבונדן מיטן עצם פון מענטשן¹⁵ [ביז אז דער תואר פון א מענטשן איז „מדבר”¹⁶]; ומהאי טעמא, ווען איינער רעדט לשון הרע, איז דער דיבור בלתי רצוי שלעפט (מצד עצמו) אים אריין נאך מערער אין רע¹⁷.\nה. און דאס איז אויך וואס דער רמב״ם ברענגט ארויס דורך זיין אריכות, אין סוף הלכות טומאת צרעת, וועגן „שיחת הרשעים”:\nער הויבט אן ווי מ׳דארף זיך אויס־היטן פון הנהגת „הרשעים הטפשים שמרבים לדבר גדולות ונפלאות” (וואס דערין איז נאך ניטא קיין תוכן היפך הרצוי), און איז דערנאך מסביר „דרך ישיבת הלצים הרשעים”, אז „בתחילה מרבין בדברי הבאי” (וואס אין דעם דיבור איז ניטא קיין מדה רעה וכיו״ב), אבער אט־די דיבורים שלעפן דעם מדבר ביז צו תכלית הרע (כהמשך דברי הרמב״ם);\nאון דאס איז אויך דער גדר פון לשון הרע — „שיחת הרשעים”, דאס רעדן אין אן אופן ווי רשעים רעדן. די הדגשה איז אויף דעם וואס ער איז ניט נזהר, פוגם וכו׳ בדיבורו.\nאון ווי דער רמב״ם איז מדגיש גלייך בתחלת הענין — ווען ער רעדט ווי נגעים קומען מזהיר זיין פון לשון הרע — אז בשעת „משתנה עורו ויצטרע” בלייבט דער מענטש „מובדל ומפורסם לבדו עד שלא יתעסק בשיחת הרשעים שהוא הליצנות ולשון הרע”",[["14","14","להעיר גם מעקידה ר״פ מצורע בארוכה."],["15","15","ראה ד״ה לולב וערבה תרנ״ט ובכ״מ. וראה הנסמן בהערה הבאה."],["16","16","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171115\" data-slug=\"likkutei-sichot\" data-id=\"1300171115\">לקו״ש חי״ז ס״ע 115</a> ואילך ובהנסמן שם. לקו״ש חכ״ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271226\" data-slug=\"likkutei-sichot\" data-id=\"1300271226\">ע׳ 212</a>."],["17","17","להעיר גם מסה״מ תרנ״ט ע׳ ה (בשם הר״ח) סגולה למדת הכעס שלא ידבר בעת ההיא, ע״ש באורך."]]],[1300221082,"— דלכאורה: „שיחת הרשעים” און „ליצנות” מאן דכר שמייהו?\nנאר דערמיט איז דער רמב״ם אויסן צו מבאר זיין, אז לשון הרע (וועלכער ברענגט צו נגעים) איז א פרט און קומט מצד „שיחת הרשעים” בכלל (א חסרון אין דעם דיבור (חיצוניות) האדם), ווייל דער ענין פון נגעים איז (כנ״ל), אז „עור בשרו” — די חיצוניות האדם — איז ניט כדבעי.\nו. עפ״ז יומתק וואס דער רמב״ם איז מאריך ווי דער ענין (אז נגעים קומען צוליב לשון הרע) ווערט אפגעלערנט פון מעשה מרים — „ועל ענין זה מזהיר בתורה — . . התבוננו מה אירע למרים כו׳”:\nדער עונש פון נגעים אויף לשון הרע איז (ניט מצד דעם (ערשטן) ענין הנ״ל אין לשון הרע, וואס זיינע מדות רעות זיינען מזיק דעם זולת, נאר בלויז מצד דעם דיבור עצמו:\nווארום ביי מרים׳ן איז דאך אדרבה: „גידלתו על ברכי׳ וסכנה בעצמה להצילו מן הים”: איר דיבור איז בכלל ניט געווען מיט דער כוונה לגנותו¹⁸, און נאך מער (זאגט דער רמב״ם): „לא דברה בגנותו אלא טעתה כו׳”; און אויך מצד משה׳ן איז „לא הקפיד על כל הדברים האלו כו׳” —\nאין איר דיבור איז ניט געווען קיין שום רע והיזק כו׳ (ניט מצד מרים׳ן און ניט מצד משה׳ן), ס׳איז אן ענין חיצוני לגמרי¹⁹, און אעפ״כ „מיד נענשה בצרעת”.\nז. על פי האמור לעיל וועט מען אויך פארשטיין פארוואס דער רמב״ם ברענגט (בתחלת ההלכה הנ״ל) דעם סדר ווי עס קומען נגעים „להזהירן מלשון הרע”:\n„משתנות קירות ביתו” (נגעי בתים), דערנאך אויב „עמד ברשעו . . משתנין כלי העור שבביתו . . ואם עמד ברשעו . . משתנין הבגדים שעליו”, און ערשט דערנאך — „אם עמד ברשעו . . משתנה עורו ויצטרע” —\nווייל דאס איז מתאים צו דעם תוכן הנ״ל פון לשון הרע און זיין סדר:\nבשעת מען הויבט אן רעדן לשון הרע, איז דער דיבור אן ענין חיצוני לגמרי וועלכער „רירט אים ניט אן”, און דער־פאר איז לוקה (נאר) דער בית וואס איז אינגאנצן אפגעטיילט פון אים²⁰; אבער וואס מער ער רעדט, אלץ מער שלעפט עם אריין דער דיבור גופא, דער רע ווערט מער בפנימיותו, און דערפאר קומען די נגעים אין זאכן וועלכע זיינען נעענטער צו אים — כלי תשמישו, בגדיו, ביז — עור בשרו.\n(בשעת אבער דער רע גייט אריין בפנימיות ממש — דעמולט איז ניטא דער גאנצער ענין הנגעים, כנ״ל סעיף א).",[["18","18","רש״י בהעלותך יב, א. וראה שו״ע אדה״ז או״ח סקנ״ו ס״י. שם חו״מ הל׳ אונאה כו׳ סכ״ט."],["19","19","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181154\" data-slug=\"likkutei-sichot\" data-id=\"1300181154\">לקו״ש חי״ח (ע׳ 145</a> ואילך). ועיי״ש שזהו דיוקו של רש״י (ר״פ שלח) „עסקי דיבה”, ולא — לשון הרע."],["20","20","ויש לומר, שזהו הטעם (הפנימי) למ״ש הספורנו (ס״פ תזריע) בנוגע לנגעי בתים „וכאשר לא עלו הדורות למדריגה ראוי׳ למעלה (לחמלה) זו אין זכרון לראשונים שנמצאו לעולם נגעי בתים עד שאמרו קצתם ז״ל (סנהדרין עא, א) שלא היו לעולם” — כי הרע המתברר בנגעי בתים הוא חיצוני כ״כ (כמו בית שהוא מקיף הכי רחוק), שצריך להיות ב„מדריגה ראוי׳ למעלה זו” כדי לברר גם רע זה. ואולי יש לומר, שזהו גם הטעם (הפנימי) לזה שדוקא גבי נגעי בתים ובגדים מפורש ברמב״ם שהם „אות ופלא” (ראה לקמן ע׳ 72 הערה 36)."]]],[1300221083,"וע״פ הנ״ל איז מובן ווי דער ביאור פון אלטן רבי׳ן הנ״ל — אז נגעים קומען דוקא בא אן אדם השלם וואס האט מתקן געווען כל הדברים חוץ פון „סוף לבושיו” — איז ניט נאר ניט קיין סתירה צו דברי הרמב״ם, נאר אדרבה, ביידע ביאורים זיינען עולה בקנה אחד —\nווייל די זהירות פון לשון הרע וואס ווערט ארויסגעבראכט אין רמב״ם, איז די זהירות אין דיבור מצד עצמו, וואס איז א דבר חיצוני.\nח. ע״פ כל הנ״ל וועט מען אויך פארשטיין פארוואס די תקנה (טהרה) פון נגעים איז דוקא דורך א כהן.\nדלכאורה איז ניט מובן: וויבאלד עס רעדט זיך וועגן אן אדם השלם, כנ״ל, וועלכער איז בכח צו מברר זיין אלע זיינע ענינים פנימיים און האט עס גע־טאן בפועל — איז ווי קומט עס אז ער אליין קען ניט מברר זיין די חיצוניות הרע שבו?\nאיז דער ביאור בזה: דאס וואס אן אדם השלם קען נכשל ווערן אין לשון הרע, אע״פ וואס ער האט שוין מברר געווען כל ענינים פנימיים שבו — איז ווייל עס קען זיין א רע הנעלם (עומק הרע) וואס איז טיף מושרש אין דעם אדם, און עס קומט ביי אים ניט ארויס בגלוי;\nאון דער רע הנעלם דריקט זיך אויס אין דעם דיבור האדם²¹ [וכנ״ל, אז דיבור איז פארבונדן מיטן עצם פון מענטשן], און אין אזא דיבור וואס איז לכאורה אן ענין חיצוני בעלמא, און קיין תוכן רע ממש²²\n[ווארום א דיבור בתוכן רע, איז אן אדם השלם וואס האט שוין מברר גע־ווען זיין רע שבפנימיות, ניט שייך צו רעדן אזעלכע דיבורים],\nולכן איז דער תיקון אויף לשון הרע דורך מתקן זיין דעם רע הנעלם שב־נפשו.\nאון דעריבער איז עס דורך א כהן דוקא, וואס איז „חסד עילאה”²³, ולכן איז ער בכחו צו מטהר זיין דעם רע הנעלם;\nאון דערפאר דארף מען האבן דיבור הכהן „טהור אתה”²⁴ — ווייל דורך זיין דיבור איז ער ממשיך אן אור עליון ביותר וואס איז מתקן דעם רע הנעלם, ביז דער מצורע ווערט טהור בתכלית.\n(משיחת ש״פ תזריע תשמ״א)",[["21","21","ראה דרך חיים בהקדמה. ועוד."],["22","22","כביאור הרמב״ם (כנ״ל בפנים) בנוגע למרים."],["23","23","לקו״ת שם. וראה עקידה שם."],["24","24","רמב״ם שם פ״ט ה״ב־ג. וראה לקו״ת שם."]]],[1300221084,"<h3>תזריע־מצורע</h3>\nא. די פרשיות תזריע מצורע זיינען לויט דער קביעות פון רוב השנים (אלע שנים פשוטות) — מחוברות¹. דער קישור ושייכות צווישן די צווי סדרות איז פארשטאנדיק בפשטות — נוסף אויף דעם וואס אין ביידע סדרות רעדט זיך וועגן נגעים (אין פ' תזריע — נגעי אדם² ונגעי בגדים³ און אין פ' מצורע — נגעי בתים⁴), נאר נאך מער: פ' מצורע איז דער סיום וחתום פון פ' תזריע; די דיני המצורע וועלכע עס רעדט זיך בפ' תזריע, איז סיומם — „תורת המצורע ביום טהרתו\" — אין פ' מצורע⁵.\nמען דארף אבער פארשטיין בנוגע די שמות הסדרות: ווי גערעדט שוין פיל מאל⁶, זיינען די נעמען פון די סדרות ניט א סימן בעלמא, א וואורט פון התחלת הסדרה ווערט גענוצט בלויז בכדי אויסצוטיילן אין סדרה פון דער אנדערער, נאר יעדער נאמען אנט־האלט און דריקט אויס (ווי אלע „שמות שנקראים בהם בלשון הקודש\"⁷) די נקודת התוכן פון דער סדרה.\n[און ווי דאס איז אויך מודגש בפרשת תזריע, אז לויט מנהג ישראל הייסט זי ניט „אשה\"⁸ (כאטש דאס איז דער\nערשטער וואורט נאך דער פתיחה כללית „וידבר ה' גו' לאמר\", אבער מיט וועלכן עס הויבן זיך אן כמה פרשיות אין תורה, איז דאס ניט א נאמען ספעציעל פון דער פרשה), נאר איר נאמען איז „תזריע\"⁹].\nפאדערט זיך א ביאור בנדו\"ד — וואס איז די שייכות פון דעם וואורט (נאמען) „תזריע\" צו דער פרשה בכללותה¹⁰, וואס איר תוכן איז, רובה ככולה, דער ענין פון נגעים?\nנאך מער: ניט בלויז האט דער וואורט „תזריע\" קיין שייכות ניט צום ענין הנגעים, נאר, לכאורה, זיינען זיי הפכיים: „תזריע\" ווייזט — ווי דאס איז מפורש בפרשתנו: „אשה כי תזריע וילדה גו'\" — אויף אן ענין וואס ברענגט א הולדה חדשה און חיים חדשים; משא\"כ נגעים, איז דאך „מצורע חשוב כמת\"¹¹, און דער פשט דערפון איז¹², אז דאס איז ניט (נאר) מצד טומאת המצורע¹³, נאר דער מצורע עצמו איז חשוב כמת¹⁴.",[["1","1","ראה לוחות העיבור שבטור או\"ח אחרי הל' ר\"ח ובעתים לבינה מאמר טו."],["2","2","יג, ב ואילך."],["3","3","שם, מז ואילך."],["4","4","יד, לד ואילך."],["5","5","יד, ב — עד שם, לב."],["6","6","ראה בהנסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211250\" data-slug=\"likkutei-sichot\" data-id=\"1300211250\">לקו\"ש חכ\"א ע' 250</a> הערה 1־2."],["7","7","ראה שער היחוד והאמונה פ\"א."],["8","8","כפי שנק' בסידור הרס\"ג — קריאת התורה."],["9","9","כבמג\"א או\"ח סתכ\"ח. וברמב\"ם (סו\"ס אהבה) בסדר תפילות שלו בסופו (ועוד) „אשה כי תזריע\". וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211146\" data-slug=\"likkutei-sichot\" data-id=\"1300211146\">לקו\"ש שם ע' 146</a> הערה 6 עד\"ז בכמה סדרות."],["10","10","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071086\" data-slug=\"likkutei-sichot\" data-id=\"1300071086\">לקו\"ש ח\"ז ע' 74</a> ואילך העניין המיוחד שבשם „תזריע\" (וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171148\" data-slug=\"likkutei-sichot\" data-id=\"1300171148\">לקו\"ש חי\"ז ע' 148־9</a> וע' 155). אבל לא נתבארה שם השייכות לתוכן ענין הנגעים כי אם ל„תורת האדם\" בכלל."],["11","11","נדרים סד, ב."],["12","12","ראה חדא\"ג מהרש\"א נדרים שם."],["13","13","ראה ספרי ורש\"י בהעלותך יב, יב."],["14","14","ועד\"ז י\"ל גם בהא דאמרינן מצורע איתקש למת — ראה יבמות קג, ב. רמב\"ם הל' טומאת צרעת פי\"ג הי\"ד. ואכ\"מ."]]],[1300221085,"אויך איז ניט מובן בנוגע „מצורע\" אלס שם הפרשה: אין פ' מצורע רעדט זיך ניט וועגן דעם מצורע אלס מצורע (פרטי הנגעים שבו און — זיין טומאה), נאר פארקערט — וועגן טהרתו — ער ווערט אויס מצורע, ער קען שוין אריינ־קומען אין תוך המחנה און ברענגען זיינע קרבנות וכו'¹⁵ — היינט פארוואס זאל די סדרה אנגערופן ווערן „מצורע\"?¹⁶\n[ואע\"פ אז נאכדעם אין דער סדרה רעדט זיך וועגן נגעי בתים — איז ניט גלאטיק: א) אין פשטות ווערן נגעי בתים ניט נכלל אינעם מובן הפשוט פון „מצורע\"¹⁷. ב) נאך מער: ביי די נגעי בתים איז די הדגשה ניט אין די נגעים כשלעצמם (אלס ענין בלתי רצוי), נאר — ווי רש\"י וואס ענינו איז פשוטו של מקרא, ברענגט גלייך אראפ¹⁸ אויף „ונתתי נגע צרעת\" — „בשורה היא להם שהנגעים באים עליהם לפי שהטמינו אמוריים כו' ועי\"ג הנגע נותץ הבית ומוצאן\",\nמשא\"כ „מצורע\" איז — אדרבה, לפי המבואר בפרש\"י דא ובארוכה אין מדרשי חז\"ל אויף תחלת פרשתנו¹⁹ וועגן דעם חסרון און עונש פון א מצורע — אז דאס איז פארבונדן מיטן ענין פון לשון הרע וגסות הרוח].\nאויך דארף מען פארשטיין וואס מען געפינט צווי שמות פון דער סדרה: מנהג ישראל (און אזוי ווערט אנגע־רופן אין טור ושו\"ע²⁰) איז צו רופן איר — „מצורע\"; אבער אין רס\"ג²¹, פרש\"י²² און רמב\"ם²³ ווערט זי אנגערופן — „זאת תהי'\". וואס איז דער טעם החילוק פון די צווי שיטות?\nב. ויש לומר הביאור בזה:\nבהקדים: איינע פון די יסודות האמונה איז — דער ענין פון שכר ועונש, ובלשון הרמב\"ם²⁴ (אין פירוש המש־ניות²⁵): „היסוד הי\"א כי הוא הש\"י נותן שכר למי שעושה מצות התורה ויענישׁ למי שעובר על אזהרותי' וכי השכר הגדול העולם הבא והעונש החזק כרת כו'\", און ווי ער איז מאריך בזה בספרו יד החזקה אין הל' תשובה²⁶:\nתורה איז דאך תורת חסד. איז מובן, אז אויך די עונשי התורה זיינען ניט לשם עונש ח\"ו²⁷, נאר — דער תיקון פארן נפש החוטא²⁸, וכמאמר רז\"ל²⁹ „חייבי כריתות שלקו נפטרו ידי כרית־תם\". ועד\"ז באַ עונש מיתת ב\"ד, ווי",[["20","20","או\"ח סתכ\"ח."],["21","21","בסידורו — קריאת התורה."],["22","22","עה\"ת תזריע יג, ח."],["23","23","בסדר תפלות שלו בסופו. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071112\" data-slug=\"likkutei-sichot\" data-id=\"1300071112\">לקו\"ש ח\"ז ע' 100</a> ובשוה\"ג להערה 3 שם."],["24","24","ואפילו לדעת ס' העיקרים דרק שלשה עיקרים הם — שכר ועונש אחד מהם (ח\"א פ\"ד, פ\"י)."],["25","25","סנהדרין ר\"פ חלק. — וכבר העירו ע\"ז שלא הביא בס' היד ענין העיקרים, אבל מובן שאין זה מבטל חשיבותם. וראה טושו\"ע יו\"ד סרס\"ח ס\"ב."],["26","26","פ\"ח ואילך."],["27","27","להעיר מברכות ה, א."],["28","28","ראה כוזרי מאמר שני פמ\"ד. וראה גם עיקרים מאמר רביעי פל\"ח."],["29","29","מכות כג, סע\"א במשנה."],["15","15","וי\"ל שלכן נקראות בכמה ספרים בשם פ' „טהרה\". וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071112\" data-slug=\"likkutei-sichot\" data-id=\"1300071112\">לקו\"ש ח\"ז ע' 100</a> הערה 5 ובהנסמן שם."],["16","16","להעיר גם מפרשת „חיי שרה\" אף שתחלת הסדרה מדברת בפטירתה וקבורתה, ובכל הסדרה מדובר בענינים שארעו אחר מיתתה — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151145\" data-slug=\"likkutei-sichot\" data-id=\"1300151145\">לקו\"ש חט\"ו ע' 145</a> ואילך. וש\"נ."],["17","17","להעיר מפיה\"מ נגעים פי\"ב, ה."],["18","18","יד, לד מויק\"ר פי\"ז, ו."],["19","19","תנחומא, ויק\"ר (פט\"ז, ה־ו)."]]],[1300221086,"רז\"ל³⁰ זאגן ביי עכן: „יעכרך ה' ביום הזה ביום הזה אתה עכור ואי אתה עכור לעוה\"ב\"³¹,\nאבער באַ רוב עונשי התורה זעט מען ניט בגלוי אז דאס איז גאר לטובתו של האדם, בחיים חיותו בעלמא דין בעוה\"ז.\nמשא\"כ באַ נגעי צרעת זעט מען דאס בגלוי (כדלקמן ברמב\"ם) — (און פון דעם עונש הנגעים³² איז מובן אז עד\"ז איז באַ אלע עונשי התורה).\nג. דער רמב\"ם זאגט בסוף הל' טומאת צרעת³³: „וזה השינוי האמור בבגדים ובבתים שקראתו תורה צרעת בשותפות השם אינו ממנהגו של עולם אלא אות ופלא הי' בישראל כדי להזהירן מלשון הרע שהמספר בלשון הרע משתנות קירות ביתו, אם חזר בו יטהר הבית אם עמד ברשעו עד שהותץ הבית משתנין כלי העור שבביתו כו' ואם עמד ברשעו עד שישרפו משתנין הבגדים שעליו, אם חזר בו יטהרו ואם עמד ברשעו עד שישרפו משתנה עורו ויצטרע ויהי' מובדל ומפורסם לבדו עד שלא יתעסק בשיחת הרשעים³⁴ שהוא הליצנות ולשון הרע\"³⁵.",[["30","30","סנהדרין מג, ב במשנה."],["31","31","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380529\" data-slug=\"likkutei-torah\" data-id=\"4001380529\">לקו\"ת קרח נג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380667\" data-slug=\"likkutei-torah\" data-id=\"4001380667\">מטות פו, ב</a>. ובכ\"מ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231096\" data-slug=\"likkutei-sichot\" data-id=\"1300231096\">לקו\"ש חכ\"ג ע' 96</a> ואילך, שמובן הוא גם בפשוטו של מקרא."],["32","32","להעיר מברכות (ה, ב) אם נגעים הוו יסורין של אהבה. אבל לכו\"ע הוי מזבח כפרה."],["33","33","ועד\"ז בפיה\"מ נגעים פי\"ב מ\"ה. מו\"נ ח\"ג ספמ\"ז."],["34","34","מקור הרמב\"ם הוא (לכאורה) בתוספתא נגעים פ\"ו, ו; תנחומא מצורע ד (בסופו); ויק\"ר פי\"ז, ד; פסיקתא רבתי יז — ששם מפורש הסדר הנ\"ל, תחלה נגעי בתים כו'. אבל במקומות הנ\"ל אינו מפורש: א) „אות ופלא הי' בישראל\". ב) עד שלא יתעסק בשיחת הרשעים כו'. ואכ\"מ."],["35","35","וראה ספורנו ס\"פ תזריע. דאס הייסט, דער אויבערשטער מאכט א שינוי מיוחד³⁶ אין דער בריאה „כדי להזהירן מלשון הרע\". וואס דערפאר איז דער סדר, אז דער אויבערשטער ברענגט עס (דעם שינוי) פריער אין די בתים און דערנאך אויף די בגדים וכו', בכדי צו מזהיר זיין די אידן מן הקל אל הכבד צו זיין אפגעהיט פון לשון הרע³⁷."],["36","36","פשטות לשון הרמב\"ם בהל' טומאת צרעת שם, „אינו ממנהגו של עולם\", קאי על „השינוי האמור בבגדים ובבתים\", ועד\"ז מובן ממ\"ש בפיה\"מ שם „כי הבגדים והבתים דוממים והשנוי הנולד בהם אינו צרעת אלא שהתורה קראתו כך\"* (וכן מפורש ברמב\"ן עה\"ת פרשתנו יג, מז. כלי יקר וספורנו שם. חינוך מצוה קעב, קעז**). אבל בלקו\"ת פרשתנו (כב, ב. הובא לקמן בפנים ס\"ו) כתב גם על צרעת באדם „שנולדו סימנים בגשמיות בבשרו שלא כדרך הטבע . . אך מעשה נסים הם\". אבל גם ברמב\"ם מובן, מכיוון שנגעי אדם באים על האדם בהמשך ולאחרי נגעי בתים ונגעי בגדים מוכח שסיבתם אינה טבעית***. וכ\"מ במו\"נ שם. ולהעיר ממה שמסיים בפיה\"מ שם „וכן נגעי אדם אתה תראה שישים הנתקים צרעת והוא חולי . . ויטהר הצרעת כאשר הפך כולו לבן . . ואמנם הם ענינים תוריים\" (וראה תרגום קאפח שם). ובכלי יקר שם „וזהו בנין אב גם על נגעי הגוף שהם חוץ לטבע על צד העונש\". וראה גם בחיי (שם, נח)."],["37","37","להעיר מלשון החנוך במצוה קעב „משרשי המצוה שרצה הא־ל בטובו הגדול לייסרנו כאשר ייסר איש את בנו כו'\", ובמצוה קעז „כי מאהבת ה' אותם יודיע כו'\". *) כ\"ה בתרגום קאפח שם, ולפנינו בפיה\"מ ב' נוסחאות. **) להעיר משינוי הלשון בחינוך: בנוגע לנגעי בגדים כתב (מצוה קעב) „כי זה הענין אינו בטבע אבל מופת הוא באומה הקדושה למען ילמדו כו'\". ובנוגע לנגעי בתים כתב (מצוה קעז) „שמעתי שאיננו דבר טבעי אבל הוא ענין מופתי יבוא לפעמים בבתי ישראל להוכיחם\". ***) וכן משמע גם ממ\"ש בלקו\"ת שם „הנגעים שאינם מליחות המצויים כמ\"ש הרמב\"ם\", וקאי על נגעי אדם (כבפנים ההערה). וראה בהנסמן לקמן הערה 51. וראה לעיל ע' 65 הערה 9."]]],[1300221087,"און אויך דער הסגר פון דעם מצורע עצמו, וואס ווערט געטאן אין אופן ש„יהי' מובדל ומפורסם לבדו\", „בדד ישב מחוץ למחנה מושבו\"³⁸, איז מיט דער מטרה אז דאס זאל אויף אים פועלן „שלא יתעסק בשיחת הרשעים שהוא הליצנות ולשון הרע\".\nד. ועפ\"ז י\"ל אז מהאי טעמא ווערט די פרשה אנגערופן „תזריע\": תזריע איז די התחלת הלידה פון חיים חדשים, כנ\"ל ס\"א (ע\"ד ווי זריעה באַ תבואה ופירות — און דערפון זאל נאכדעם קומען א נייע צמיחה) —\nאזוי איז דער תוכן ענין הנגעים פון פ' תזריע: סיי דער נגע עצמו און סיי דער הסגר והחלט פון דעם מצורע וואס ער איז „מובדל ומפורסם לבדו\" זיינען ניט (נאר?) בתור עונש והעדר הטוב פאר דעם מצורע כנ\"ל, נאר פרטים און מיט־לען אין דעם תיקון (אין דער היילונג) פון דעם מצורע, אז ער זאל אריין אין א סדר פון חיים חדשים און ניט האבן קיין שייכות מיט „שיחת הרשעים שהוא הלי־צנות ולשון הרע\".\nאון וויבאלד אז ענינה של תורה איז — הוראה, איז מובן, אז פון פרשת נגעים איז דא א הוראה³⁹ אויף אלע עונשי התורה, אז ענינם איז א פעולה מיוחדת פון דעם אויבערשטן צו מתקן זיין דעם אידן, ער זאל גיין בדרך הישר.\nפארוואס ווערט דאס אנגעוויזן און געזאגט דוקא באַ מצורע?\nהיות אז ער איז חשוב כמת (און בגילוי איז טומאת מצורע פון די טומ־\nאות הכי חמורות⁴⁰, זיין עונש — בדד ישב מחוץ למחנה מושבו — איז פון די עונשים הכי חמורים⁴¹).\nאון פון דעם לערנט מען אפ אויך בנוגע די אנדערע עונשים, אז זיי זיינען א התחלה ופרט פון דעם תיקון האדם,\nאזוי ווי דער ענין הנגעים, מיט די ימי הסגר והחלט, זיינען אן ענין פון „תזריע\" (אז דער כמת זאל ווערן א ברי' חדשה).\nה. ויש לומר, אז פון דעם קומט ארויס אויך א נפק\"מ להלכה:\nדעם⁴² דין באַ מצורע, אז „כל ימי אשר הנגע בו יטמא כו' בדד ישב מחוץ למחנה מושבו\"³⁸, קען מען מגדיר זיין אין צווי אופנים — אז דאס איז א דין ע\"ד ווי באַ אנדערע טמאים (זבים וזבות וטמאי מתים) וועלכע טארן ניט זיין בתוך מחנה שכינה אדער מחנה לוי', עד\"ז דארף א מצורע, מצד חומר יותר בטומאתו, זיך געפינען מחוץ לג' מחנות, אויך מחוץ למחנה ישראל (ובמילא איז „בדד ישב גו'\")⁴³; אדער אז די אזהרה „בדד ישב מחוץ למחנה\" איז א דין מיוחד באַ מצורע דוקא, ניט (נאר) פאר־בונדן מיט זיין טומאה, נאר (אויך) מיט ענינו המיוחד ומשונה פון שאר הטמאים.",[["38","38","יג, מו."],["39","39","להעיר שבחינוך (מצוה קסט) כ' בשרשי המצוה (דנגעים — „לטמא אדם מצורע . . שיבוא אל הכהן\") „לקבוע בנפשותינו כי השגחת הקב\"ה פרטית על כ\"א מבני אדם כו'\". עיי\"ש."],["40","40","דמחוץ למחנה מושבו, מחוץ לג' מחנות, משא\"כ שאר טמאים (ראה תו\"כ ורש\"י פרשתנו שם. פסחים סז, א — הובא בפרש\"י נשא ה, ב)."],["41","41","ובמכש\"כ מצער גלות שהוא „שקול כמעט כצער מיתה שנפרד האדם מאוהביו כו' ושוכן כו' עם זרים\" (חינוך מצוה תי), ויותר מזה במצורע „בדד ישב\". ולהעיר מפירוש הראב\"ד לתו\"כ שם — שיהא כמנודה כו'. וראה לקמן הערה 49."],["42","42","בכל הבא לקמן — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181144\" data-slug=\"likkutei-sichot\" data-id=\"1300181144\">לקו\"ש חי\"ח ע' 135</a> ואילך. וש\"נ."],["43","43","מקומות שבהערה 40."]]],[1300221088,"לכאורה איז ביי מצורע דא צווי באַ־זונדערע סוגי דינים: א) דער דין כללי פון טמאים וועלכע שטייט אין פ' נשא⁴⁴: „וישלחו מן המחנה כל צרוע וכל זב וכל טמא לנפש\". און דער טעם איז „ולא יטמאו את מחניהם\"⁴⁵ (צוליב די מחנות), וואס דאס איז פארבונדן מיט דער טומאה פון מצורע; און ב) דער ציווי „בדד ישב מחוץ למחנה מושבו\" א דין מיוחד באַ מצורע, וואס איז נוגע עם, לטהרתו (ניט (נאר) אלס הרחקה מהמחנות מצד טומאתו).\nויש לומר, אז צווישן די צווי דינים זיינען דא כמה נפק\"מ, ומהם:\nא) ביי דעם דין הכללי „וישלחו מן המחנה\" איז נוגע די שלילה, ער זאל ניט זיין אין דער מחנה („ולא יטמאו את מחניהם\" (ובמילא — כשבטלו מחנות איז ער אויך דעמאלט ניט במחנה)); משא\"כ אין דעם דין „בדד ישב מחוץ למחנה מושבו\" איז נוגע דער חיוב — אז ער זאל זיין בדד מחוץ למחנה — ובמילא אויב עס האט זיך (מאיזו סיבה שתהי') ניט אויסגעפירט ביי אים דער ענין פון „בדד ישב מחוץ למחנה מושבו\" (— ווען ס'איז ניטא קיין מציאות פון מחנות כנ\"ל וכיו\"ב), דארף אויסקומען, אז ער קען דעמולט ניט קומען לטהרתו. וכמבואר במ\"א⁴⁶.\nב) מצד דעם דין, אז ער דארף זיין מחוץ לג' מחנות, דארף אויסקומען, אז די אזהרה „בדד ישב לבדו שלא יהו טמאין אחרים יושבין עמו\"⁴⁷ איז בלויז שולל אן אנדער סוג טמאים (טמאי מת,\nזבים וזבות) אבער ניט מצורעים⁴⁸; דאַ־קעגן מצד דעם חיוב „בדד ישב\", דארף זיין „בדד\" אויך פון אנדערע מצו־רעים⁴⁹: דוקא דעמאלט ווערט ביי אים נתקיים „ויהי' מובדל ומפורסם לבדו\"⁵⁰, און נאר אזוי ווערט באוארנט „שלא יתעסק בשיחת הרשעים\" (משא\"כ כשנמצא עם מצורעים ובפרט — רק עמהם — ה\"ז פועל להיפך!).\nו. כשם ווי דאס איז אין פשוטם של הענינים ועפ\"ד ההלכה — אז נגעים איז אן אות און א וואַרנונג אפצוהיטן א אידן פון לשון הרע, און אז אויב ער איז נאך ווייטער אריינגעצויגן געווארן אין דעם ביז אז „משתנה עורו ויצטרע\", ווערן געטאן פעולות „בדד ישב גו'\" אים צו היילן און אפשיידן פון שיחת הרשעים כו' —\nעד\"ז (און נאך מער) איז עס מודגש בפנימיות הענינים:\nס'איז מבואר אין לקו\"ת⁵¹, אז דאס וואס ביי נגעים שטייט⁵² „אדם כי יהי' בעור בשרו גו'\" — דער תואר אדם וואס",[["44","44","ה, ב."],["45","45","שם, ג."],["46","46","ראה בארוכה לקו\"ש שם."],["47","47","פסחים סז, א. וראה גם שאר המקומות שבהערה 40."],["48","48","כפשטות הפירוש בדברי ר\"י פסחים שם."],["49","49","כן הוא לפי' הראב\"ד בתו\"כ שם. ולכאורה כן מובן מרש\"י ד\"ה בדד ישב (יג, מו) שמבאר בהמשך פירושו „מה נשתנה משאר טמאים לישב בדד כו'\", דהיינו לבדו ממש — דאילו זה שמושבו חוץ לג' מחנות מפרש רש\"י בד\"ה שלאח\"ז שזהו פי' ד„מחוץ למחנה — חוץ לשלש מחנות\". אבל ראה ר\"ם ועוד בפרש\"י ובשאר מפרשי התו\"כ. וראה צפע\"נ עה\"ת שם דמביא מכ\"מ דמצורעים יושבים ביחד. וראה גם מ\"ב ז, ג (הפטרת פרשתנו): וארבעה אנשים היו מצורעים גו' ויאמרו איש אל רעהו גו' (אלא שזהו גיחזי ובניו שמחוייבים לכבדו וכו')."],["50","50","לכאורה כן משמע מלשון הרמב\"ם הנ\"ל בפנים. וראה רמב\"ם שם פ\"י ה\"ז."],["51","51","תזריע כב, ב. וראה גם סד\"ה אדם כי יהי' תרס\"ה, תרע\"ה (בהמשך תער\"ב). וראה גם אלשיך פרשתנו שם. וראה לעיל ע' 65 ואילך."],["52","52","תזריע יג, ב."]]],[1300221089,"איז דער שם המעלה פון אידן — איז ווייל דער ענין הנגעים איז שייך דוקא ביי איינעם וואס איז במדריגת אדם, וועלכע איז א מדריגה גדולה, „שלימו דכולא\".\nאון דער טעם דערפון איז, ווייל דער ענין „בעור בשרו\" ווייזט אז דער רע וואס איז גורם דעם נגע איז ניט בתוך אין (דער פנימיות פון) דעם מענטשן, נאר ס'איז „פסולת\" ורע וועל־כע איז פארבליבן בלויז אין זיין חיצוניות — „בסוף לבושיו\", און דער־פאר ווערט דערפון אזוי אויך אין דעם מסובב (בדומה צו זיין סיבה) א נגע וואס איז (נאר) „בעור בשרו\", בחיצוניות הגוף.\nדערמיט איז דער אלטער רבי אויך מבאר פארוואס „מצות נגעים אינו נהוג בזמננו זה אחר החורבן מפני שאינן מצויין כלל⁵³ כו' אך מעשה נסים הם\"⁵⁴ —\nהיות אז „אינו בנמצא בזמננו\" אזא מענש וואס האט אינגאנצן ניט קיין רע בפנימיות, „שאף הצדיק והטוב עדיין הרע קצת בפנימיות\", דערפאר איז דער רע בזמננו ניט גורם קיין נגעים.\nלפ\"ז איז נאך מער מוסבר דער טעם הנ\"ל, אז דער ענין הנגעים המבואר בפ' תזריע איז תוכנו ענין פון „תזריע\" — צוליב א הולדה חדשה ונעלה:\nדעם מעשה נסים מאכט דער אוי־בערשטער בכדי אז אויך די חיצוניות ופסולת הרע זאל נתברר ווערן באַ אידן.\nז. עפ\"ז איז אויך מבואר דער שם פון דער צווייטער סדרה, „מצורע\", כאטש דאַרט רעדט זיך ניט ווי דער מצורע איז במצב של טומאה, נאר ווי ער איז „ביום טהרתו\":\nדערמיט ווערט אַרויסגעבראַכט, אז טהרת (ורפואת) המצורע (המבוארת בפ' מצורע) איז ניט קיין באזונדער אויפטו, וואס ווערט נתחדש (בלויז) מצד די פעולות וקרבנות וועלכע זיינען מבואר אין דער פרשה, נאר דאס אלץ קומט בהמשך און אלס מסובב פון די ענינים המבוארים בפ' תזריע.\nבסגנון אחר: די פעולות שבפ' מצורע וואס טוען אויף די טהרה (בפועל), זיי־נען (בלויז) ממשיך ומגלה דאס וואס האט זיך שוין אויפגעטאן אין דעם אדם דורך דער צרעת גופא, וכנ\"ל אז די רפואת האדם ברוחניות (וואס דאס איז די סיבת הצרעת) איז דורך דער צרעת והסגר („בדד ישב גו'\").\nאון דעריבער ווערט די פרשה ניט אנגערופן „ביום טהרתו\" (וכיו\"ב⁵⁵) וואס וואלט אנגעדייטעט אז דוקא דאָ טוט זיך אויף טהרתו, נאר דוקא „מצורע\" וואס ברענגט ארוים אז דאס איז די תוצאה פון דעם ענין ה„מצורע\" גופא.\nח. כשם ווי דאס איז בנוגע א מצורע פרטי, עד\"ז איז מובן בנוגע כללות עם ישראל, וואס געפינענדיק זיך אין גלות זיינען אידן אין א מעמד ומצב פון „בדד ישב מחוץ למחנה מושבו\"⁵⁶:\nדי⁵⁶* עבודה פון אידן בזמן הגלות איז אן ענין פון „תזריע\"⁵⁷ — א זריעה והכרח",[["55","55","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071115\" data-slug=\"likkutei-sichot\" data-id=\"1300071115\">לקו\"ש ח\"ז ע' 103־4</a> ובהערה 40 שם."],["56","56","ראה ויק\"ר ספי\"ז דדריש כל הפרשה בנגעי בתים על חורבן ביהמ\"ק „ועמא הגלי לבבל\" כו'. *56) ראה גם סה\"ש תנש\"א ח\"ב ע' 490 ואילך."],["57","57","ראה דרושי חסידות עה\"פ הבאים ישרש יעקב (תו\"א כו' פ' שמות)."],["53","53","צ\"ע אם הכוונה רק מפני זה (כי דינם שנוהגים גם שלא בזמן הבית (רמב\"ם הל' טו\"צ פי\"א ה\"ו)) — ואין כל מניעות, כהן מיוחס וכו'. וראה תו\"ש (שמות מילואים סח\"י) הדעות אם נגעים נוהגין בזה\"ז והטעמים. וראה הנסמן לעיל ע' 65 הערה 9."],["54","54","ראה לעיל הערה 36."]]],[1300221090,"לצמיחה והתחלת הצמיחה בזמן פון דער גאולה. ווי דער אלטער רבי זאגט אין תניא⁵⁸, אז די גילויים דלעתיד זיינען „תלוי במעשינו ועבודתינו כל זמן משך הגלות, כי הגורם שכר המצוה היא המצוה עצמה\". ד.ה. אז דאס וואס עס טוט זיך אויף לימות המשיח ותחיית המתים איז ניט קיין באזונדער זאך פון ענין הגלות, נאר דאס איז די „צמיחה\", וואס „וואקסט אויס\" פון עבודת ה„זריעה\" בזמן הגלות.\nאון דאס איז די הוראה פון די שמות הסדרות „תזריע־מצורע\" בעבודת כל אחד:\nא. איד דארף לערנען תורה ומקיים זיין מצות מיט קבלת עול, ווייל אזוי האט דער אויבערשטער געהייסן.\nקען ער טראכטן אז ס'איז קיין נפק\"מ ניט כלל וואס די עבודה טוט אויף⁵⁹,\n— איז אויף דעם די הוראה, אז (ביחד עם הנ\"ל) איז אין „מעשינו ועבו־דתינו\" פון זמן הגלות דארף דערהערט ווערן אז דאס איז אן ענין פון „תזריע\" וואס ברענגט די „צמיחה\", דעם גילוי פון משיח צדקנו; ובמילא: אז די גילויים דלעתיד זיינען ניט קיין באזונדער ענין, נאר א המשך ותוצאה פון דער עבודה פון גלות (ע\"ד „תזריע־מצורע\", כנ\"ל) — די צמיחה וואס קומט פון דער עבודה אין גלות.\nט. אין דעם פארבונד פון דער עבודה בזמן הגלות (תזריע) מיט ביאת המשיח (מצורע) זיינען אבער דא כמה אופנים: אע\"פ אז יעדער איד מאמין אין ביאת המשיח און איז „מחכה לביאתו\", וואס דאס איז א יסוד פון די\nיסודות האמונה אין וועלכן אלע אידן זיינען גלייך — קען אבער זיין א חילוק אויף וויפל דאס איז פארבונדן מיטן לימוד התורה וקיום המצות, מיט מעשי־נו ועבודתינו פון א אידן:\nער קען לערנען תורה און מקיים זיין מצות וויסנדיק אז דאס איז „תזריע\", אז דאס ברענגט משיח'ן, אבער צו „אים\" (צו זיין עבודה) האט דאס ניט, ווייל — א) ניט צוליב דעם לערנט ער תורה און איז מקיים מצות. ב) אים ארט ניט אז די גאולה וועט זיין אין א שפעטערדיקן זמן, אין א זמן שפעטער (קריאת מצורע בשבוע בפ\"ע) — ביז אין אנדער דור ח\"ו. „ער\" באנוגנט זיך און איז צופרידן מיט דעם וואס ער לערנט תורה, איז מקיים מצות און מאכט די זריעה אויף דער גאולה.\nאויף דעם איז די הוראה, אז ברוב השנים זיינען די ביידע סדרות מחו־ברות, און א כלל גדול בתורה איז — שעל הרוב תדבר⁶⁰ און א דין עיקרי בהלכה למעשה בפועל איז — אזלינן בתר רובא⁶¹ —\nד.ה. עס דארף זיין דער חיבור פון תזריע און מצורע, און אזוי בשלימות, אז — כמנהג ישראל אומעטום — אז מ'פרעגט ביום ראשון פון דער וואך (אדער בשאר הימים) פון וועלכער וואך, איז דער ענטפער בפשטות: פון פרשת תזריע מצורע,\nזיין עבודה אין גלות דארף זיין דורכ־גענומען מיט דער שטענדיקער צפי׳⁶² און שטרעבונג צו דער גאולה, אחכה לו",[["58","58","רפל\"ז."],["59","59","ובל' הידוע אילו נצטווה לחטוב עצים (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380472\" data-slug=\"likkutei-torah\" data-id=\"4001380472\">לקו\"ת שלח (מ, א</a>). וראה מו\"נ ח\"ג פנ\"א בהערה)."],["60","60","מו\"נ ח\"ג פל\"ד."],["61","61","חולין יא, א. ובכ\"מ."],["62","62","ראה פסיקתא רבתי רפל\"ז: איזה אור שכנסת ישראל מצפה זה אורו של משיח. וראה שבת לא, א: צפית לישועה (וצ\"ע בפרש\"י שם). זח\"א ד, סע\"א. קם, א. ועוד."]]],[1300221091,"בכל יום שיבוא⁶³. און וויבאלד אז אני נבראתי לשמש את קוני⁶⁴, דאס איז די עבודה פון דעם אידן כל היום, דער־הערט ער אין זיין קיום התומ\"צ, אז דאס ברענגט און איז ממהר די גאולה⁶⁴*.\nיוד. אבער דאס גופא קען זיין אויף צוויי אופנים:\nא) ער דערהערט ווי זיין עבודה, „תזריע\", איז א זריעה וואס וועט ברענ־גען די צמיחה, די גאולה, אבער דאס איז אין אן אופן פון „זאת תהי'\" בהויתו תהא⁶⁵ — אלס נאך א זאך, וואס וועט זיין בנפרד; ער האלט טאקע באַ „אחכה לו בכל יום שיבוא\" און די עבודה איז צוליב דעם „שיבוא\" — באַ אים הערט זיך דאס אבער ווי נאך אן ענין, אז דורך מעשינו ועבודתינו ברענגט מען אראפ און מ'איז ממהר (א באזונדער ענין) ביאת משיח צדקנו, ובפרט „זכו — אחישנה\"⁶⁶.\nב) א העכערער אופן איז, אז באַ אים איז „תזריע ומצורע\" מחוברות — דער אחכה און קווינו כל היום צו דער גאולה וואס ווערט נרגש בכל יום אין זיין עבודת „תזריע\", איז ניט נאר אז יעדע זיין עבודה וועט גלייך זיין „שיבוא\", נאר אז די גאולה העתידה איז איין זאך מיט תוכן עבודתו („תזריע־מצורע\" ווערן איין פרשה) — ווייל ביאת המשיח איז די צמיחה ובמילא די שלימות פון זיין זריעה:\nויש לקשר זה דערמיט וואס דער ענין פון משיח'ן איז וואס דעמאלט וועט זיין\nדי שלימות אין תורה און די שלימות אין מצות, תשבי יתרץ קושיות ואבעיות⁶⁷ משיח יגלה טעמי תורה⁶⁸ כו' ילמד תורה⁶⁹, וכו'\nכולל — בלשון הרמב\"ם⁷⁰: המלך המשיח עתיד לעמוד ולהחזיר מלכות דוד ליושנה לממשלה הראשונה ובונה המקדש ומקבץ נדחי ישראל וחוזרין כל המשפטים בימיו כשהיו מקודם, מקריבין קרבנות ועושין שמטין ויובלות ככל מצותה האמורה בתורה\".\nווי מבואר במ\"א⁷¹ אז דערמיט גיט דער רמב\"ם ארויס א הלכה, אז דער גדר פון משיח'ן איז, וואס ער ברענגט צוריק די שלימות הלכות ומצות התורה. און דאס זאגט דער רמב\"ם: די אלע ענינים וואס האבן געפעלט אין דער שלימות פון קיום התומ\"צ (מצד דעם וואס עס האט געפעלט אין שלימות כל ישראל וביהמ\"ק — וואס דאס איז כללות ענין הגלות) — ווערט נשלם דורך משיח'ן. און אויך אין דעם באַ־שטייט וואס משיח איז מחזיר „מלכות בית דוד ליושנה כו' וחוזרין כל המשפ־",[["63","63","כנוסח אני מאמין."],["64","64","קדושין בסופה. *64) ראה לקו\"ד ח\"ג תכב, א (סה\"ש תש\"ג ע' 73). וראה סה\"ש תשנ\"ב ח\"א (ע' 111. 131. 249)."],["65","65","מנחות ה, א."],["66","66","סנהדרין צח, א."],["67","67","תויו\"ט סוף מס' עדיות. של\"ה תט, א. והוא ע\"פ זח\"ג כח, א. ועייג\"כ ערוך השלם בערכו."],["68","68","ברש\"י שה\"ש (א, ב) מפורש שלעתיד הקב\"ה מגלה טעמי תורה (מבלי לפרט ע\"י מי כמו בנגלה — שמשה קבל וכו') ובאותיות דרע\"ק אות ז (יל\"ש ישעי' רמז תכט בתחלתו): והקב\"ה דורש להם (לצדיקים בג\"ע) טעמי תורה חדשה שעתיד הקב\"ה ליתן להם ע\"י משיח (וביל\"ש שם ליתא תיבת „טעמי\"). וראה הנסמן בהערה הבאה."],["69","69","רמב\"ם הל' תשובה פ\"ט ה\"ב. ובפיה\"מ להרמב\"ם (סנהדרין ר\"פ חלק ד\"ה ועתה אחל): ונפלאות יתגלו על ידו (כ\"ה הלשון בהעתקת קאפח. ובפיה\"מ לפנינו בא בהמשך למש\"כ לפנ\"ז: ויעבדוהו כל הארצות לצדקו הגדול ולנפלאות שיהא על ידו). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380145\" data-slug=\"likkutei-torah\" data-id=\"4001380145\">לקו\"ת צו יז, ב</a>. שער האמונה פנ\"ו ואילך. סהמ\"צ להצ\"צ מצות מינוי מלך פ\"ג."],["70","70","הל' מלכים רפי\"א."],["71","71","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081288\" data-slug=\"likkutei-sichot\" data-id=\"1300081288\">לקו\"ש ח\"ח ע' 277</a> ואילך."]]],[1300221092,"טים\" — ער ברענגט צוריק די שלימות הלכות ומצות התורה.\nאון וויבאלד אז די חפצא (תורה ומצות) איז דאן בשלימות, וועט דעמאלט אויך דער קיום מצד הגברא זיין בשלימות וואַרום „ינוחו ממלכיות שאינן מניחות להם לעסוק בתורה ומצות כהוגן\"⁷² און „יהיו פנויין בתורה וחכמתה\"⁷³. נאכמער: „ובאותו הזמן לא יהי' שם לא רעב ולא מלחמה ולא קנאה ותחרות כו' ולא יהי' עסק כל העולם אלא לדעת את ה' בלבד כו'\"⁷⁴.\nאון אין דעם באַשטייט די אמונה אין ביאת המשיח און דער „מחכה לביאתו\" וואס דער רמב\"ם זאגט בהמשך להנ\"ל⁷⁵: דער לימוד התורה און דער קיום המצות איז דורכגענומען מיט דער אמונה אז דאס ברענגט אים און די גאנצע וועלט צו דער שלימות לימוד וידיעת התורה, פון מצות וקיומן און צו דער שלימות פון ידיעת הבורא — אין דעם באַשטייט דער „מחכה לביאתו\" כנ\"ל.\nיא. עפ\"ז יש לומר אז דאס איז איינער פון די טעמים וואס בדורות הראשונים האט די סדרה געהייסן „זאת תהי'\" און דוקא בדורות האחרונים ווערט זי גערופן „מצורע\" (כנ\"ל סוף ס\"א)⁷⁶:\nבדורות הראשונים, וועלכע זיינען געווען ווייטער פון זמן הגאולה, האט\nזיך די גאולה אנגעהערט אין אן אופן פון „זאת תהי'\" — אן ענין וואס וועט זיין בעתיד, בנפרד; ובמילא, איז די עבודה ניט געווען דורכגעדרונגען עד כ\"כ מיט דעם הרגש, אז דער קיום התומ\"צ גופא קומט גלייך לשלימותו אויך בעולם,\nאבער אין די דורות האחרונים, וועלכע ווערן אנגערופן „עקבתא דמשיחא\", הערט זיך ביי אידן א סך מער דער ענין פון משיח'ן, און דערפאר ווערט די סדרה בדורות אלו מיטן נאמען „מצורע\" — אידן הערן און פילן, ופשיטא אז מזלייהו חזי — אין זייער עבודה אז אט־אט קומט משיח, ובמילא — המעשה הוא העיקר — מוז מען נאך מער מוסיף זיין אין תומ\"צ, די וועלט זאל קומען לשלימותה וואס שנעלער און מקיים זיין מצות „כמצות רצונך\"⁷⁷ בביאת משיח צדקנו אין דעם ביהמ\"ק השלישי.\nיב. ע\"פ הנ\"ל (סעיף ו), יש להמתיק עוד יותר, וואס דוקא בדורות האחרונים ווערט די סדרה אנגערופן „מצורע\":\nכשם ווי דאס איז ביי אן אדם פרטי, אז דוקא דער ענין פון נגעים („מצורע\") ווייזט אויף אן אדם השלם „שמוכשרין מעשיו ותיקן כל הדברים והבחי' שלמע־לה\"⁷⁸, ס'איז נאר אז די בחי' „התחתונה שבו לא נתברר הרע והפסולת ממנו\"⁷⁸, און דערפאר ווערן נולד סימנים גשמיים נאר בעורו, לרמז, אז נאר „בסוף לבושיו\" איז געבליבן פסולת וואס איז נאך ניט נתברר געווארן —\nעד\"ז איז בנוגע לכללות עם ישראל: וויבאלד אז בדורות האחרונים פון",[["72","72","רמב\"ם הל' תשובה שם. עיי\"ש ובהלכה א שם."],["73","73","רמב\"ם הל' מלכים פי\"ב ה\"ד. עיי\"ש ובהל' תשובה שם ה\"ב „שמפני זה נתאוו כל ישראל כו' לימות המשיח\". וראה בארוכה — פיה\"מ להרמב\"ם שם."],["74","74","רמב\"ם ספי\"ב מהל' מלכים."],["75","75","ברפי\"א שם. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081289\" data-slug=\"likkutei-sichot\" data-id=\"1300081289\">לקו\"ש שם ע' 278</a> ואילך."],["76","76","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071115\" data-slug=\"likkutei-sichot\" data-id=\"1300071115\">לקו\"ש ח\"ז ע' 103</a> ואילך."],["77","77","ראה תו\"ח ר\"פ ויחי. המשך וככה תרל\"ז פי\"ז ואילך."],["78","78","לשון הלקו\"ת שנסמן לעיל שם."]]],[1300221093,"עקבתא דמשיחא האלט מען גאר נאענט צו ביאת המשיח, דערפאר פילט מען איצט דעם תוכן נעלה פון בחי' „מצורע\", כנ\"ל, אז די פנימיות פון כלל ישראל איז שוין נתברר געווארן (דורך דער עבודה פון אידן במשך כל הדורות), און עס איז געבליבן אויף צו מברר זיין נאר די פסולת און חיצוניות פון „סוף לבושיו\".\nיג. ע\"פ הנ\"ל איז אויך מובן וואס מ'געפינט אין סנהדרין⁷⁹, אז אליהו האט געזאגט צו רבי יהושע בן לוי אז משיח „יתיב ביני עניי סובלי חלאים\", און רש\"י איז מפרש: „מנוגעים והוא נמי מנוגע\": אויך — די שקו\"ט אין גמרא⁸⁰ וועגן שמו של משיח און לדעת רבנן „חיוורא דבי רבי שמו (מצורע של בית רבי — רש\"י) שנאמר⁸¹ אכן . . חשבנוהו מנוגע גו'\".\nאיז לכאורה תמוה: ווי קומט עס, אז משיח זאל אנגערופן ווערן „מנוגע\" און „מצורע\"?\nבשלמא דאס וואס משיח לייד־ט יסורים בכלל („ביני . . סובלי חלאים\") קען מען פארשטיין, ווי רש\"י הנ\"ל אין גמרא ברענגט דעם פסוק⁸² „והוא מחולל מפשעינו וכתיבי⁸¹ חליינו הוא נשא\", ועד\"ז ברענגען די רבנן אין גמרא די ראי' אויפן נאמען פון דעם פסוק הנ\"ל — וואס איז אבער דער דיוק און דער תוכן פון דעם ענין הנגעים של משיח?\nוע\"פ הנ\"ל י\"ל הביאור אים דעם*⁸²: נגעים ברענגען ארוים דעם מצב פון אידן אין זמן פון עקבתא דמשיחא, אז ס'איז דא די „התברורות הרע\" אין פנימיות הגוף והנפש (פון כלל ישראל) און ס'איז געבליבן רע נאר בחיצוניות, אזוי אז מ'האלט שוין באַ דעם מצב פון „זכו\".\n— ועפ\"ז איז מובן אויך דער ענטפער פון משיח צו ריב\"ל⁶⁶ (אויף זיין שאלה „לאימת אתי מר\", א\"ל היום\", און די הסברה פון אליהו „הכי אמר לך היום⁸³ אם בקולו תשמעו\"):\nכלל בתורה — אין מקרא יוצא מידי פשוטו⁸⁴, מען מיינט ניט שולל זיין דעם פירוש הפשוט פון „היום\" וואס משיח האט געזאגט, אז היום איז א מצב פון „זכו\" און מ'איז ראוי ער זאל קומען „היום\", נאר מען איז מסביר, אז דאס וואס „לא אתא\" איז ווייל עס האט גע־פעלט די שלימות פון „בקולו תשמעו\", דער גמר הבירור פון חיצוניות הרע —\nובפרט בדורותינו אלו, אז אידן הערן און פילן אז משיח איז „הנה⁸⁵ זה עומד אחר כתלינו⁸⁶\"; און נאכמער: דער כותל האט שוין „חלונות\" און „חרכים\", און נאכמער: משיח איז „משגיח⁸⁵ מן החלו־נות מציץ מן החרכים\" — ער איז „משגיח\" און קוקט אויס, ווען מיר וועלען שוין פארענדיקן די „פכים קטנים\", „צו־פוצן די קנעפלער\"⁸⁷ און פארענדיקן דעם בירור „שבסוף לבושיו\" —\nוואס דעמאלט קומט משיח תיכף ומיד, „ארו⁸⁸ עם ענני שמיא כבר אינש",[["83","83","תהלים צה, ז."],["84","84","שבת סג, א."],["85","85","שה\"ש ב, ט."],["86","86","ראה קול קורא לכ\"ק מו\"ח אדמו\"ר (נדפס בהקריאה והקדושה תש\"א. אגרות קודש אדמו\"ר מהוריי\"צ ח\"ה ע' תיד) דמפרש זה על משיח."],["87","87","ראה שיחת שמחת תורה תרפ\"ט."],["88","88","דניאל ז, יג (ושם: אנש) — הובא בסנהדרין שם, א."],["79","79","שם."],["80","80","שם ע\"ב."],["81","81","ישעי' נג, ד."],["82","82","שם, ה. *82) ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021428\" data-slug=\"likkutei-sichot\" data-id=\"1300021428\">לקו\"ש תזריע</a> תנש\"א. סה\"ש תנש\"א ח\"ב (ע' 491. 496 ואילך)."]]],[1300221094,"אתה\", ער קומט באופן פון אחישנה, וואַרום ס'איז א מצב פון „כולו זכאי דכתיב⁸⁹ ועמך כולם צדיקים לעולם יירשו ארץ\"⁶⁶,\n— פון דעם „וזרעתי לי בארץ\"⁹⁰ —\n„הבאים⁹¹ ישרש יעקב\" — ווערט דער „יציץ⁹¹ ופרח ישראל ומלאו פני תבל תנובה\", בקרוב ממש.\n(משיחות ש\"פ תזריע. תשמ\"א, ש\"פ תזו\"מ תשמ\"ב)",[["89","89","ישעי' ס, כא."],["90","90","הושע ב, כה."],["91","91","ישעי' כז, ו. וראה תו\"א ואוה\"ת ד\"ה זה (בפ' שמות)."]]],[1300221095,"<h3>מצורע</h3>\nא. נאך די פרשיות וועגן די דינים פון: זב¹, איש כי תצא ממנו שכבת זרע², נדה³, און זבה⁴ — איז די תורה מסיים (בסוף הסדרה): „זאת תורת הזב ואשר תצא ממנו שכבת זרע גו' והדוה בנדתה והזב את זובו לזכר ולנקבה גו'\".\nאיז רש\"י אויף דעם מפרש: „זאת תורת הזב, בעל ראי' אחת ומהו תורתו. ואשר תצא ממנו שכבת זרע, הרי הוא כבעל קרי טמא טומאת ערב. והזב את זובו, בעל שתי ראיות ובעל שלש ראיות שתורתן מפורשת למעלה\".\nלערנען מפרשים⁵, אז רש\"י'ס הכרח צו לערנען אז „זאת תורת הזב\" מיינט (ניט די „תורת הזב\" וועגן וועלכער עס רעדט זיך פריער אין פרשה, נאר) „בעל ראי' אחת\", וואס „תורתו\" ווערט ערשט געזאגט אין פסוק דא („ומהו תורתו, ואשר תצא ממנו שכבת זרע\") — איז פון דעם וואס די תורה חזר'ט איבער נאכאמאל (אין דעם פסוק שלאח\"ז⁶) — „והזב את זובו (לזכר)\".\nדעריבער לערנט רש\"י אז די צוויי פסוקים — „זאת תורת הזב\" און „והזב את זובו\" — ריידן וועגן צוויי סוגים:\nא) „זאת תורת הזב\" רעדט וועגן „בעל ראי' אחת\", און דאס וואס דער פסוק טיילט עס אויס פון זב בכלל, איז ווייל בעל ראי' אחת האט אן אנדער דין — „ומהו תורתו\" (פון דעם „בעל ראי' אחת\") — „הרי הוא כבעל קרי\".\nב) „והזב את זובו\" מיינט „בעל שתי ראיות ובעל שלש ראיות שתורתן מפורשת למעלה\"⁷.\nב. מען דארף אבער פארשטיין: דער פירוש — אז די צוויי סוגים (אין די צוויי פסוקים דא) זיינען „בעל ראי' אחת\" און „בעל שתי ראיות ובעל שלש ראיות\" — האט כו\"כ שוועריקייטן בדרך הפשט⁸, ווייל:\nא) פארוואס שטייט די „תורה\" פון בעל ראי' אחת ערשט בסיום הסדרה, נאך אלע אנדערע סוגים (און נאכן פסוק⁹ „והזרתם את בנ\"י מטומאתם גו'\") — און ניט פריער, ביי די דינים פון זב אדער בעל קרי¹⁰ (ובפרט אז ער איז דאך",[["1","1","פרשתנו טו, ב ואילך."],["2","2","שם, טז ואילך."],["3","3","שם, יט ואילך."],["4","4","שם, כה ואילך."],["5","5","ראה רא\"ם, ס' זכרון ובאר יצחק כאן. וראה קרבן אהרן לתו\"כ כאן."],["6","6","ופירושי רש\"י על ב' הפסוקים הם המשך אחד."],["7","7","כפרש\"י לעיל (טו, ג) מ„מדרשו\". וראה בארוכה לקמן בפנים."],["8","8","אף שלאידך — לפי פרש\"י יומתק זה שהפסוק (לב) מסיים „לטמאה בה\" — שלכאורה תיבות אלו מיותרות — כי כוונת הפסוק היא לפרש תורת הזב, שהוא טמא („לטמאה בה\") כמו „ואשר תצא ממנו גו'\" (אבל — רש\"י לא העתיק תיבות אלו בפירושו (אף שמסיים פירושו „טמא טומאת ערב\"), ומשמע שאין זו הוכחת רש\"י לפירושו)."],["9","9","טו, לא."],["10","10","וגם: מסתימת לשון רש\"י „ומהו תורתו. ואשר תצא ממנו גו'\" משמע, שכוונת רש\"י היא (לא להקיש זב לואשר תצא ממנו גו' — כמ\"ש במפרשי רש\"י ותו\"כ כאן — כ\"א) שה„ואי\"ו\" ד„ואשר תצא ממנו גו'\" הוא כמו „ואי\"ו הביאור\" (ראה רש\"י שמיני י, ט וברא\"ם שם. שיחת ש\"פ שמיני תשמ\"א), שאינו גלאטיק כ\"כ בפשש\"מ. ובפרט בנדו\"ד, שבפסוק שלאח\"ז נמנו עוד סוגים (בהמשך לפסוק זה), והוא\"ו בהם הוי ואי\"ו המוסיף."]]],[1300221096,"אויך א בעל ראי' אחת, און — ס'קען דאך ניט זיין „שתי ראיות\" סיידן ס'געווען פריער „ראי' אחת\")?\nב) לפ\"ז קומט אויס, אז מ'דארף מחלק זיין די ווערטער „זאת תורת\" לצדדין¹¹: בשייכות צו „(תורת) הזב\" מיינט עס — דאס פאלגנדע, וואס קומט שפעטער, איז „תורת הזב\"; און בשייכות צו „והדוה בנדתה והזב את זובו גו'\" מיינט „זאת תורת\" — דאס געזאגטע פריער („המפורשת למעלה\")!\nג) לפ\"ז איז דער סיום, דער סך־הכל פון די פריערדיקע פרשיות אינגאנצן ניט לויטן סדר אין וועלכן זיי שטייען: פרשת זב איז געקומען פאר „איש כי תצא ממנו שכבת זרע\" און נדה, און דא שטייט „והזב את זובו\" (וואס לויט רש\"י מיינט עס דער זב וואס תורתו „מפורשת למעלה\") נאך „והדוה בנדתה\" —\nאיז ניט מובן: הלמאי לערנט רש\"י (וואס איז פשוטו של מקרא¹²) אז די צוויי סוגים זיינען „בעל ראי' אחת\" און „בעל שתי ראיות ובעל שלש ראיות\" — ער האט געדארפט לערנען אז („זאת תורת גו'\" איז בלויז א סך־הכל פון פריער, און) „זאת תורת הזב\" מיינט „בעל שתי ראיות\" און „והזב את זובו\" — „בעל שלש ראיות\"¹³, ווי רש\"י האט שוין פריער געבראכט (אין תחלת פרשת זב¹⁴) אז זיי זיינען מחולקים צווישן זיך: „שתים לטומאה והשלישית מזקיקתו לקרבן\".\n[און דאס וואס די תורה שטעלט דעם פרט פון זב בעל שלש ראיות (ניט במקומו — פאר „ואשר תצא ממנו גו'\" — נאר) צוזאמען מיט א זבה, קען מען פארענטפערן, אז דאס איז ווייל נאר די צוויי האבן דעם דין מיוחד (וואס טיילט זיי אויס פון די אלע אנדערע סוגים דא)¹⁵, אז זיי דארפן האבן א קרבן¹⁶ (לכפר אויף דער טומאת הזיבה)].\nג. לכאורה וואלט מען געקענט ענטפערן, אז רש\"י'ן ארט דא דער כפל הלשון — „והזב את זובו\" (ניט ווי אין פריערדיקן פסוק „זאת תורת הזב\" וואו דער לשון זב שטייט בלויז איין מאל). און פון דעם נעמט רש\"י, אז דער פסוק איז דא מרמז אויף צוויי סוגים אין „זב\"",[["11","11","ראה ס' זכרון כאן."],["12","12","שמזה מובן שאין לומר שרש\"י כותב זה מפני שכן הוא בתו\"כ כאן — כי הלימוד בתו\"כ [שבפסוק הוקש זב בין לבעל קרי ובין לדוה בנדתה כו' — ראה רבינו הלל וקרבן אהרן שם. מפרשי רש\"י כאן] הוא ע\"ד הדרש (ובפרט שרש\"י משנה מלשון התו\"כ כאן — ראה רא\"ם וגו\"א כאן. וראה לקמן סעיף ח ואילך). ברש\"י פסחים (סז, ריש ע\"ב) דפסוק „זאת תורת הזב\" איירי בבעל ראי' אחת „דלא מנה בי' בהאי קרא אלא חדא זיבה דאזלינן בתר מניינא דקרא כדאמרינן במגילה (ח, א) מנה הכתוב שתים וקראו טמא כו'\" — והרי רש\"י הביא לעיל (טו, ג) דרשה זו (כדלקמן סעיף ג). אבל קשה לומר שזהו ג\"כ הכרחו של רש\"י כאן בפירושו עה\"ת (וסומך על פירושו לעיל) — כי (נוסף לזה, שא\"כ הול\"ל ע\"ז „ומדרשו\", כמ\"ש לעיל שם על הדרשה (דמגילה) שהביא — הרי) ע\"ד הפשט אין לדמות פסוק(ים) דילן לפסוקים (ודרשה) דלעיל, כדלקמן הערה 26."],["13","13","ולהעיר, שלגירסת הרא\"ם וגו\"א בתו\"כ כאן, הפסוק „זאת תורת הזב\" קאי (גם) על בעל שתי ראיות, ו„והזב את זובו\" (רק) על בעל שלש ראיות [ומ\"ש בגו\"א דזה שרש\"י לא כתב כן הוא מפני „שפירש הפשט\" — הרי מסיים שזהו מפני ש„לפי פשוטו (ד)זאת תורת הזב איירי בבעל ראי' אחת\"]."],["14","14","טו, ג."],["15","15","ע\"ד זה שהדין ד„ולאיש אשר ישכב עם טמאה\" נפרט כאן בפ\"ע ושלא במקומו. וראה לקמן הערה 20."],["16","16","טו, יד־טו. שם, כט־ל."]]],[1300221097,"— ע\"ד¹⁷ ווי רש\"י האט פריער אפגעלערנט דעם חילוק (הנ\"ל) צווישן „בעל שתי ראיות\" און „בעל שלש ראיות\" פון דעם כפל הלשון אין די צוויי פסוקים דארט: „מנה הכתוב הראשון ראיות שתים . . זב מבשרו זובו . . ומנה הכתוב השני ראיות שלש . . בזובו רר בשרו את זובו או החתים בשרו מזובו\" —\nאון וויבאלד אז אין די צוויי פסוקים (צוזאמען) ווערט געזאגט דריי מאל זב, דעריבער לערנט רש\"י, אז „זאת תורת הזב\" מיינט „בעל ראי' אחת\" און „והזב את זובו\" — „בעל שתי ראיות ובעל שלש ראיות\".\nאבער ס'איז שווער אזוי צו לערנען, ווייל דער כפל הלשון „והזב את זובו\" דא איז ניט אזא שטארקער דיוק (בדרך הפשט) — ס'איז ע\"ד (און נאכמער — עס קומט בהמשך צו) דעם כפל הלשון „והדוה בנדתה\"¹⁸; ובמילא האט ניט קיין ארט צו זאגן, אז צוליב דעם זאל רש\"י לערנען אזא ווייטן פירוש (— זאגן אז דאס איז פשט) אין „זאת תורת הזב ואשר גו'\".\nנוסף לזה: אפילו אויב מ'זאל אננעמען אז דער כפל הלשון („והזב את זובו\") איז יע א דיוק אין דרך הפשט — איז אבער דער אופן הלימוד (אז דער כפל הלשון איז מרמז אויף צוויי סוגים) נאר אן ענין של מדרש\n— ווי רש\"י זאגט פריער¹⁴ ביים חילוק צווישן „שתי ראיות\" און „שלש ראיות\" (וואס מ'לערנט אפ פון „מנה הכתוב . . ראיות שתים . . ראיות שלש\") אז דאס איז (ניט „פשוטו\", נאר) „מדרשו\" —\nהאט רש\"י אויך דא געדארפט מדגיש זיין, אז זיין פירוש איז מדרשו.\nד. וי\"ל דעם ביאור אין דעם:\nדער לשון „זאת תורת הזב\" איז ע\"ד „זאת תורת העולה גו' המנחה וגו'\" (מיינט אלע עולות מנחות וכו'¹⁹ — אלע סוגים) לערנט רש\"י אז דא איז די תורה כולל און וויל מפרט זיין אלע סוגי זב ועל הסדר: מן הקל אל החמור²⁰.\nועפ\"ז ווערט פארענטפערט וואס די תורה שטעלט „והזב את זובו לזכר\" — ניט וואו עס רעדט זיך וועגן זב פריער אין פרשה, נאר מיט — „ולנקבה\" זב צוזאמען מיט זבה, ווייל זיי האבן ביידע דעם זעלבן חומר.\nעפ\"ז ווערט אבער שווער: דא שטייט דאך פריער „(תורת) הזב\", פאר „ואשר תצא ממנו גו'\" — „ואשר\" בתוספת וא\"ו, וואס באווייזט אז „הזב\" דא איז (אויך) א פרט אין כללות הסוג פון „זב\" — דארף לפ\"ז אויסקומען אז (ס'איז דא) א זב וועלכער איז קל בדינו פון „ואשר תצא גו'\"!\nאון וויבאלד אז מ'קען ניט זאגן אז א זב בעל שתי ראיות זאל זיין גלייך ועל אחת כו\"כ קל פון ואשר תצא גו'²¹, מוז",[["17","17","ולא ממש, שהרי שם מנה הראיות, וכאן — סוגים בזב. וראה לקמן הערה 26."],["18","18","והרי רש\"י לא פירש טעם כפל לשון זה — אף שיש פירושים ע\"ד הדרש (ראה תו\"כ עה\"פ. שבת סד, ב. נדה נד, ב)."],["19","19","פרש\"י ויקרא ו, ב. שם, ז."],["20","20","ואף שמסיים ב„ולאיש אשר ישכב עם טמאה\" — אף שטומאתו אינה חמורה כ\"כ כמו זב וזבה (שהרי אין צריך קרבן לכפר על טומאתו) — כי בזה יש גם איסור (כרת). ולהעיר מבחיי כאן (בטעם שסיים הכתוב עם „אשר ישכב עם טמאה\")."],["21","21","שהרי זב חמור מבעל קרי, כמפורש בפרשת זב. ואין לומר שזב בעל שתי ראיות יהי' קל מבבעל קרי (שטמא אף בראי' אחת)."]]],[1300221098,"מען זאגן אז „זאת תורת הזב\" מיינט „בעל ראי' אחת\".\nה. מען דארף אבער פארשטיין וואס רש\"י זאגט — „והזב את זובו, בעל שתי ראיות ובעל שלש ראיות שתורתן מפורשת למעלה\":\nפון דיוק לשון רש\"י „בעל שתי ראיות ובעל שלש ראיות²² שתורתן²³ מפורשת למעלה\" איז מוכח, אז לויט רש\"י רעדט דער פסוק „והזב את זובו\" וועגן צוויי סוגי זב²⁴ — איז ניט מובן: דער ביאור הנ\"ל (סעיף ד) איז בלויז א הכרח אז „זאת תורת הזב\" רעדט וועגן „בעל ראי' אחת\", און „והזב את זובו\" — וועגן א זב וואס איז חמור פון „ואשר תצא ממנו גו'\" (און „והדוה בנדתה\"²⁵); אבער פון וואנעט איז דער הכרח (פון פשטות הכתובים דא) אז „והזב את זובו\" איז כולל צוויי סוגים — „בעל שתי ראיות ובעל שלש ראיות\"²⁶?\nלכאורה קען מען ענטפערן, אז וויבאלד רש\"י האט שוין פריער געבראכט (עכ\"פ אלס „מדרשו\") אז עס זיינען פאראן צוויי סוגי זב (שתי ראיות און שלש ראיות), איז ער מפרט דא (נאכאמאל) די צוויי סוגים.\nאבער עס איז ניט גלאטיק לשון רש\"י „שתורתן מפורשת למעלה\" — אז זייערע דינים, וואס דאס מיינט במילא אויך די חילוקים שביניהם²⁴, איז „מפורשת למעלה\": מ'האט געדארפט זאגן „תורתן נדרשת למעלה\", ווי רש\"י אליין זאגט „למעלה\" — אז דער חילוק צווישן שתי ראיות ושלש ראיות איז (ניט פשוטו פון די פסוקים, נאר) „מדרשו\"?\nו. איז דער ביאור אין דעם: דאס וואס רש\"י פריער ברענגט „ומדרשו\", איז דאס ניט ווי אין אנדערע ערטער, וואו לויט „מדרשו\" איז דער פירוש אין פסוק אנדערש ווי לויט „פשוטו\" — נאר בנדו\"ד, איז אויך לויט „מדרשו\" איז דער פירוש אין פסוק ווי לויט „פשוטו\"²⁷ ( — „מדרשו\" גייט (בעיקר) אויף (איז מוסיף נאך) אן ענין וואס איז מרומז אין פסוק);\nולאידך גיסא, איז דער דרש (ניט נאר „מיישב\" דעם פשט, נאר) „מוכרח\" לויט „פשוטו\"²⁸ — ווייל דוקא לויטן דרש (בל' רש\"י²⁹ — אגדה לישב פשוטו ש\"מ) ווערט פארענטפערט די אריכות",[["22","22","בדפוס ראשון ושני וכמה כת\"י רש\"י — תיבה זו ליתא."],["23","23","בדפוס שני וכמה כת\"י רש\"י — „שתורתו\". אבל בדפוסי רש\"י שלפנינו הוא כבפנים. ובא' מכת\"י רש\"י (שתח\"י) — „שתורתם\"."],["24","24","בבאר מים חיים (לאחי המהר\"ל) כאן משמע, שמפרש שכוונת רש\"י היא (לא לב' סוגים בזב, כ\"א) לבעל „ריבוי זיבות\" (בניגוד ל„בעל ראי' אחת\"). ו„תורתן מפורשת למעלה\" היינו הצד השווה בין בעל ב' וג' ראיות (שצריכים ז' נקיים). אבל מאריכות לשון רש\"י „בעל שתי ראיות ובעל שלש ראיות שתורתן כו'\" משמע, שכוונתו לב' הסוגים שהזכיר לעיל בפירושו. ואולי היתה לפניו הגירסא שבדפוס שני דרש\"י (הנ\"ל בהערה שלפנ\"ז)."],["25","25","או עכ\"פ שקול כנדה. וראה רמב\"ן סוף פרשתנו („על דרך הפשט\")."],["26","26","במפרשים (רבינו הלל וקרבן אהרן לתו\"כ כאן. רא\"ם, גו\"א ושפ\"ח כאן) דג' זיבות שנאמרו כאן (בב' הפסוקים) מורות על בעל ג' זיבות. והוא ע\"ד פרש\"י לעיל טו, ג (וראה לעיל הערה 12). אבל ע\"ד הפשט אינו דומה פרש\"י לעיל לנדו\"ד, כי בפסוק דילן („והזב את זובו\") נאמרו רק ב' זיבות (אף שי\"ל שמצטרף ל„זאת תורת הזב\"): משא\"כ בפרש\"י לעיל, שבהכתוב שאיירי בבעל שתי ראיות נאמרו ב' זיבות בפ\"ע, ובכתוב שאיירי בבעל ג' ראיות — ג' ראיות בפ\"ע."],["27","27","ראה עד\"ז באר יצחק לעיל שם."],["28","28","להעיר ממשנ\"ת (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211033\" data-slug=\"likkutei-sichot\" data-id=\"1300211033\">לקו\"ש חכ\"א ע' 33</a> ואילך) בביאור דברי רש\"י (וארא ו, ט בסופו) „יתיישב המקרא על פשוטו . . והדרשה תדרש\", שכוונת רש\"י בזה היא, שהפשט מכריח הדרש, ע\"ש."],["29","29","בראשית ג, ח."]]],[1300221099,"לשון הפסוק (וואס איז שווער לויט „פשוטו\"):\nפריער³⁰ שטייען צוויי פסוקים: „איש כי יהי' זב מבשרו זובו טמא הוא. וזאת תהי' טומאתו בזובו רר בשרו את זובו או החתים בשרו מזובו טומאתו היא\", און דערנאך (אין דעם פסוק שלאח\"ז) הויבן זיך אן די פרטי דינים פון טומאת הזב — „כל המשכב וגו'\".\nאיז ניט פארשטאנדיק: פארוואס איז די תורה מפסיק צווישן „וזאת תהי' טומאתו בזובו\" און די דיני הטומאה („כל המשכב וגו'\") מיט די ווערטער „רר בשרו גו' או החתים בשרו גו'\", וואס זיינען (ניט דינים אין טומאת הזב, נאר) צוויי אופנים אין זיבה [„רר בשרו\" — „ריר שיוצא צלול\"³¹; „החתים בשרו\" — „שיוצא עב וסותם את פי האמה\"³¹] —\nדי ווערטער „רר בשרו את זובו או החתים בשרו מזובו\" האבן לכאורה געדארפט שטיין אין דעם פריערדיקן פסוק: „איש כי יהי' זב מבשרו, רר בשרו את זובו או החתים בשרו מזובו, זובו טמא הוא\" (און דערנאך: „וזאת תהי' טומאתו כל המשכב גו'\")?\nאויף דעם קומט „מדרשו\" און פארענטפערט — „מנה הכתוב הראשון . . וקראו טמא . . הכתוב השני . . וקראו טמא\": די תורה איז דערמיט מרמז אויף צוויי סוגים אין זב, וואס זייער טומאה איז ניט גלייך; און דערפאר שטייען זיי אין צוויי באזונדערע פסוקים („הכתוב הראשון . . הכתוב השני\"³²), און יעדן\nפון זיי באזונדער — „קראו טמא\" (וויבאלד זייער טומאה איז ניט גלייך).\nוואס זיינען די צוויי סוגי זב (און וואו איז דער חילוק ביניהם מרומז אין פסוק)? — זאגט רש\"י, אז יעדער „זוב\" וואס ווערט דערמאנט אין פסוק איז מרמז אויף נאך א ראי'; ובמילא — רעדט דער „כתוב הראשון\" וועגן איינעם וואס האט געזען ראיות שתים, און „כתוב השני\" — וועגן איינעם וואס האט געזען ראיות שלש.\nקומט אויס, אז פשוטו של מקרא דארטן איז מכריח (אז מ'דארף דרש'נען דעם יתור הלשון, ובמילא —) אז עס זיינען דא צוויי סוגים אין זב — בעל שתי ראיות און בעל שלש ראיות.\nז. וויבאלד אז דער „מדרשו\" בנדו\"ד איז אזא וואס איז מוכרח מצד „פשוטו\" (כנ\"ל), איז פארשטאנדיק, אז אויך דער חילוק אין דין צווישן זיי (וואס רש\"י ברענגט) — „שתים לטומאה והשלישית מזקיקתו לקרבן\" — איז (ניט בלויז העתקת לשון חז\"ל³³, וועלכער איז ניט היפך הפשט, נאר ס'איז) מוכרח אין פשוטו של מקרא.\nוהביאור: וויבאלד אז „וזאת תהי' טומאתו\" באציט זיך בפשטות צו דעם „טמא הוא\" וואס שטייט אין פריערדיקן פסוק (ביי בעל שתי ראיות), דארף מען זאגן, אז די דיני טומאה וועלכע שטייען בהמשך הפרשה זיינען דא אויך ביי בעל שתי ראיות³⁴.\nמוז מען במילא זאגן, אז די הוספה פון בעל שלש ראיות אויף בעל שתי",[["30","30","טו, ב־ג."],["31","31","פרש\"י שם."],["32","32","ע\"פ המבואר בפנים יומתק טעם הוספה זו של רש\"י (הראשון . . השני) על לשון הש\"ס (מגילה ח, א. נדה מג, ב)."],["33","33","מגילה ונדה שם (בשינוי לשון קצת)."],["34","34","משא\"כ ע\"ד הדרש וההלכה, שיש לימוד מיוחד שבעל שתי ראיות צריך ז' נקיים (תו\"כ פרשתנו טו, יג. מגילה שם, א־ב)."]]],[1300221100,"ראיות איז ניט אין דעם עצם ענין (ואופן) הטומאה — „טמא הוא\" — נאר אין דעם וואס „(שתים לטומאה) והשלישית מזקיקתו לקרבן\"³⁵. — ניט „מחייבתו קרבן\" וואס „זיקה\" מיינט — נויטיקייט אין א נייער (זייטיקער) זאך.\nועפ\"ז איז מובן וואס רש\"י זאגט בסיום הסדרה „בעל שתי ראיות ובעל שלש ראיות שתורתן מפורשת למעלה\" — ווייל דער חילוק הנ\"ל צווישן שתי ראיות און שלש ראיות איז מוכרח אויך מצד „פשוטו\" (כנ\"ל בארוכה); ובמילא, אז רש\"י וויל אפטייטשן וועלכער „זב\" — איז תורתו „מפורשת למעלה\"³⁶ — ניט ווי בעל ראי' אחת וואס תורתו שטייט ערשט בסיום הסדרה — ברענגט ער ביידע סוגים אין זב.\nח. פון די ענינים מופלאים ע\"ד ההלכה אין פירוש רש\"י זה:\nדער תוכן פון פירוש רש\"י בסיום הסדרה שטייט אין תורת כהנים אויפן פסוק, נאר מיט כמה שינויים — ווי מפרשי רש\"י³⁷ שטעלן זיך אויף זיי. ס'איז אבער דא א שינוי לשון אויף וועלכן לא מצאתי לע\"ע אז מ'שטעלט זיך — וואס יש לומר, אז אין דעם שינוי ליגט א גאנצער ענין, און א לשיטתי' פון תו\"כ (הלכה) אדער — פירוש רש\"י (פשוטו ש\"מ):\nאין תו\"כ איז דער לשון: „. . זה שראה ראי' אחת . . זה שראה³⁸ שתי ראיות . . זה שראה שלש ראיות\"; און רש\"י איז משנה³⁹ און זאגט: „בעל ראי' אחת . . בעל שתי ראיות ובעל שלש ראיות\".\nוועט מען דאס פארשטיין בהקדים וואס מ'געפינט אין גמרא⁴⁰ צוויי לימודים אויף דעם חילוק פון שתי ראיות און שלש ראיות:\nא) די דרשה פון ר' סימאי⁴¹ (וואס רש\"י ברענגט דא אראפ⁴²): „מנה הכתוב שתים וקראו טמא שלש וקראו טמא הא כיצד שתים לטומאה ושלש לקרבן\".\nב) די דרשה פון די חכמים: „זובו חדא רר בשרו תרי את זובו תלת לימד על זב בעל שלש ראיות שחייב בקרבן. או החתים בשרו מזובו טמא מקצת זובו טמא לימד על זב בעל שתי ראיות שמטמא משכב ומושב\".\nיש לומר אז עס איז א נפק\"מ צווישן די צוויי לימודים — אין דעם גדר פון א זב בעל שתי ראיות — וואס מ'קען לערנען אויף צוויי אופנים⁴³:",[["35","35","אף שגם הקרבן שייך לטומאת הזב, שהרי בא לכפר מזובו (פרשתנו טו, טו) — מ\"מ אינו דין בהטומאה (כמו הדינים שלפנ\"ז)."],["36","36","וזה גופא היא כוונת רש\"י במ\"ש „שתורתן מפורשת למעלה\" — שההכרח לפרש ד„והזב את זובו\" קאי על „בעל ב' ראיות ובעל ג' ראיות\", הוא (לא מלשון הכתוב כאן — כפירוש המפרשים שנסמנו בהערה 26 — כ\"א) מפני „שתורתן מפורשת למעלה\", וכאן הוא הסך־הכל מהפרשיות דלמעלה."],["37","37","רא\"ם וגו\"א כאן."],["38","38","בכמה דפוסים „זו שראתה\". אבל לכאורה צ\"ל כהגירסא שהובאה בפנים (שהרי קאי על זב)."],["39","39","ביל\"ש כאן גריס (בתו\"כ): בעל שתי ראיות."],["40","40","נדה שם."],["41","41","דרשתו הובאה גם במגילה שם. וכן סתם בפיה\"מ להרמב\"ם ריש זבים."],["42","42","ראה בארוכה נחלת יעקב כאן."],["43","43","וראה עד\"ז חקירה זו בשומרת יום כנגד יום, אם היא פרט בזבה גדולה או גדר בפ\"ע — <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071118\" data-slug=\"likkutei-sichot\" data-id=\"1300071118\">לקו\"ש ח\"ז ע' 106</a> ואילך (ע\"ש באורך). *) אבל לא ממש, כי שם השאלה היא האם הענין דשומרת יום הוא מפני שהראי' יכולה להצטרף ולהביא לידי זיבה גדולה; משא\"כ בנדו\"ד, שדין טומאת זב בעל שתי ראיות הוא גם כשהראי' היא מסוג אחר שאין שייך לצרפה לשלש ראיות — כי"]]],[1300221101,"א) זב בעל שתי ראיות וזב בעל שלש ראיות זיינען צוויי אינגאנצן באזונדערע מציאות'ן. די טומאה פון בעל שתי ראיות איז ניט די זעלבע טומאה פון (די שתי ראיות פון דעם) בעל שלש ראיות, זי איז אן ענין בפני עצמו — די צוויי ראיות מצד עצמן זיינען מחייב טומאת זב וספירת ז' נקיים.\nב) די טומאה פון בעל שתי ראיות איז א חלק פון דער טומאה פון א זב בעל שלש ראיות. והיות אז ער איז א חלק פון שלש ראיות, באקומט ער אויך נאר א חלק פון דיני טומאת בעל שלש ראיות.\n[עפ\"ז קען מען מבאר זיין וואס עס שטייט אין תרגום יונתן בן עוזיאל אויפן פסוק⁴⁴ „איש כי יהי' זב גו'\" — „חמא תלת זימני\" (און דערמאנט ניט כלל דעם דין פון בעל שתי ראיות): די טומאה פון בעל שתי ראיות איז א חלק פון בעל שלש ראיות].\nט. איינע פון נפקא מינה'ס וואס מ'קען זאגן בדרך אפשר להלכה בפועל⁴⁵: אויב עס איז געווען א הפסק (יום) צווישן דער דריטער ראי' און די ערשטע צוויי ראיות, צי זיי ווערן אלע נצטרף און ער באקומט א דין פון א בעל שלש ראיות אדער ניט (וואס דאס איז א\nפלוגתא (לדעת ר' אליעזר בן יהודה⁴⁶) צווישן בית שמאי און בית הלל):\nאויב מ'זאל אננעמען, אז טומאת בעל שתי ראיות איז אן ענין בפני עצמו, הייסט עס אז נאך די צוויי ראיות ווערט גלייך א חיוב (מצד עצמו) צו ציילן ז' נקיים (סיידן אויב מ'זעט גלייך א דריטע ראי', איז איגלאי מילתא אז ער איז א בעל שלש ראיות).\nולפ\"ז דארף אויסקומען, אז אויב עס איז געווען (נאך די צוויי ראיות) א הפסק (יום), ס'איז נתברר געווארן אז ער איז ניט קיין בעל (שלש) ראיות, איז איגלאי מילתא אז ער האט (גלייך נאך דער צווייטער ראי') דעם דין פון א בעל שתי ראיות; און אז ער זעט אין דעם יום שלאחרי ההפסק א ראי', איז דאס א נייער ענין, עס ווערט ניט נצטרף צו די פריערדיקע צוויי ראיות⁴⁷.",[["44","44","טו, ב."],["45","45","גם י\"ל שזהו פלוגתת ר' יוסי וחכמים (זבים פ\"א מ\"ה) אם ראה אחת מרובה כשתים הוי כשתי ראיות, כמו ראה אחת מרובה כשלש שילפינן מקרא דהוי כג' ראיות, דלר\"י אין הדין מבעל ג' נמשך לבעל ב' (פיה\"מ להרמב\"ם שם) — אף שלכאורה כש\"כ הוא דמרובה כשתים צ\"ל מתחלק לשתים (כמ\"ש במשנה אחרונה שם). טומאת ב' ראיות היא גם אם ראי' הא' היתה באונס, משא\"כ טומאת ג' ראיות להצריך קרבן היא רק אם ראי' הא' היתה ברצון (נדה לה, א. רמב\"ם הל' מחוסרי כפרה פ\"ב ה\"ה)."],["46","46","זבים פ\"א מ\"א. ובתוספתא שם (פ\"א, ב) דחזר רע\"ק להיות שונה כדבריו. ולהת\"ק במשנה (זבים שם. משנה ראשונה דרע\"ק תוספתא שם, א) דפלוגתת ב\"ש וב\"ה היא ב„ראה אחת ובשני הפסק ובשלישי ראה שתים\" — י\"ל שס\"ל שפליגי בגדר דבעל ראי' אחת אי הוי פרט בזב (גמור) או לא, ותלוי בפלוגתתם שלפנ\"ז (במשנה ותוספתא שם. וראה חסדי דוד לתוספתא שם) אי בעל ראי' אחת הוי כשומרת יום או כבעל קרי (לדעת המהרש\"א (נדה עב, ב) דלב\"ש „בראי' שני' של זוב הוה זוב גמור למפרע\". אבל ראה משנה אחרונה זבים שם). אבל להעיר דבשומרת יום כנגד יום ס\"ל לב\"ש דגם „הרואה יום אחד עשר\" שאא\"פ להצטרף לזבה גדולה הוי שומרת יום דאורייתא (משנה סוף נדה), ובנדו\"ד (זב בעל ראי' אחת) ס\"ל דהראיות מצטרפות. אבל ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071126\" data-slug=\"likkutei-sichot\" data-id=\"1300071126\">לקו\"ש שם (ע' 114</a> ואילך) שי\"ל, שלב\"ש גם ברואה יום י\"א ישנו הענין דחזי לאצטרופי לזבה גדולה, אלא שהוא בכח, ע\"ש. ואכ\"מ."],["47","47","ולכן לא קבלו ב\"ה מ\"ש להם ב\"ש (תוספתא שם, ב) „הואיל ונזקק לספירת שבעה בטל הראיי' את יום הטהור\" — כי אף ש„בטל הראיי' את יום"]]],[1300221102,"אויב אבער די טומאה פון בעל שתי ראיות איז א חלק אין דעם גדר פון טומאת בעל שלש ראיות, דארף אויסקומען, אז אפילו נאך דעם ווי ס'איז דורכגעגאנגען איין טאג פון די ז' נקיים (נאך די צוויי ראיות), ווערט די שפעטערדיקע דריטע ראי' נצטרף צו די פריערדיקע צוויי. ווייל די ספירת ז' נקיים נאך צוויי ראיות איז (ניט ווייל די צוויי ראיות מצד עצמן זיינען דאס מחייב, נאר) ווייל זיי זיינען א חלק „ומקצת\" פון שלש ראיות⁴⁸.\nיו\"ד. און דאס איז אויך דער חילוק צווישן די צוויי לימודים הנ\"ל:\nלויט דער דרשה אז מ'לערנט אפ זב בעל שתי ראיות פון פסוק „מזובו — מקצת זובו טמא\", איז א זב בעל שתי ראיות א „מקצת\" פון א זב (גמור), בעל ג' ראיות.\nמשא\"כ לויט דרשת ר' סימאי „מנה הכתוב שתים כו'\" — די תורה רעכנט „שתים\" באזונדער און „שלש\" באזונדער, און אין צוויי באזונדערע פסוקים — זיינען דאס צוויי באזונדערע סוגים אין זב⁴⁹.\nועפ\"ז קען מען אויך מבאר זיין דעם חילוק צווישן לשון התורת כהנים ולשון רש\"י בסיום הסדרה:\nדער תורת כהנים ברענגט פריער⁵⁰ אראפ דעם לימוד „מזובו — מקצת זובו\"; און דערפאר זאגט ער דא דעם לשון „זה שראה⁵¹ שתי ראיות . . שלש ראיות\", דער לשון איז מדגיש די ראיות בפועל: זיי זיינען אין דעם זעלבן גדר, ס'איז נאר א חילוק אין כמות וויפל ראיות עס זיינען (שוין) געווען.\nרש\"י וועלכער ברענגט דרשת ר' סימאי (כנ\"ל) האלט, אז דאס זיינען באזונדערע מענשן, א באזונדער „בעל שראה\"; און דערפאר איז ער מדייק ומפרט בלשונו⁵² „בעל ראי' אחת . . בעל שתי ראיות ובעל שלש ראיות\"⁵³ — יעדער פון זיי איז א באזונדער „בעל\" לעצמו.\n(משיחת ש\"פ מצורע תשכ\"ה)",[["","","הטהור\", אא\"פ להראי' שלאח\"ז להצטרף להראיות שלפנ\"ז, כי כבר חל עליו הגדר דזב בעל שתי ראיות."],["48","48","עפ\"ז יש מקום לומר, שגם אם הי' הפסק יותר מיום א' מצטרפת ראי' הג' לב' הראיות הראשונות, מכיון שכל הטומאה (וספירת ז' נקיים) של ב' ראיות הוא מפני שהן ההתחלה של שלש ראיות. אלא שלדעת ר\"א ב\"ר ינאי בתוספתא שם, גם לב\"ש מצטרפות הראיות רק אם היו כולם בתוך ג' ימים. וראה משנה אחרונה זבים שם."],["49","49","ואף שגם לר' סימאי איצטריך הדרשה „מזובו, מקצת זבין מביאין קרבן כו'\" (מגילה שם. וראה רש\"י שם ד\"ה מזובו), וכן יליף שבעל ב' ראיות טעון ז' נקיים דכתיב „מזובו וספר, מקצת זובו וספר\" (מגילה שם ואילך) — מ\"מ: א) י\"ל שזהו רק בלימוד ע\"ד ההלכה, ב) היסוד שיש חילוק בין ב' וג' (לר' סימאי) הוא מזה ש„מנה הכתוב שתים כו'\", ו„מזובו\" ילפינן רק באיזה ענין הם חלוקים (שתים לטומאה ושלש לקרבן). וכן דגם שתים טעון ז' נקיים)."],["50","50","עה\"פ טו, ג. וראה שם, יג. שם, טו."],["51","51","ולהעיר, שגם לעיל שם הלשון בתו\"כ הוא: מקצת זובו . . את שראה שתי ראיות — דלא כהלשון בנדה שם „לימד על בעל ג' ראיות . . מקצת זובו טמא לימד על בעל ב' ראיות כו'\"."],["52","52","לשון זה („בעל ב' . . בעל ג'\") רגיל בכ\"מ (וכ\"ה הלשון גם בהדרשה ד„מזובו מקצת זובו\", כבהערה שלפנ\"ז) — והדיוק שבפנים הוא מזה שרש\"י משנה מלשון התו\"כ על אתר."],["53","53","ולא „בעל שתי ראיות ושלש ראיות\"."]]],[1300221103,"<h3>אחרי</h3>\nא. בתחלת פרשתנו, וואו עס ווערט דערציילט „ויאמר ה׳ אל משה דבר אל אהרן גו׳ ואל יבא בכל עת אל הקודש גו׳ בזאת יבוא אהרן אל הקודש“, שטייט אין פסוק¹: „כתונת בד קודש ילבש גו׳“.\nשטעלט זיך רש״י אויף די ווערטער „כתונת בד גו׳“ און איז מפרש: „מגיד שאינו משמש לפנים² בשמונה בגדים שהוא משמש בהם בחוץ שיש בהם זהב³ לפי שאין קטיגור נעשה סניגור⁴, אלא בארבעה ככהן הדיוט וכולן של בוץ“.\nבפשטות איז דער פשט אין פירוש רש״י⁵: ער קומט דאָ פארענטפערן וואָס דאָ שטייט דער ציווי אויף אנטאָן די בגדים („כתונת בד קודש ילבש גו׳ בגדי קודש הם גו׳ ולבשם“) ווי א נייע זאַך, א חידוש דבר: בשעת דאָס איז שוין מפורש נאָך אין פ׳ תצוה⁶, סיי דעם עצם חיוב צו מאַכן די בגדים און סיי דער חיוב זיי צו טראָגן, „בבואם אל אהל מועד או בגשתם אל המזבח לשרת בקודש ולא ישאו עון ומתו גו׳“⁷.\nוואָס גיט צו דער ציווי דאָ ביים דיבור לאהרן?\nאיז רש״י מבאר, אַז דער פסוק קומט דאָ זאָגן, „מגיד“ — (ניט אויסצורע־כענען די בגדי כהונה און דעם ציווי אַז מ׳דארף זיי אנטאָן ווען מ׳גייט אריין צו טאָן די עבודה בקודש, נאָר) אַז ער דארף אנטאָן בלויז ד׳ בגדים, און ניט די „שמונה בגדים“ (וועגן וועלכע מ׳האט געלערנט פריער אין פ׳ תצוה אַז אין זיי איז אהרן משמש אלע מאָל).\nב. מען דארף נאָך אבער פארשטיין:\nהוספת תיבת „מגיד“ אין פירוש רש״י איז בדרך כלל אין א פאַל ווען דער ענין וואָס רש״י זאָגט שטייט ניט בפשט הפסוק מפורש, נאָר „מגיד“ — דער פסוק קומט זאָגן א געוויסע זאַך, נוסף אויף דעם וואָס ער זאָגט בפירוש⁸. איז דאָ ניט פארשטאַנדיק: דער ענין אז ער טוט אן נאָר ארבעה בגדים, ניט שמונה בגדים, שטייט בפירוש אין דעם פסוק?\nאויך דארף מען פארשטיין דעם סיום פון לשון רש״י „אלא בארבעה ככהן הדיוט וכולן של בוץ“:\nא) מען זעט אין פסוק אז דאָ זיינען אויסגערעכנט ארבעה בגדים, איז וואָס דארף עס רש״י זאָגן?\nב) וואס איז ער מוסיף ומחדש „ככהן הדיוט“; מ׳וויס דאס שוין פון פריער (אין פ׳ תצוה⁹) אז א כהן הדיוט טראָגט נאָר „ארבעה בגדים“.\nג) בכל אופן: למאי נפק״מ אז דאס איז „ככהן הדיוט“?\nד) „וכולן של בוץ“ — עס שטייט",[["1","1","טז, ד."],["2","2","כ״ה בדפוסי רש״י שלפנינו. וכ״ה גם בדפוס ראשון, ובא׳ מכת״י רש״י (שתח״י) — „בפנים“. ובדפוס שני ובכמה כת״י רש״י ליתא תיבת „לפנים“."],["3","3","בדפוס ראשון וא׳ מכת״י רש״י (שתח״י) ליתא „שיש בהם זהב“. אבל כ״ה בשאר הדפוסים וכת״י רש״י (שתח״י)."],["4","4","מקורו בגמ׳ ר״ה כו, א. דיעה הא׳ בויק״ר פכ״א, יו״ד. ירושלמי יומא פ״ז ריש ה״ג."],["5","5","ראה גו״א, דבק טוב ושפ״ח כאן."],["6","6","כח, ב ואילך."],["7","7","שם כח, מג."],["8","8","ראה לדוגמא פרש״י פרשתנו יח, ג. ובכ״מ."],["9","9","שם כח, מ־מב."]]],[1300221104,"בפירוש אין פסוק ביי יעדערן פון די בגדים אז ער זאל זיין פון „בד“. וואס איז רש״י מוסיף „וכולן של בוץ“?\nג. לכאורה וואלט מען געקענט לערנען אז רש״י קומט שולל זיין גאר אן אנדער פירוש:\nלערנענדיק דעם פסוק „כתונת בד קודש גו׳“, וואלט מען געקענט זאגן: היות אז מ׳וויס שוין פון פרשת תצוה¹⁰ אז אהרן כהן גדול האט שמונה בגדים וואס זיי אלע זיינען „לכבוד ולתפ־ארת“¹¹, ווי קומט עס אז ביים אריינגיין אחת בשנה לקודש הקדשים זאל ער אנטאן נאר פיר פון די בגדים, און ניט די אנדערע פיר — ממעט זיין אין דעם „לכבוד ולתפארת“¹²?\nמצד דעם וואלט מען געלערנט, אז דער פסוק קומט ניט זאגן אז ער דארף אנטאן נאר די פיר בגדים, וואַרום ס׳איז פשוט אז ער דארף אנטאן (במכש״כ פון א גאנץ יאר) אלע שמונה בגדים (און ווי ס׳איז משמע פון מפרשי התורה¹³). דער פסוק קומט זאגן דעם שינוי¹⁴ שביום הכיפורים — אז די ד׳ בגדים דארפן זיין דאמאלס (ביום הכפורים) אנדערש: א גאנץ יאר זיינען די ד׳ בגדים (ווי געזאגט אין פ׳ תצוה¹⁵) „הכתונת שש מצנפת שש ואבנט שש גו׳“, געווען „שש משזר“¹⁶, משא״כ דא ביוהכ״פ איז „כתונת בד ומכנסי בד גו׳ ובאבנט בד גו׳ ובמצנפת בד גו׳“ — ניט „שש משזר“, נאר איין חוט¹⁷. און דערי־בער רעדט דער פסוק נאר וועגן (דער לבישה פון) די ד׳ בגדים.\nאון דאס איז רש״י שולל מיט זיין פירוש „מגיד כו׳“ — ניט ווי מ׳האט גע־קענט לערנען אז דער פסוק איז נאר מפרט דעם שינוי, וועלכער איז נאר אין די ד׳ בגדים (אבער ער איז ניט שולל די לבישה פון די אנדערע ד׳ בגדים), נאר „אינו משמש לפנים בשמונה בגדים“, דער פסוק קומט שולל זיין די בגדים „שהוא משמש בהם בחוץ“, „אלא בארבעה ככהן הדיוט“.\nד. אבער אויך דער פירוש איז שווער, ווייל¹⁸\n[נוסף לזה וואס אויך לפירוש זה איז ניט גלאטיק די הוספה „מגיד“, וואַרום סוף סוף איז רש״י ניט מוסיף אויף המפורש בפסוק, ער איז בלויז שולל א פירוש מוטעה ניט ווי די משמעות הפסוק — איז נוסף אויף דעם]",[["10","10","כח, ד ואילך."],["11","11","כח, ב."],["12","12","ואף שגם בבגדי כהן הדיוט נאמר (שם כח, מ) „לכבוד ולתפארת“ — מובן, שאינו דומה לשמונה בגדי כה״ג. וראה רמב״ן שם, ב. רשב״ם שם, מ. סהמ״צ להרמב״ם מ״ע לג. — ועפ״ז מובנים דברי חז״ל (פרש״י במגילה יב, א ד״ה בגדי — מאסת״ר שם. ועוד) — כה״ג דוקא."],["13","13","ראה ראב״ע כאן. רשב״ם תצוה כח, לה. וכבר העירו מויק״ר פכ״א, ז (וראה מפרשים שם). וראה תו״ש מלואים לפ׳ תצוה סי״ז."],["14","14","וכמו שמצינו בפ׳ צו (ו, ג) שהכתוב מפרט רק ב׳ בגדים אף שפשוט שצריך ללבוש כל הבגדים. אלא שמחמת טעם מפרט רק ב׳ אלו — ראה רש״י ומפרשיו שם."],["15","15","כח, כט."],["16","16","פקודי לט, כח."],["17","17","ולהעיר שגם ע״ד ההלכה הרי כתב הרמב״ם (הל׳ כלי המקדש פ״ח הי״ד) כל מקום שנאמר בתורה שש או שש משזר צריך שיהי׳ חוט כפול ששה ומקום שנאמר בד אם הי׳ חוט אחד לבדו כשר. אלא שברמב״ם שם מסיים „ומצוה מן המובחר שיהי׳ כפול ששה“. אבל ראה זבחים יח, סע״ב ובפרש״י שם שגם שזורין מעכב. וראה משנה למלך שם ה״ג בארוכה."],["18","18","ועוד: א) זהו היפך דעת רש״י (אבל ש)על הש״ס דכל הבגדים צ״ל שש משזר גם בדיעבד, כנ״ל בהערה שלפנ״ז. ב) ועיקר: כבר מפורש בצו שם „ולבש הכהן מדו בד (הכתונת) ומכנסי בד ילבש על בשרו“, דהנאמר בבגדי כהונה „שש“ היינו „בד“."]]],[1300221105,"דער סיום פון פירוש רש״י „(ככהן הדיוט) וכולן של בוץ“ איז ניט נאר איבעריק, נאר דאס איז א הדגשה אויף להיפך: עס גיט א מקום לטעות אז דער חידוש פון פסוק איז אין די ד׳ בגדים (וואס דער פסוק רעכנט יע אויס), אז „כולן של בוץ“ — היפך הנ״ל אין פירוש רש״י, אז דער חידוש פון פסוק איז (בלויז) אין דעם וואס ער טראגט ניט די אנדערע פיר בגדי זהב.\nה. איז דער ביאור בזה:\nרש״י קומט פארענטפערן א שאלה וואס שטעלט זיך אין פסוק: פארוואס שטייט אט דער פסוק (וועגן לבישת הבגדים) במקום זה? לכאורה האט עס געדארפט שטיין — אדער פאר אלע עבודות וקרבנות פון דעם כהן גדול ביום הכפורים (אין דעם פריערדיקן פסוק), אדער נאכדעם ווי דער פסוק רעכנט אויס די אלע עבודות וואס ער האט געדארפט טאן זייענדיק אנגעטאן אין די בגדים¹⁹.\nפון דעם וואס די תורה זאגט דעם ציווי דאָ גלייך נאך דעם פסוק „בזאת גו׳ בפר בן בקר לחטאת ואיל לעולה“ וואלט מען בפשטות געלערנט, אז די ארבעה בגדים טוט ער אן נאר בא דעם פר בן בקר לחטאת ואיל לעולה, זייענדיק די קרבנות המיוחדים לו ביום הכפורים.\nאבער פון די פסוקים ווייטער איז קלאר, אז: א) עולתו — דער איל לעולה — וערט געטאן אין אנדערע בגדים, „ולבש את בגדיו“, וואס דאס מיינט די „שמונה בגדים שהוא עובד בהן כל ימות השנה“²⁰. ב) אז די אלע עבודות ביז עולתו — די שני שעירי עזים לחטאת פון עדת בני ישראל און די עבודת הקטורת כו׳ וואס וערן אויסגערעכנט\nנאך אונזער פסוק — דארפן אויך געטאן ווערן אין די ארבעה בגדים.\nדעריבער איז רש״י מפרש: „מגיד שאינו משמש לפנים בשמונה בגדים שהוא משמש בהם בחוץ כו׳“. אע״פ אז פשטות הכתוב איז לכאורה משמע אז ס׳איז נוגע צו די ביידע קרבנות וואס וערן געזאגט אין פריערדיקן פסוק, סיי דער חטאת און סיי די עולה — איז דער פירוש ניט אזוי, נאר דער פסוק קומט זאגן אז „אינו משמש לפנים בשמונה בגדים שהוא משמש בהם בחוץ“, און דער איל לעולה איז דאך הקרבתו בחוץ²⁰. ולאידך, די אלע ווייטערדיקע עבודות — די הזיית הדם פון די שני שעירי עזים און די קטורת כו׳ — איז דאך אלץ בפנים (אדער צורך פנים²¹),",[["21","21","בסגנון אחר: כיון שנעשו בהדברים שדמם נכנס לפנים הרי זה כהתחלת עבודת פנים. וראה יומא ס, סע״ב „צורך פנים כפנים דמי“. אלא שע״ד ההלכה אמרינן זה לדעת ר״י (לענין הקדים מעשה לחבירו בבגדי לבן מבחוץ) רק בשחיטה ובחפינה ולא בהגרלה וידוי ושפיכת שיריים וכל מתנות הפרוכת ומזבח הזהב (ראה פרש״י שם ע״א ד״ה בבגדי לבן. וראה רמב״ם הל׳ עבודת יוהכ״פ פ״ה ה״ב). משא״כ ע״ד הפשט (ולעצם ענין לבישת בגדי לבן) אמרינן זה בכל העבודות הנעשות בדברים שנכנסים לפנים. וראה יומא מ, א ואילך. לח״מ לרמב״ם שם ה״א. ואכ״מ. *) וצ״ע בשעיר המשתלח לפרש״י אם הוא נחשב כקרבן אחד עם שעיר השני (שלכן הציווי דלקיחתם והעמדתם כו׳ נאמר על שניהם ביחד, שני השעירים (ראה פסוקים טז, ה. ז־ח). וראה יומא רפ״ו (סב, א ואילך)) והכפרה בדם של שעיר המובא בפנים הוי (גם) כחלק (וכפרה) של (דם) שעיר המשתלח. ולהעיר מיומא מ, ריש ע״ב: יעמוד חי לפני ה׳ לכפר עליו (פרשתנו טז, י״ד) עד מתי כו׳ עד שעת מתן דמו של חבירו כו׳ בכפרת דמים הכתוב מדבר (ולהעיר שהוא דעת ר״י שס״ל (יומא ס, סע״א) שסדרן מעכב בדברים הנעשים בבגדי לבן מבפנים. וראה שם סה, א). אלא שרש״י בפירושו עה״ת פ״י לכפר עליו — שיתודה עליו (כדעת ר״ש שם). ואכ״מ."],["19","19","לאחרי פסוק כב."],["20","20","טז, כד ובפרש״י."]]],[1300221106,"ובמילא וערן זיי געטאן אין די ארבעה בגדים.\nאון דאס גופא איז דער טעם וואס דער ענין הבגדים שטייט דוקא דא נאכן פסוק „בזאת יבוא אהרן אל הקודש גו׳“, ניט פריער פאר אלע קרבנות און ניט שפעטער נאך דעם סיום פון די קרבנות המיוחדים פון יוהכ״פ:\nמיט דעם זאגט דער פסוק, אז די לבישה פון די פיר בגדים איז ניט מצד (עבודת) היום פון יוהכ״פ, נאר מצד „בזאת יבוא אהרן אל הקודש“ — דער חידוש פון (יום הכפורים, דער) שימוש בפנים; דער שימוש בפנים קען ניט זיין מיט שמונה בגדים „שהוא משמש בהם בחוץ“ (וואס דא מיינט ער (בעיקר) ניט דעם שימוש בכל ימות השנה²², נאר „שהוא משמש בהם בחוץ“ ביוהכ״פ עצמו).\nו. עפ״ז ווערט אויך פארענטפערט א תמי׳ פארוואס רש״י באוארענט ניט א קושיא בפשוטו של מקרא:\nוויבאלד אז „אין קטיגור נעשה סניגור“, און דערפאר טאר כה״ג ניט משמש זיין בבגדי זהב — ווי קומט עס אז בחוץ זאל ער יע משמש זיין בבגדי זהב?\nבנוגע צו עבודת כה״ג בכל ימות השנה — אפילו ווען ער טוט אן עבודה וואס ענינה איז כפרה — וואלט מען גע־קענט ענטפערן, אז „אין קטיגור נעשה סניגור“ זאגט מען נאר אין יום הכפורים, וואס כל ענינו פון אט דעם טאג איז (כשמו) — כפורים, און דערפאר דארף די עבודה פון דעם טאג זיין מיט א זהירות מיוחדת, ניט געבן קיין ארט פאר אן ענין פון „קטיגור“.\nאבער בנוגע דער עבודה פון יום הכפורים עצמו — איז ניט פארשטאנ־דיק: די גאנצע עבודת יוהכ״פ, סיי עבודה בפנים און עבודה בחוץ, האט ניט געדארפט זיין בבגדי זהב²³!\nאיז דער ביאור בזה אנגעדייטעט אין דעם וואס דער פסוק „כתונת בד גו׳“ קומט בהמשך צום פסוק „בזאת יבוא אהרן גו׳“:\nדורך מקדים זיין גלייך בהתחלת עבודת יום הכפורים די ווערטער „בזאת יבוא גו׳ בפר גו׳“ לערנט אונז דער פסוק, אז די נקודה פון יום הכפורים איז (ניט די עבודת היום, נאר) „יבוא אהרן אל הקודש“, די כניסה לקודש הקדשים²⁴, און דאס ברענגט די כפרה של יום הכפורים: נאר בכדי²⁵ די כניסה לקודש זאל זיין ווי עס דארף צו זיין — דארף זי זיין „בזאת“, עס פאדערן זיך פארשידענע קרבנות ועבודות (סיי בפנים און סיי בחוץ — ווי דער איל לעולה).\nובמילא איז פארשטאנדיק, אז די באָ־וואַרעניש פון „אין קטיגור נעשה סניגור“ איז בעיקר (אין דעם ארט פון כפרה דיום הכפורים —) אין דער עבודה בפנים²⁶.",[["22","22","כלשון רש״י שם ד״ה ולבש."],["23","23","והרי מפורש (טז, כד) „וכפר בעדו ובעד העם“ ע״ז ש„ויצא ועשה את עולתו ואת עולת העם“. ועל כל היום בכלל (טז, ל) „כי ביום הזה יכפר עליכם גו׳“."],["24","24","להעיר מב׳ הדיעות ביומא ס, ריש ע״ב: ר״י סבר מקום שמתכפרין בו פעם אחת בשנה ור״נ סבר דברים המתכפרין בהן פ״א בשנה."],["25","25","להעיר מיומא ג, א: במה הוכשר אהרן לבוא אל הקודש בפר כו׳. ושם ד, א: והאי בזאת מיבעי לי׳ לגופי׳ כו׳."],["26","26","בקה״ק (שבא בהמשך ל„יבוא אל הקודש“), וכפרש״י יומא ס, א ד״ה מבפנים (וראה פרש״י שם מ, א ד״ה חוקה). ולא כפשטות לשון הרמב״ם (רפ״ה דהל׳ עבודת יום הכפורים) „בפנים בהיכל“. וראה"]]],[1300221107,"ז. וויבאלד אז לויט פירוש רש״י איז דער חידוש פון פסוק „כתונת בד גו׳“ אין דער שלילה, אז בפנים טאר מען ניט משמש זיין מיט די בגדי זהב ווייל אין קטיגור נעשה סניגור — איז ניט גלאטיק:\nווען מ׳לערנט די פסוקים אין פ׳ תצוה, זעט מען דעם גודל הזהירות וואס דארף זיין ביי לבישת הבגדים כדי די עבודה זאל געטאן ווערן אין אן אופן פון „לכבוד ולתפארת“, ביז אז „המשמש מחוסר בגדים במיתה“²⁷ — היינט ווי קומט עס, אז צוליב „אין קטיגור נעשה סניגור“ זאל דער כה״ג ניט זיין (בשלי־מות) „לכבוד ולתפארת“, אפילו ניט טראגן דעם פולען מספר בגדים כרגיל?\n[ויש להוסיף: וואלט מען געלערנט אז ביום הכפורים איז א דין מיוחד בנוגע בגדי כהונה²⁸, אז דער כה״ג דארף טראגן אן אנדער סוג בגדים, וועלכער איז מיוחד ליום הכפורים — איז ניט אזוי קשה. דכשם ווי בכל ימות השנה האט תורה אנגעזאגט א דין פון שמונה בגדים צו א כה״ג, האט אזוי אויך תורה אנגעזאגט א דין פון ד׳ בגדים מיוחדים ליום הכפורים:\nוויבאלד אבער אז לויט רש״י איז ניטא קיין דין וחידוש מיוחד אין די ד׳ בגדים וואס דער כה״ג טראגט, ס׳איז נאר פאראן אן איסור צו טראגן בגדי זהב ביוהכ״פ — ווערט די קשיא: סוף־סוף\nקומט אויס אז דער כה״ג איז דוקא ביוהכ״פ כאילו א מחוסר בגדים?]\nדערפאר מוז רש״י באוארענען, אז דער כה״ג טראגט ארבעה „ככהן הדיוט“: דאס וואס דער כה״ג טראגט בפנים נאר ארבעה בגדים, איז ניט דער פשט אז ער טראגט פיר פון זיינע אכט בגדים²⁹, נאר ער איז דעמאלט משמש ווי א כהן הדיוט³⁰, וואס מספר בגדיו איז (מלכתחילה) ארבעה.\nח. דערמיט וועט מען אויך פאר־שטיין דעם סיום לשון רש״י „וכולן של בוץ“:\nכוונת רש״י איז ניט נאר צו מדגיש זיין אז די ד׳ בגדים זיינען ניט קיין ענין של „קטיגור“ — וויבאלד אז „כולן של בוץ“; נאר דאס איז אויך א תוספת ראי׳ אז דער שימוש בפנים ביום הכפורים איז „ככהן הדיוט“³¹:\nוועגן דעם אבנט של אהרן שטייט אין פ׳ פקודי³² אז ער איז געמאכט געווארן פון „שש משזר ותכלת וארגמן ותולעת שני מעשה רוקם“\n(אין פ׳ תצוה³³ וואו עס שטייט דער ציווי אויף עשיית הבגדים, שטייט נאר אז דער אבנט דארף זיין „מעשה רוקם“, ער זאגט אבער ניט דערביי פון וועלכן מין (אדער מינים) ער ווערט געמאכט: משא״כ ביי עשיית הבגדים אין פקודי",[["","","בארוכה לח״מ שם (אבל ראה בדבריו שם בסופו דגריס ברמב״ם „לפנים מן ההיכל“. וכ״ה בקרית ספר (על הרמב״ם) שם)."],["27","27","פרש״י שם כח, מג."],["28","28","ראה לקמן בפנים (סעיף ט) שכן משמע דעת הרמב״ם. ולהעיר מירושלמי יומא פ״ז סה״ב (ויק״ר פכ״א, יא): ולמה בבגדי לבן כו׳ כשירות של מעלן כך שירות של מטן כו׳."],["29","29","להעיר מלשון רש״י „שאינו משמש לפנים בשמונה בגדים כו׳ שיש בהם זהב“ (אף שרק בחלק מהם יש זהב), ולא כלשון הגמ׳ ר״ה שם, ירושלמי וכן בויק״ר (הנ״ל הערה 4): מפני מה אין כה״ג נכנס בבגדי זהב כו׳."],["30","30","להעיר מהגירסא בא׳ מכת״י רש״י (שתח״י): בד׳ של כהן הדיוט."],["31","31","להעיר גם מטורי אבן ר״ה שם ד״ה מ״מ."],["32","32","לט, כט."],["33","33","כח, לט."]]],[1300221108,"שטייט אז אבנטו של אהרן כה״ג איז געווען פון די מינים הנ״ל).\nקומט אויס, אז אבנטו של אהרן איז ניט נאר פון „בד“ — היינט ווי זאגט דער פסוק „ובאבנט בד יחגור“? איז דערפון געדרונגען, אז די בגדים זיינען ניט די בגדי כהן גדול, נאר דאס זיינען די „ארבעה ככהן הדיוט“³⁴,\nאון רש״י נעמט אן (בפשוטו של מקרא), אז דאס וואס דער פסוק טיילט אויס אבנטו של אהרן (אין פ׳ פקודי) — און דערמאנט ניט די אבנטים פון בניו (כאטש דארטן גופא³⁵ דערמאנט דער פסוק די אנדערע ג׳ בגדים פון בני אהרן) — איז ווייל דער פסוק רעדט דארט דוקא וועגן אבנטו של אהרן, משא״כ די אבנטים פון בני אהרן זיינען געמאכט געווארן אנדערש (בלויז פון בד)³⁶.\nט. וי״ל אז דאס איז — פון די ענינים מופלאים ע״ד ההלכה שבפירוש רש״י: רש״י איז מחולק מיטן רמב״ם אין דעם גדר פון די בגדי כה״ג ביוהכ״פ:\nדער רמב״ם³⁷ זאגט „בגדי כהונה שלשה מינים, בגדי כהן הדיוט ובגדי זהב ובגדי לבן“ — לשיטת הרמב״ם זיינען די בגדי לבן של יוהכ״פ אן אנדער מין בגדים; ניט אז ס׳איז אן איסור צו טראגן בגדי זהב בפנים ובמילא בלייבן ביי אים איבער (נאר) פיר פון זיינע אכט בגדים, נאר עס איז א דריטער מין בגדים³⁸.\n— רש״י איז מדייק אז בפנים דארף ער משמש זיין אין „ארבעה ככהן הדיוט“ (כנ״ל בארוכה).\nעד״ז זעט מען דעם חילוק פון רש״י מיטן רמב״ם אין דעם חיוב פון בגדי לבן אין נאך אן ענין:\nדער רמב״ם³⁹ זאגט אז „עבודות המיוחדות ליום זה בבגדי לבן“. בגדי לבן איז א דין אין עבודות היום. וואס דערין איז פאראן א שוועריקייט — דער איל לעולה און איל העם זיינען עבודות המיוחדות ליום הכפורים⁴⁰, און אעפ״כ זיינען זיי ניט בבגדי לבן.\nרש״י פארבינדט אבער דעם חיוב פון בגדי לבן מיט „פנים“, ס׳איז ניט תלוי אין עבודות היום נאר אין דעם ארט פון דער עבודה — אלץ וואס וערט געטאן אין פנים (אדער עכ״פ צוליב עבודת פנים⁴¹) דארף געטאן ווערן בבגדי לבן. וואַרום, ווי גערעדט פריער, איז לויט רש״י (בפשוטו של מקרא), דער עיקר כפרה פון יום הכפורים איז מצד דער כניסה לפני ולפנים, און די עבודות היום זיינען בלויז א תנאי ומכשיר צו זיין כניסה.\nיו״ד. ואולי יש לומר, אז די צוויי ענינים הנ״ל — (א) צי בגדי לבן איז אן",[["34","34","אבל ראה משכיל לדוד כאן."],["35","35","לט, כז־כח."],["36","36","ובגמ׳ פלוגתא באבנטו של כהן הדיוט — ראה יומא ו, א (ובפרש״י ותוס׳ שם). יב, סע״א ואילך. ולהלכה פסק הרמב״ם (רפ״ח מהל׳ כלי המקדש) דרקום בצמר."],["37","37","רפ״ח מהל׳ כלי המקדש."],["38","38","להעיר גם מהשגת הרמב״ן על ספהמ״צ להרמב״ם מ״ע לג שמקשה לדעת הרמב״ם שם ד״ה „ראוי שתמנה מצות בגדי לבן ביום הכפורים מצוה אחרת (מצוה בפ״ע)“. וראה מפרשי סהמ״צ שם. ביאור הרי״פ פערלא לסהמ״צ לרס״ג מנין הפרשיות פרשה ס״ב."],["39","39","רפ״ב מהל׳ עבודת יוהכ״פ."],["40","40","ראה רמב״ם שם פ״ה ה״ג ובכס״מ שם. ובקרית ספר שם: איל ושעיר המוספין שעשאן קודם עבודת היום לא עשה כלום דאיל העם כתיב בהדי עבודת היום כדכתיב את עולתו ואת עולת העם. וראה גם פרש״י יומא ס, סע״א ד״ה בבגדי זהב. וראה לשון הרמב״ם בהכותרת להלכות עבודת יוהכ״פ. ובמנין המצות וסהמ״צ מ״ע מט."],["41","41","ראה לעיל הערה 21."]]],[1300221109,"ענין שלילי אדער אן ענין חיובי, (ב) צי בגדי לבן איז פארבונדן מיט עבודות היום אדער מיט כניסה לפנים — זיינען תלוי זה בזה:\nאויב מ׳זאל לערנען אז ס׳איז א דין מיוחד וחיובי פון בגדי לבן, איז מסתבר צו זאגן אז דאס איז א דין אין עבודת היום. וואַרום כשם ווי בגדי כהונה בכלל זיינען פארבונדן מיט עבודת הכהנים⁴², אזוי איז דער דין מיוחד פון בגדי לבן א פרט אין דער עבודה המיוחדת פון דעם טאג.\nאויב אבער דער ענין פון בגדי לבן איז אן ענין שלילי — עס טארן ניט זיין בגדי זהב — איז מסתבר צו זאגן, אז דער איסור איז פארבונדן (ניט מיט דער עבודה גופא, נאר) מיט דעם מקום פון דער עבודה וואס „דערלאזט“ ניט אן ענין של זהב.\nיא. פון דעם פרש״י האט מען ארויס א הוראה אין עבודת ה׳:\nבשעת א איד וויל פועל זיין „לפני ה׳ תטהרו“⁴³ בנוגע זיך און בנוגע א צווייטן אידן און ברענגען אלעמען „לפני ה׳“, נעענטער צום אויבערשטן לתורתו ולמצוותיו, דארף ער צום אלעם ערשטן וויסן, אז דערצו פאדערט זיך אז ער זאל אריינגיין „לפנים“. ער דארף זיך דער־גרונטעווען, „אריינגיין“ אין זיין פנימיות הנפש און בכח זה דוקא קען ער אויפ־טאן א כפרה וטהרה אויף זיך און אויף א צווייטן.\nאון דער וועג צו אריינגיין לפנים איז — דורך אויסטאן זיין „לכבוד ולתפארת“ די בגדי זהב. כל זמן ער פילט זיין „לכבוד ולתפארת“, קען ער ניט אריינגיין אין „פנים“, פנימיות הכוונה.\nדוקא בשעת ער פילט זיך ווי א כהן הדיוט — ניט בבגדי זהב נאר בבגדי לבן, „כולן של בוץ“ — ביי אים איז מאיר דער ענין הפשיטות⁴⁴\nדאס דוקא מאכט אים ראוי צו אריינ־גיין לפנים, און דורך דעם פועלן א כפרה וטהרה און ניט נאר אויף זיך, נאר אויך אויף א צווייטן, ביז אז\nוכפר בעדו ובעד ביתו ובעד כל קהל ישראל⁴⁵.\n(משיחת ש״פ אחרי תשל״ו)",[["42","42","ראה רמב״ם הלכות כלי המקדש פ״י ה״ד. סהמ״צ להרמב״ם שם. ובמפרשים שם. ולהעיר מהשקו״ט אם בגדי כהונה הם רק בשביל כהן העובד או שהעבודה בעצמותה זקוקה להבגדים (ראה אתוון דאורייתא כלל יט. בית האוצר ח״ב כלל יו״ד. וש״נ). ואכ״מ."],["43","43","פרשתנו טז, ל."],["44","44","ראה לקו״ת פרשתנו כח, סע״ב ואילך. ובארוכה עטרת ראש שער יוהכ״פ פ״ה ואילך (ל, א)."],["45","45","פרשתנו טז, יז."]]],[1300221110,"<h3>אחרי ב</h3>\nא. ביים סוף פון דער סדרה איז די תורה מסיים פרשת עריות מיטן אָנזאָג:¹ „ושמרתם את משמרתי לבלתי עשות מחוקות התועבות גו׳ ולא תטמאו בהם אני ה׳ אלקיכם”.\nשטעלט זיך רש״י אויף די ווערטער „ולא תטמאו בהם אני ה׳ אלקיכם” און איז מפרש: „הא אם תטמאו איני אלקי־כם ואתם נפסלים מאחרי ומה הנאה יש לי בכם ואתם מתחייבים כלי׳, לכך נאמר אני ה׳ אלקיכם”.\nדער טעם פאַרוואָס רש״י איז ניט מפרש די ווערטער „אני ה׳ אלקיכם” ווי ער איז מפרש בפ׳ וארא² „אני ה׳ נאמן ליפרע כו׳ אני ה׳ נאמן ליתן שכר”, ובפרט אַז ער זאָגט דאָרט אַז אַזוי איז „אני ה׳” „נדרש בכמה מקומות” — איז (ווי מפרשים³ זיינען מסביר): דער ענין „אני ה׳ — נאמן לשלם שכר” (און „ליפרע”) איז שוין געשטאַנען פריער⁴ אין דער פרשה, דעריבער האָט ניט קיין אָרט צו איבער׳חזר׳ן דעם ענין נאָכאַמאָל. מוז מען זאָגן, אַז „אני ה׳ אלקי־כם” מיינט אַן ענין חדש⁵.\nמען דאַרף אָבער פאַרשטיין דעם פירוש פון רש״י:\nפון די ווערטער „ולא תטמאו בהם אני ה׳ אלקיכם” קען מען לכאורה נאָר מדייק זיין (מכלל הן אתה שומע לאו⁶ —) „הא אם תטמאו איני אלקי־כם”. פון וואַנעט נעמט רש״י די אַלע פרטים וואָס ער זאָגט דערנאָך⁷: „ואתם נפסלים מאחרי ומה הנאה יש לי בכם ואתם מתחייבים כלי׳”?\nאמת טאַקע דער פירוש שטייט אין תורת כהנים⁸ — אָבער, ווי גערעדט כמה פעמים, איז ניט ענינו פון רש״י בפירושו על התורה, צו מעתיק זיין דרשות חז״ל (— ובלשונן⁹). ובפרט אַז רש״י זאָגט דאָ ניט „איתא בתו״כ” (וכיו״ב),\nוואָס דערפון איז מוכח אַז רש״י נעמט אָן דעם פירוש אלס פשוטו של מקרא. ד.ה. אַז די ווערטער „ולא תטמאו בהם",[["1","1","יח, ל."],["2","2","בתחלתה (ו, ב)."],["3","3","גו״א כאן. בש״ך עה״ת כאן כתב, דהוקשה לרש״י „שכל מקום שנאמר אני ה׳ . . אצל עונש (פירושו) אני נאמן ליפרע וכאן הוא אמור אצל עונש . . והעונש כבר אמור שאמר . . ונכרתו, לזה ארז״ל שזה העונש האמור לעיל . . מתחייבים כלי׳ שהיא הכרת”. וצ״ע לפענ״ד, שהרי לכאורה החידוש ב„אני ה׳ — נאמן ליפרע” הוא (לא שחייבים עונש, כ״א) שהקב״ה „נאמן ליפרע” (וראה רש״י וארא ו, ג. שם, ו). וא״כ גם אם „העונש כבר אמור” יש להוסיף „אני ה׳” (שהקב״ה נאמן ליפרע עונש זה). וראה ג״כ פרש״י פרשתנו (יח, ה): וחי בהם, לעוה״ב . . אני ה׳, נאמן לשלם שכר."],["4","4","יח, ו (לשלם שכר). פי׳ הב׳ ברש״י שם, ב (וראה בארוכה לקמן סעיף ב) — ב׳ הענינים. פרש״י שם, ה (לפי׳ הא׳ בד״ה ושמרתם. משא״כ לפי׳ הב׳ לכאורה לא קאי על עריות (ראה רש״י שם, ד). ואכ״מ)."],["5","5","ראה גם ס׳ זכרון ושפ״ח כאן."],["6","6","פרש״י יתרו כ, יב. ובכ״מ."],["7","7","ראה גם חי׳ ופי׳ מהרי״ק (לבעהמ״ח שו״ת מהרי״ק) על פרש״י (ירושלים, תשל״א): יש לעיין מה זה שהאריך רש״י כו׳. — אבל מבאר רק לשון רש״י (וקשר ג׳ הענינים), אבל אינו מבאר מהו ההכרח בפשש״מ לפרטי הלשונות שבפרש״י."],["8","8","עה״פ."],["9","9","ובפרט שיש שינויים בלשון רש״י לגבי לשון התו״כ, ע״ש. ולהעיר ממש״כ בס׳ זכרון על לשון רש״י „מדרש רבותינו הוא בספרא אות באות”(!)."]]],[1300221111,"אני ה׳ אלקיכם” ברענגען אַרויס די אַלע דריי פרטים: אתם נפסלים מאחרי, ומה הנאה יש לי בכם ואתם מתחייבים כלי׳.\nאיז תמוה: פון וואַנעט איז דער הכרח אין פשוטו של מקרא אויף די פרטים?\n[מען קען ניט ענטפערן אַז רש״י מוז (אָדער עכ״פ — וויל) מפרט זיין פאַרן בן חמש למקרא דעם באַדייט פון „איני אלקיכם” אין אַלגעמיין — ווייל¹⁰ דעם תוכן פון „איני אלקיכם” געפינט מען שוין פריער אין פרש״י: אויפן פסוק (אין פ׳ לך¹¹) „ונתתי לך גו׳ ארץ כנען גו׳ והייתי להם לאלקים” איז רש״י מפרש „אבל הדר בחו״ל כמי שאין לו אלוקה” — און רש״י איז דערביי ניט מוסיף קיין ביאור ועל אכו״כ — ניט קיין פרטים].\nאויך איז ניט מובן די הוספה וסיום פון רש״י „לכך נאמר אני ה׳ אלקיכם” — וואָס איז דאָ רש״י מוסיף¹²? ובלשון פון אַ תירוץ לקושיא „לכך נאמר”?\nנאָכמער: פון התחלת פרש״י — וואָס ער שטעלט זיך אויף די ווערטער „ולא תטמאו בהם אני ה׳ אלקיכם” — איז משמע, אַז די שוועריקייט אין פסוק איז אויך אין די ווערטער „ולא תטמאו בהם”, ובסיום איז רש״י מעתיק בלויז די ווערטער „אני ה׳ אלקיכם” און ניט „ולא תטמאו בהם”?\nב. וועט מען דאָס פאַרשטיין בהקדם הביאור אין פירוש רש״י בתחלת פרשת עריות¹³ — „וידבר גו׳ דבר אל בנ״י גו׳ אני ה׳ אלקיכם” — וואו רש״י¹⁴ איז מפרש (בפירושו הב׳) „רבי אומר גלוי וידוע לפניו שסופן לנתק בעריות . . לפיכך בא עליהם בגזירה אני ה׳ אלקי־כם, דעו מי גוזר עליכם, דיין להפרע ונאמן לשלם שכר”.\nאיז לכאורה ניט מובן: „דעו מי גוזר עליכם” און „דיין להפרע ונאמן לשלם שכר” זיינען לכאורה צוויי באַזונדערע פירושים אין „אני ה׳ (אלקיכם)”. וכדמוכח דערפון וואָס בכמה ערטער¹⁵ וואו רש״י איז מפרש (אויף „אני ה׳”) „נאמן לשלם שכר” אָדער „נאמן להפרע” (וכיו״ב) זאָגט ער ניט די הקדמה „דעו מי גוזר עליכם”; און אַזוי לאידך, בכמה מקומות איז רש״י מפרש „אני ה׳” — „גזרתי עליכם אי אתם רשאים להפטר”¹⁶, „דע מי גזר על הדבר ואל יקל בעיניך”¹⁷, און איז דערביי ניט מוסיף „נאמן לשלם שכר” (וכיו״ב).\nפון וואַנעט נעמט רש״י, אַז „אני ה׳ אלקיכם” בנדו״ד מיינט ביידע ענינים¹⁸",[["10","10","נוסף לזה די לומר „ואתם נפסלים מאחרי”, שזהו הפירוש ד„איני אלקיכם”, משא״כ „ומה הנאה וכו׳” שהו״ע נוסף כו׳ (ראה קרבן אהרן לתו״כ כאן. ס׳ זכרון כאן)."],["11","11","יז, ח. וראה גם פרש״י אמור כה, לח."],["12","12","במשכיל לדוד כאן מפרש (וראה גם פירושו לפרש״י לעיל יח, ו): דהכא תרתי קאמר קרא אם לא תטמאו אני ה׳ במדה״ר נאמן לשלם שכרם ואם תטמאו הריני אלקיכם דיין ליפרע . . והיינו דהדר רש״י ומסיים לכך נאמר אני ה׳ אלקיכם” (וראה גם רבינו הלל וקרבן אהרן לתו״כ כאן). וצע״ג, דאין כל רמז בפרש״י כאן להענין דנאמן לשלם שכר (ודיין ליפרע)!"],["13","13","יח, א־ב."],["14","14","שם, ב. — ביאור פרש״י זה ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121083\" data-slug=\"likkutei-sichot\" data-id=\"1300121083\">לקו״ש חי״ב ע׳ 83</a> ואילך."],["15","15","ראה לדוגמא, פרש״י: ר״פ וארא. פרשתנו יח, ה. שם, ו. קדושים יט, י. שם, טז. שם, כה. שם, לו. אמור כב, לג. כג, כב. ס״פ בהר. שלח טו, מא."],["16","16","אחרי יח, ד."],["17","17","אמור כב, ל. וראה גם פרש״י קדושים יט, לא."],["18","18","ובפרט שבתו״כ עה״פ לא הובא בדברי רבי הסיום „דיין להפרע ונאמן לשלם שכר” [ורק לפנ״ז (פרשה ט, א) הובאה דרשה בפ״ע „אני דיין להיפרע ונאמן לשלם שכר”]. ולכאורה אין הכרח (ודוחק הוא) לומר שהיתה לפני רש״י גירסא אחרת בתו״כ שלא ראינוה וכו׳ — כי אפ״ל שזוהי הוספה (וביאור) רש״י — כרגיל בפרש״י — על דברי רבי."]]],[1300221112,"— „דעו מי גוזר עליכם” און „דיין להפרע ונאמן לשלם שכר”¹⁹?\nאיז דער ביאור בזה: ביי פרשת עריות געפינט מען אַ דבר מיוחד, אַז איידער די תורה הויבט אָן צו מפרש זיין די פרטי האיסורים, שטייט אַ הקדמה כללית, און וועלכע באַשטייט פון כמה וכמה ענינים²⁰: „כמעשה ארץ מצרים גו׳ ארץ כנען גו׳ לא תעשו גו׳ את משפטי תעשו גו׳ ושמרתם את חוקותי גו׳”. און די פתיחה פון דער הקדמה כללית איז — „וידבר ה׳ גו׳ דבר אל בני ישראל גו׳ אני ה׳ אלקיכם”.\nדער טעם פאַרוואָס תורה גיט אַזאַ הקדמה כללית וארוכה ומרובה צו פרשת עריות איז מובן בפשטות: עריות זיינען דאָך אַ זאַך וואָס „נפשו של אדם מתאוה להם”²¹, ועד כדי כך, אַז אפילו נאָך די אַלע אזהרות איז (ווי רש״י ברענגט אַראָפּ, כנ״ל) „סופן לנתק בעריות”. דעריבער פאַדערן זיך דברי זירוז און מערערע אזהרות צו באַוואָ־רענען אַז מען זאָל זיין אָפּגעהיט אין דעם, ביישטיין דעם נסיון.\nוויבאַלד אַז דער „אני ה׳ אלקיכם” שטייט אין דער פתיחה פון דער הקדמה כללית, איז דעריבער מסתבר, אַז דאָס איז אַן ענין (וזירוז) כללי. און דאָס איז דער טעם וואָס דער ערשטער פירוש פון רש״י אויף „אני ה׳ אלקיכם” (— אין דער פתיחה) איז: „קבלתם עליכם מלכו־תי מעתה קבלו גזרותי”, אַן ענין הכי כללי — קבלת עול מצות (גזירות²²).\nאון כדי צו מבאר זיין, ווי אויך לויטן צווייטן פירוש [אַז „אני ה״א” איז אַן אזהרה (ניט (נאָר) אויף קבלת גזירות בכלל, נאָר) בעיקר אויף ענין העריות] איז „אני ה״א” אַן ענין כללי (וואָס דער־פאַר איז דאָס בפתיחת הפרשה), איז רש״י מפרש, אַז דער לשון „אני ה׳ אלקיכם” וואָס שטייט דאָ איז כולל כמה פרטים — יעדער וואָרט איז מרמז אויף אַ באַזונדערע אזהרה²³: „אני — דעו מי גוזר עליכם”; „ה׳ — נאמן לשלם שכר”; „אלקיכם — דיין להפרע”:\nוואָס די דריי ענינים זיינען כולל אַלע אופנים (כלליים²⁴) דורך וועלכע מען קען באַווירקן אַ מענשען באַהערשן די תאוות וועגן וועלכע עס רעדט זיך אין דער פרשה (כאָטש זיי זיינען שטאַרקע תאוות, כנ״ל).\nג. וועלנדיק אָפּהאַלטן אַ אידן פון אַ תאוה גדולה ביותר, דאַרף מען אים צום אַלעם ערשטן זאָגן — „דעו מי גוזר עליכם”: ער דאַרף וויסן און געדענקען, אַז דאָס איז אַ גזירה פון דעם אוי־בערשטן, דעם בורא העולם ומנהיגו, און דעריבער איז אוממעגליך אַז דורך נאָכ־געבן די תאוה היפך רצון הבורא, זאָל אים זיין גוט.",[["19","19","אבל מה שכתב ב׳ ענינים — דיין להפרע ונאמן לשלם שכר — מובן, כמ״ש במפרשי רש״י שם. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121089\" data-slug=\"likkutei-sichot\" data-id=\"1300121089\">לקו״ש שם ע׳ 89</a> הערה 32."],["20","20","יח, ג־ה."],["21","21","פרש״י ראה יב, כה (ומובן הוא בפשטות, וכדמוכח גם מסגנון ל׳ רש״י שם). ולהעיר גם מפרש״י בהעלותך יא, י."],["22","22","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121086\" data-slug=\"likkutei-sichot\" data-id=\"1300121086\">לקו״ש שם ע׳ 86</a> ואילך."],["23","23","ראה הנסמן בהערה 19."],["24","24","להעיר שג׳ ענינים אלו הם ג׳ האופנים הכלליים שישנם בעבודת ה׳: דעו מי גוזר עליכם — קבלת עול מלכות שמים; נאמן לשלם שכר — ע״מ לקבל פרס (קו הימין); ודיין להפרע — יראת העונש (קו השמאל). אבל מהסדר בפרש״י („דיין להפרע” לפני „נאמן לשלם שכר” (ולהעיר מהסדר סור מרע ועשה טוב) — אף שבכתוב בא „הוי׳” לפני „אלקיכם”) — מוכח, שכוונת רש״י היא לרמז על סדר האזהרה (לכל אדם פרטי). וראה לקמן סעיף ג."]]],[1300221113,"קען זיך אָבער איינער פרוואוון איינ־רעדן: אים אַרט ניט וואָס „אחריתה מרה כלענה”²⁵, אַבי ער וועט דערווייל הנאה האָבן פון דער תאוה. דערויף קומט די צווייטע וואָרענונג — „דיין להפרע”: פאַרן עובר זיין אויפן רצון ה׳ באַקומט מען דערנאָך ניט סתם אַן עונש, נאָר אין אַן אופן פון פרעון (דיין להפרע): דער אויבערשטער גיט אַן עונש וועלכער איז אַ פרעון, ער „קערט אום”, ס׳איז בטל די גאַנצע הנאה וואָס ער האָט געהאַט פון דער עבירה — אַזוי, אַז עס בלייבט באַ אים גאָרניט, נאָר צער וכו׳.\nלפ״ז ווערט אַ שאלה — למה עשה ה׳ ככה? פאַרוואָס האָט אים דער אוי־בערשטער באַשאַפן מיט אַזאַ שטאַר־קער תאוה, וועלכע ער קען ניט ביי־שטיין? זאָגט מען אים (אַ דריטן ענין) — „ונאמן לשלם שכר”: דער אוי־בערשטער וויל געבן אַ אידן שכר, און דערפאַר שטעלט מען אים פאַר אַ נסיון, כדי ער זאָל ביישטיין דעם נסיון און דערפאַר באַקומען שכר: און וואָס שווע־רער ס׳איז די עבודה צו ביישטיין דעם נסיון — אַלץ מער שכר וועט ער באַ־קומען.\nד. בשעת מען קומט צו דעם סיום הסדרה, זעט מען אַז די תורה חזר׳ט איבער כמה אזהרות אויף עריות — „אל תטמאו בכל אלה גו׳ ושמרתם אתם את חוקותי גו׳”²⁶: און אויך — אַז דורך עובר זיין אויף עריות קומען פאַר־שידענע עונשים — „ולא תקיא הארץ אתכם גו׳ ונכרתו הנפשות גו׳”²⁷. און ערשט דערנאָך קומט דער לעצטער פסוק: „ושמרתם את משמרתי לבלתי\nעשות מחוקות התועבות גו׳ ולא תטמאו בהם אני ה׳ אלקיכם”.\nאיז לולא דעם סיום „אני ה׳ אלקיכם” וואָלט מען געלערנט, אַז דאָס וואָס די תורה חזר׳ט איבער אזהרות וכו׳ „ושמרתם את משמרתי גו׳ ולא תטמאו בהם” איז [ע״ד ווי רש״י האָט מפרש גע־ווען פריער²⁸ ביים איסור פון אכילת שרצים וכו׳, אַז דאָס איז] „לעבור עליהם בלאוין הרבה” — דער זעלבער לאו מערערע מאָל.\nוויבאַלד אָבער אַז דערביי ווערט איבערגעחזרט אויך „אני ה׳ אלקיכם” — וואָס אין דעם איז ניט שייכות זאָגן „הרבה” — איז דאָס מכריח צו זאָגן, אַז דער גאַנצער המשך הסיום איז (ניט „לעבור כו׳ הרבה”, נאָר) אַ חתימה מעין הפתיחה²⁹: כשם ווי די פרשת עריות הויבט זיך אָן מיט אַ הקדמה וזירוז כללי — „אני ה״א, כמעשה ארץ מצרים גו׳ את משפטי תעשו גו׳ ושמרתם את חוקותי גו׳”, עד״ז איז דער סיום הפרשה מיט אַן ענלעכן זירוז כללי: „ושמרתם גו׳ אני ה״א”.\nאין וואָס באַשטייט אָבער דער אויפטו און יתרון פון דעם זירוז בסיום הפרשה לגבי דעם זירוז שבתחילתה? אויף דעם זאָגט רש״י: „ולא תטמאו בהם אני ה׳ אלקיכם — הא אם תטמאו איני אלקיכם”: דער חידוש דאָ באַשטייט אין דער שלילה — „אם תטמאו איני אלקיכם”,\nדער חידוש ביים סיום, לגבי דעם פריערדיקן זירוז (און דערפאַר קומט עס",[["25","25","לשון הכתוב — משלי ה, ד."],["26","26","יח, כד־כו."],["27","27","שם כח־כט."],["28","28","שמיני יא, מד."],["29","29","להעיר גם מתו״כ (יח, א — פי״ג, ג) „חמורות העריות שהוא פותח בהם ביו״ד ה״א וחותם בהם ביו״ד ה״א” (אלא ששם הכוונה ב„פותח בהם” היא להפסוק (יח, ו) „איש איש גו׳ אני ה׳”)."]]],[1300221114,"לבסוף, בסיום הפרשה): דער „אני ה׳ אלקיכם” שבתחילת הפרשה איז ענינים פון „חיוב” — דער אויבערשטער איז גוזר אויף אידן גזירות, און אין ביידע קווים: „דיין להפרע ונאמן לשלם שכר”.\nווען עס איז דאָ איינער, וואָס די אַלע דריי פרטים הנ״ל פועל׳ן ניט אויף אים — ער ווייס טאַקע ווער איז גוזר און ער וועט „צאָלן” דערפאַר („דיין להפרע”) און ער וועט פאַרלירן דעם שכר, אָבער די תאוה איז באַ אים אַזוי שטאַרק, אַז ער קען ניט ביישטיין דעם נסיון —\nאיז תורה מוסיף, בסיום הפרשה, נאָך אַן אופן ווי צו פועל׳ן (אויך) אויף אים — דורך מודיע זיין אַז „אם תטמאו איני אלקיכם”: דאָס רירט אָן דעם פאַרבונד פון אַ אידן מיטן אויבערשטן. און ווי מען זעט במוחש, אַז ווען אַ איד הערט אַזעלכע רייד („איני אלקיכם”) ווערט ער אויפגעדערט וכו׳ און ער קען עס ניט פאַרטראָגן (ווי דער באַוואוסטער וואָרט³⁰: אַ איד ניט ער וויל און ניט ער קען זיין אָפּגעריסן פון ג־טלעכקייט).\nו. ע״פ הנ״ל וועט מען אויך פאַר־שטיין פאַרוואָס רש״י איז מפרט און גיט צו די דריי פרטים — „ואתם נפסלים מאחרי ומה הנאה יש לי בכם ואתם מתחייבים כלי׳”:\nוויבאַלד דער תוכן (אזהרה וזירוז) פון „אני ה׳ אלקיכם” שבסיום הסדרה איז בדוגמא צום ענין פון „אני ה׳ אלקיכם” שבתחילת פרשת עריות — און דער חילוק איז נאָר וואָס פריער איז אין „חיוב” און צום סוף — אין „שלילה” — איז מובן, אַז כשם ווי „אני ה׳ אלקיכם”\nשבתחילת הפ׳ איז כולל דריי פרטים — יעדער וואָרט אַ באַזונדער פרט (כנ״ל בארוכה), איז עד״ז אויך ביי „אני ה׳ אלקיכם” שבסיום הסדרה, אַז זיי זיינען כולל די זעלבע דריי פרטים, נאָר אין דעם אופן פון „שלילה”:\nדער „אני” בתחילת הפרשה מיינט — „דעו מי גוזר עליכם”, וואָס דאָס ווייזט, כנ״ל, ווי דער אויבערשטער „פאַר־נעמט” זיך מיט אידן אַלס זיין פאָלק וועלכן ער זאָגט אָן גזירות — במקביל לזה קומט בסוף הפרשה דער צד השלילי פון זעלבן ענין: „אתם נפסלים מאחרי” (וי״ל אויך מלשון „פסל לך”³¹ — אויסהאַקן און אָפּטיילן):\nבמקביל צו דעם ענין פון „ה׳ — נאמן לשלם שכר” בתחילת הפרשה (וואָס דער תשלום שכר ווייזט, אַז באַ דעם אויבערשטן איז נחת רוח לפניו³² — ער האָט הנאה פון עבודת בני ישראל) — קומט דער ענין פון „ומה הנאה יש לי בכם” (שלילת ההנאה):\nאון במקביל צום ענין „אלקיכם — דיין להפרע” (בתחלת הפ׳), וואָס ווי־באַלד דער אויבערשטער פאַרנעמט זיך מיט אַ אידן אים צו מעניש זיין, ווייזט עס אויף דער שייכות קרובה וחביבות ביניהם³³ (ובפרט ע״פ הידוע³⁴ אַז די עונשים שבתורה זיינען לטובת האדם) — ווערט ביים סיום געוואָרנט „אתם",[["30","30","היום יום כה תמוז. ד״ה באתי לגני ה׳שי״ת פ״ג־ד. ובכ״מ."],["31","31","תשא לד, א. וראה גם באר מים חיים (לאחי המהר״ל). לפרש״י כאן."],["32","32","פרש״י ויקרא א, ט. ועוד."],["33","33","ובלשון הכתוב: רק אתכם ידעתי גו׳ על כן אפקוד עליכם את כל עונותיכם (עמוס ג, ב). — נת׳ ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450592\" data-slug=\"or-hatorah-hb\" data-id=\"8316450592\">אוה״ת</a> (להצ״צ) איכה (נ״ד ח״ב) ע׳ א׳סב. א׳סז."],["34","34","ראה בארוכה לעיל ע׳ 71 ואילך, וש״נ (וכ״ה ע״ד הפשט, כנסמן בהערה 31 שם)."]]],[1300221115,"מתחייבים כלי׳”: מען פאַרלירט די שייכות מיטן אויבערשטן, וואָס הוא חייך³⁵, ובמילא אַן ענין פון כלי׳ ר״ל³⁶.\nוע״פ הנ״ל איז אויך מובן וואָס רש״י איז מסיים „לכך נאמר אני ה׳ אלקיכם” — דערמיט וויל רש״י קלאָר מאַכן, אַז דאָס וואָס ער זאָגט די דריי פרטים, איז ווייל זיי זיינען פאַרבונדן (כנ״ל, בדרך שלילה) מיט די דריי לשונות אין פסוק: אני ה׳ אלקיכם.\nז. ע״ד החסידות יש לבאר די שייכות פון די דריי פרטים הנ״ל צו די דריי לשונות „אני ה׳ אלקיכם” (באופן אחר מהנ״ל):\n„אני” — עצמותו ומהותו ית׳³⁷ — איז העכער פון התהוות העולמות. כמאמר הידוע³⁸: „לא זה הוא עיקר האלקות מה שהעולמות מתהווים ממנו”. אעפ״כ ווערט אויך „אני” נמשך אין וועלט, וואָס דאָס איז דורך דער עבודה פון תורה ומצוות\n[וכמאמר³⁹ נתאוה הקב״ה להיות לו ית׳ דירה בתחתונים, אַז דורך תומ״צ מאַכן אידן די וועלט פאַר אַ דירה לעצמותו ומהותו ית׳ (פּונקט ווי אין דירת האדם, „דעצמות האדם דר בה־דירה”⁴⁰)].\n„הוי׳” איז מלשון מהווה⁴¹:\nאון „אלקיכם” — כחכם וחיותכם⁴² — ביז — כח הפועל בנפעל, די מדריגה פון אלקות וואָס איז זיך מתלבש אין נברא.\nאון נאָך דעם זאָגט רש״י „הא אם תטמאו איני אלקיכם”, און דאָס דריקט זיך אויס אין אַלע דריי ענינים:\nדער ערשטער ענין (בהמשך צו „איני אלקיכם”⁴³) איז, וואָס „אתם נפסלים מאחרי”: „אחרי” — בחי׳ אחוריים — איז שם אלקים, און אידן ווערן „נפסל” (אָפּגעשניטן) פון דעם כח הפועל בנפעל, שם אלקים.\nדערנאָך — „ומה הנאה יש לי בכם”: די עבודה פון אידן איז גורם תענוג למעלה — „נתאוה הקב״ה להיות לו ית׳ דירה בתחתונים”, וואָס דאָס איז דער תענוג העצמות („אני”) פון עבודת תומ״צ; איז „אם תטמאו — מה הנאה יש לי בכם”.\nאון דערנאָך „ואתם מתחייבים כלי׳”: ניט נאָר אַז עס איז דאָ די שלילה פון כח הפועל בנפעל, נאָר עס ווערט די שלילה מצד הוי׳ — כללות ענין ההתהוות — ובמילא: „אתם מתחייבים כלי׳”.\nנאָך דעם איז רש״י אָבער מסיים: „לכך נאמר אני ה׳ אלקיכם”:\nדער מכוון פון די אזהרות איז (ניט אַז עס זאָל ח״ו זיין אַזאַ מצב, נאָר) אַז עס זאָל זיין דער חיוב⁴⁴ — „אני ה׳",[["35","35","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310049\" data-slug=\"tanya\" data-id=\"3401310049\">תניא פמ״ד</a>. תניא ח״ב בהקדמה. ועוד."],["36","36","ראה גם חי׳ ופי׳ מהרי״ק לפרש״י כאן."],["37","37","ראה ס׳ הליקוטים (ממאמרי כו׳ דהצ״צ) ע׳ הוי׳ (ע׳ קפב ואילך), וש״נ. סד״ה יו״ט של ר״ה תרס״ו. ועוד."],["38","38","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370443\" data-slug=\"torah-or\" data-id=\"3901370443\">תו״א מג״א צט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381161\" data-slug=\"likkutei-torah\" data-id=\"4001381161\">לקו״ת שה״ש ח, א</a>."],["39","39","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא רפל״ו</a>, ע״פ תנחומא נשא טז. ועוד."],["40","40","המשך תרס״ו ס״ע ג. ובכ״מ."],["41","41","שער היחוד והאמונה רפ״ד. — נסמן בסה״מ ה׳ש״ת ע׳ 40."],["42","42","ראה שו״ע או״ח סי׳ ה."],["43","43","ולכן התחיל רש״י מענין זה (וראה לעיל הערה 10), ואח״כ מפרש על הסדר — „אני ה׳”: „ומה הנאה כו׳” — אני, „ואתם מתחייבים כו׳” — הוי׳ (כבפנים)."],["44","44","ועפ״ז יתורץ לשון פרש״י „ומה הנאה יש לי בכם”, דאינו מובן — דהול״ל „אין לי הנאה בכם” (— ע״ד „איני אלקיכם”) — וע״פ הנ״ל מובן"]]],[1300221116,"אלקיכם”. און דערפאַר, אע״פ אַז דער חידוש אין דער אזהרה דאָ (לגבי התחלת הפרשה) איז די שלילה — „הא אם תטמאו איני אלקיכם”, שטייט אָבער אין פסוק „אני ה׳ אלקיכם”, ווייל די מטרה איז, אַז עס זאָל זיין „אני ה׳\nאלקיכם”: עס זאָל זיין די „הנאה . . בכם”, ובמילא ווערט „אני — ה׳ אלקיכם”: עצמותו ומהותו ית׳ ווערט נמשך אין אידן אין אַ פנימיות, ביז אַז דער „אני” ווערט „(הוי׳) אלקיכם” — כחכם וחיותכם — פון יעדער אידן.\n(משיחת ש״פ אחרי תשכ״ה)",[["","","ואדרבא — מוכרח („וסוגיא שלימה”, ובפרט — ביינה של תורה), ובל׳ התניא (פכ״ז) והכתוב (משלי טז, ד): כל פעל הוי׳ למענהו וגם רשע ליום רעה כו׳ יעשה הרע שלו יום כו׳ — ע״י שיתבונן שהוי׳ שואל אותם• כביכול „מה הנאה יש לי בכם” — כי פשוט שישנה הנאה אלא שצריך חיפוש מה היא, „ובקשתם משם” (ראה לקו״ת לב, ב ואילך — תשובה) „שישוב מרשעו” ויהי׳ „אני ה״א” פעם שני׳, „אנכי אנכי — ב׳ פעמים. •) וי״ל שזהו נכלל בהבת קול (חגיגה טו, א) שובו בנים כו׳ — הרהורי תשובה מלמעלה — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380322\" data-slug=\"likkutei-torah\" data-id=\"4001380322\">לקו״ת (במדבר ג, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380497\" data-slug=\"likkutei-torah\" data-id=\"4001380497\">שלח מו, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381225\" data-slug=\"likkutei-torah\" data-id=\"4001381225\">שה״ש כד, א</a>. ובכ״מ) במחז״ל הנ״ל, ודברכות ג, סע״א (ועוד)."]]],[1300221117,"<h3>קדושים</h3>\nא. אין פסוק1 „וכי תבואו אל הארץ ונטעתם גו' וערלתם גו' פריו שלש שנים יהי' לכם ערלים לא יאכל\", שטעלט זיך רש\"י אויף די ווערטער „שלש שנים יהי' לכם ערלים\" און איז מפרש: „מאימתי מונה לו משעת נטיעתו\".\nלערנען מפרשים2, אז דערמיט מיינט רש\"י באוארענען, אז דער מנין פון די „שלש שנים\" איז ניט „משעה שעושה פרי\", נאר „משעת נטיעתו\"; און דאס לערנט מען אפ פון דעם ווארט „ונטעתם\"3 — „לומר דמשעת נטיעה מונין\".\nדארף מען פארשטיין:\nא) אויב דער גאנצער הכרח אז „מונה לו משעת נטיעתו\" איז פון ווארט „ונטעתם\"4 — האט דאך רש\"י גע-דארפט מעתיק זיין (אויך) דעם ווארט אין דעם דיבור-המתחיל?\nדי שאלה איז נאך שטארקער: דער מקור פון דעם פירוש איז פון תורת כהנים5, און דארטן ברענגט זיך טאקע דער לימוד (בהמשך צו די דרשות) אויף „ונטעתם גו'\" — אבער רש\"י איז משנה פון תורת כהנים, און ברענגט עס אויף די ווערטער6 „שלש שנים יהי' לכם ערלים\", און דערמאנט אינגאנצן ניט דעם ווארט „ונטעתם\".\nב) און דעם ווארט „ונטעתם\" — פון וואנעט וויס מען בפשוטו ש\"מ אז דאס איז משעת נטיעתו און ניט „פריו ג' שנים\" דריי יאר פון פירות וואקסען?*)\nג) וואס איז די אריכות אין רש\"י סיי בההעתקה פון פסוק סיי — בלשונו „מאימתי מונה לו\" — ער האט גע-דארפט זאגן בקיצור: „שלש שנים7 — משעת נטיעתו\"?\n[אע\"פ אז אזוי איז דער לשון אין תורת כהנים — איז אבער (ווי גערעדט כמה פעמים) ניט ענינו של רש\"י בפירושו על התורה צו מעתיק זיין דרשות רז\"ל בלשונן, נאר ער איז מפרש פשוטו של מקרא; וואס דערפאר איז רש\"י אפט-מאל משנה (ופשיטא — משמיט) פון לשון רז\"ל, בהתאם צום פירוש הכתוב ע\"פ פשוטו של מקרא].\nב. דער ביאור אין דעם:\nרש\"י'ן בפשטות ארט דא די אריכות הלשון אין פסוק „שלש שנים יהי' לכם ערלים\": עס שטייט דאך שוין פריער „וערלתם ערלתו את פריו\", היינט פאר-וואס חזר'ט איבער דער פסוק נאכ-אמאל די ווערטער „יהי' לכם ערלים\", און זאגט ניט בקיצור: „וערלתם ערלתו את פריו שלש שנים\"?",[["1","1","פרשתנו יט, כג."],["2","2","רא\"ם, גו\"א ועוד."],["3","3","גו\"א, באר מים חיים (לאחי המהר\"ל), דבק טוב ועוד. וכ\"ה בקרבן אהרן לתו\"כ כאן."],["4","4","וראה פי' המשכיל לדוד כאן (שנלמד זה מדלא כתיב „עד שלש שנים גו'\", ע\"ש)."],["5","5","עה\"פ."],["6","6","שינוי זה בפרש\"י י\"ל בפשטות, כי בא לפרש המנין ד„שלש שנים\". אבל עדיין אינו מובן (כבפנים) — למה לא העתיק גם תיבת „ונטעתם\"?"],["7","7","זה שהעתיק רש\"י בהד\"ה גם התיבות „יהי' לכם ערלים\" קאי בפשטות על ההמשך בפרש\"י „יכול כו' ת\"ל יהי' כו'\". אבל ראה לקמן בפנים סעיף ב. *) בדפוס שני (ובא' מכת\"י רש\"י שתחי\"ו) — הד\"ה הוא „שלש שנים\"."]]],[1300221118,"נעמט רש\"י דערפון ארויס, אז אין ערלה זיינען פאראן צווי ענינים: (א) דער איסור פון ערלה אויף'ן (עץ ו)הפירות („חפצא\") — וערלתם ערלתו את פריו\", ובלשון רש\"י8: „יהא אטום ונסתם מליהנות ממנו\"; (ב) דער מנין פון די „שלש שנים\" — א דין אויפ'ן אדם („גברא\") — „(שלש שנים) יהי' לכם ערלים\"9.\nאון דאס מיינט רש\"י מיט זיין אריכות הלשון „מאימתי מונה לו משעת נטיעתו\": עס דארף זיין „מונה לו\" — דער אדם ציילט די „שלש שנים\"; און וויבאלד דער מנין איז „לכם\", איז מסתבר אז די „שלש שנים\" רעכענען זיך (ניט פון ווען דער עץ איז עושה פירות, נאר) פון פעולת האדם (גברא) — „ונטעתם\"10 — פון ווען ער האט איינ-געפלאנצט דעם עץ.\nועפ\"ז קומט ארויס נאך א נפק\"מ: וויבאלד אז דאס וואס „מונה לו משעת נטיעתו\" איז מצד דעם וואס דער מנין\nדארף זיין „לכם\", דארף אויסקומען, אז די שלש שנים (פון נטיעה) ווערן גע-רעכנט ניט לויט'ן עץ, נאר לויט'ן אדם („לכם\").\nדער חילוק צווישן די צווי אופנים — צי מ'רעכנט די „שלש שנים\" לויטן „עץ\" אדער לויט נטיעת האדם — איז אין פאל ווען מ'פלאנצט איין א צווייג פון א בוים וואס איז שוין אלט „שלש שנים\":\nאויב מ'זאל רעכענען לויטן עץ, האט אן ארט צו זאגן, אז וויבאלד דער צווייג האט שוין פריער דורכגעמאכט די שני ערלה, זיינען די פירות וואס וואקסן אויס פון דעם צווייג מותר מיד;\nאויב אבער מ'זאל רעכענען די „שלש שנים\" לויט דעם אדם הנוטע — „לכם\" — דארף אויסקומען, אז מ'דארף נאכ-אמאל אנהויבן ציילן „שלש שנים\" פון זינט דער אדם האט געמאכט זיין נטיעה (חדשה).\n[ולפ\"ז איז שיטת רש\"י בפירושו על התורה — ע\"ד הפשט — מתאים מיט חלק ההלכה שבתורה, וואס דער דין איז11, אז „אחד הנוטע ואחד המבריך כו'\" איז חייב בערלה12].\nג. עפ\"ז וועט מען אויך פארשטיין נאך אן ענין אין דעם פירוש רש\"י:",[["8","8","כאן (וראה הערה הבאה). ובראב\"ע כאן: שאותו פרי הוא חשוב כמו ערלה שהיא מוזקת כו'. ולהעיר מת\"א כאן: ותרחקון רחקא, ובתיב\"ע: ותגזרון גזרא — שמדגיש פעולת הגברא. וראה לקמן בפנים סעיף ד."],["9","9","אבל להעיר מפרש\"י לעיל (וארא ו, יב): וערלתם ערלתו עשו לו אוטם וכיסוי איסור שיבדיל בפני אכילתו. שלש שנים יהי' לכם ערלים אטום ומכוסה ומובדל מלאכלו — ומשמע מזה, ש„וערלתם גו'\" („עשו לו אוטם כו'\") הו\"ע דהגברא; ו„שלש שנים יהי' לכם ערלים\" („אטום כו'\") הו\"ע בהחפצא."],["10","10","אף שע\"ד ההלכה אין צ\"ל נטיעת אדם, כי גם אם עלה מאליו חייב בערלה (ערלה פ\"א מ\"ב) — דיבר הכתוב בהווה ונטעתם. וי\"ל שע\"ד הפשט צ\"ל נטיעת אדם דוקא, כהלשון „ונטעתם\". וראה תו\"כ כאן: „ונטעתם פרט לעולה מאליו\" (וראה ע\"ד ההלכה — מפרשים לערלה שם. ירושלמי שם פ\"א ה\"א וב'. רמב\"ם הל' מע\"ש ונטע רבעי פ\"י הלכה ה'-ו'. טושו\"ע יו\"ד סו\"ס רצד. ועוד)."],["11","11","ר\"ה ט, סע\"ב ובתוד\"ה מרכיב שם. רמב\"ם שם הי\"ד. טושו\"ע שם סט\"ז."],["12","12","וגם לדרשת התו\"כ כאן „ונטעתם פרט למרכיב ולמבריך\" — ראה תוס' (ועוד) לר\"ה שם שאיירי כשלא נפסקה מהאילן הזקן כו'. וראה ערלה פ\"א מ\"ה ובמפרשים שם. ירושלמי שם פ\"א ה\"ג. רמב\"ם וטושו\"ע שם ונ\"כ. ועוד. וגם לפמ\"ש הרמב\"ן (והובא בקיצור בר\"ן) ר\"ה שם, דלר' אליעזר בן יעקב (סוטה מג, ב) נתמעט מבריך ומרכיב מערלה (וראה מלבי\"ם כאן) — הרי אין הטעם בזה מפני שמונים לפי העץ, כ\"א מפני שאין זה דרך נטיעה."]]],[1300221119,"נאך די ווערטער „מאימתי מונה לו משעת נטיעתו\", איז רש\"י ממשיך — אין דעם זעלבן דיבור-המתחיל — „יכול אם הצניעו לאחר שלש שנים יהא מותר ת\"ל יהי' בהוייתו יהא\".\nדארף מען פארשטיין: די צווי ענינים אין פירוש רש\"י — (א) „מאימתי מונה לו משעת נטיעתו\", (ב) „יכול אם הצניעו כו'\" — האבן לכאורה קיין שייכות ניט צווישן זיך: „מאימתי מונה לו כו'\" איז א פירוש אויף די ווערטער „שלש שנים\"13, און „יכול אם הצניעו כו'\" — אויף די ווער-טער „יהי' לכם ערלים\":\nהאט דאך רש\"י געדארפט מחלק זיין די צווי ענינים אין באזונדערע דיבור-המתחיל's (כדרכו בכ\"מ) — פארוואס ברענגט זיי רש\"י בהמשך אחד אין דעם זעלבן דיבור-המתחיל14?\nדי תמי' אין דעם איז נאך שטארקער: אויך דער מקור פון דעם ענין („יכול אם הצניעו כו'\") אין פירוש רש\"י איז פון תורת כהנים15, אבער דארט קומט עס טאקע ניט בהמשך צום לימוד „מאימתי מונה כו'\"16, נאר עס איז א לימוד פאר זיך — היינט פארוואס איז רש\"י משנה פון תו\"כ און איז מצרף די צווי לימודים צוזאמען?\nד. ע\"פ הנ\"ל (סעיף ב) איז עס מובן בפשטות:\nוויבאלד דער פסוק איז מדגיש „יהי' לכם ערלים\" — אז עס איז א דין אין „גברא\" (כנ\"ל) — קען מען דאך מיינען אז עס איז ניט נאר בשייכות צום פרט פון „שלש שנים\" (אז דער מנין דארף זיין „לכם\", כנ\"ל), נאר אז כללות איסור ערלה איז בלויז „לכם\", אן איסור גברא17,\n(און די ווערטער „יהי' לכם ערלים\" זיינען ניט א הוספה אויף די ווערטער „וערלתם ערלתו את פריו\" (און א דין בלויז אין מנין ג' שנים), נאר זיי זיינען דער פירוש און אויסטייטש פון „וערלתם ערלתו את פריו\" — אז עס מיינט בלויז „יהי' לכם ערלים\", אן איסור גברא):\nאון אויב מ'זאל אננעמען אז דער איסור ערלה איז ניט חל אויף די פירות גופא (נאר עס איז בלויז אן איסור על האדם ניט צו עסן די פירות די ערשטע דריי יאר) — איז דא אן ארט צו זאגן, אז נאך די ג' שנים איז ניטא דער איסור ערלה, אפילו ניט אויף די פירות וואס זיינען געוואקסן אין די ג' שני ערלה.\nמ'וואלט געלערנט, אז ערלה איז אן איסור גברא („יהי' לכם ערלים\") התלוי בזמן („שלש שנים\")18 — אזוי ווי דער איסור אכילת חמץ בפסח19 וכיו\"ב — א געוויסן זמן טאר עס דער אדם ניט עסן20; ובמילא, „אם הצניעו לאחר שלש",[["13","13","וגם לפמשנ\"ת לעיל בפנים שפירושו זה („מאימתי כו'\") שייך גם להתיבות „יהי' לכם ערלים\" — הו\"ל לרש\"י להעתיק עוה\"פ תיבות אלו ולפרש „יכול כו' ת\"ל יהי' כו'\" (כדרכו בכ\"מ. ולדוגמא בפרשתנו לעיל יט, ג)."],["14","14","ראה מה שתי' במשכיל לדוד כאן. וראה הערה 18."],["15","15","עה\"פ (בשינוי לשון)."],["16","16","ויש הפסק דרשה אחרת ביניהם."],["17","17","ראה לעיל הערה 8."],["18","18","עפ\"ז יתוסף ביאור גם בתי' השפ\"ח כאן (בשם הנח\"י)."],["19","19","ראה צפע\"נ לרמב\"ם הל' חו\"מ פ\"א ה\"ז, שזהו טעם המ\"ד (פסחים כח, ריש ע\"ב. שם כט, א) דחמץ שעבר עליו הפסח אסור רק מדרבנן. ולמ\"ד (שם כח, סע\"א) שהוא אסור מה\"ת, הוא מפני ש„ס\"ל דהחיוב הוא בהדבר ולא בהזמן\", ד„חמץ הוא איסור בעצמו שאסור לאוכלו בפסח\"."],["20","20","ראה בארוכה אתוון דאורייתא (כלל יו\"ד)"]]],[1300221120,"שנים\" איז עס מותר (וויבאלד דער זמן איסורו איז שוין אריבער).\nלערנט מען אפ פון ווארט „יהי'\" — „בהוייתו יהא\" — אז דער איסור ערלה בלייבט שטענדיק אויף די פירות, אויך נאך די שלש שנים21.\nה. דער טעם פנימי פון דעם חילוק צווישן איסורי גברא ואיסורי חפצא — י\"ל אז דאס היינגט אפ פון וואנעט עס קומט דער חיות פון דעם דבר הנאסר:\nאיסורי חפצא (אז דער חפץ פאר זיך איז אסור), איז ווען דער חפץ איז מקבל א חיות אסור, פון ג' קליפות הטמאות לגמרי22 וואס קענען ניט נתעלה ווערן אין קדושה, און דערפאר איז דאס א חפצא של איסור ואסור לעולם;\nאיסורי גברא איז ווען די זאך איז מקבל א חיות סתם, פון קליפת נוגה22 וואס קען נתעלה ווערן אין קדושה, און דערפאר איז ער א חפצא של היתר (נאר דער גברא טאר עס ניט עסן וכיו\"ב).\nאון פירות ערלה זיינען אן איסור חפצא (כנ\"ל בארוכה) — ווייל זייער חיות איז פון ג' קליפות הטמאות (ווי דער אלטער רבי ברענגט אראפ אין תניא<sup data-n=\"23\">23</sup>.\nעס פאדערט זיך אבער נאך הסברה: וויבאלד אז דער אילן אליין איז א דבר היתר24, און די פירות זיינען דאך יונק חיותם פון דעם אילן — ווי קען זיין, אז דער אילן אליין זאל זיין א דבר המותר און די פירות וואס קומען פון אים ארויס זאלן זיין א חפצא של איסור?\nווען פירות האילן וואלטן אלעמאל געווען אסור, וואלט מען נאך געקענט מסביר זיין, אז אט דער חלק החיות25 פון דעם אילן פון וואנען די פירות זיינען יונק זייער חיות איז פון ג' קליפות הטמאות;\nוויבאלד אבער אז נאך ג' שנים זיינען די פירות מותר, קומט אויס, אז אויך דער חלק (החיות של) האילן איז ניט פון ג' קליפות הטמאות — היינט ווי ווערן די פירות אן איסור חפצא?\nו. וועט מען דאס פארשטיין בהקדם הביאור אין דעם לשון פון אלטן רבי'ן אין תניא26 וועגן „מאכלות אסורות מהצומח כמו ערלה וכלאי הכרם כו'\" — אז זייער „קיום וחיות\" איז פון ג' קליפות הטמאות; איז מדייק דער רבי (מהורש\"ב) נ\"ע27, אז „בערלה וכלאי הכרם לא אמר וקיום גופם\" — ניט ווי פריער, ביי „בעלי חיים הטמאים ואסורים באכילה\", וואו דער אלטער רבי",[["","","ובית האוצר (אות א כלל קכה) — להרי\"ן ענגל — שקו\"ט באיסורים זמניים אם הם איסור חפצא או איסור גברא. ונת' בארוכה בההתועדות."],["21","21","ע\"ד חמץ שעבר עליו הפסח להדיעה שאסור מה\"ת (ראה הערה 19). ולהעיר מלשון אדה\"ז בשולחנו (הל' פסח סתמ\"ז סמ\"ה) „ועכשיו הוא כחתיכת נבילה\" — דלכאורה: כוונת אדה\"ז שם היא לבאר איך שלא חל שינוי בשם חמץ כשמגיע זמן איסורו, כי גם קודם הפסח „הי' שמו חמץ\". ואי\"כ, תיבות הנ\"ל („שעד עכשיו לא אסרו הכתוב ועכשיו הוא כחתיכת נבילה\" — ולא „ועכשיו נאסר\" וכיו\"ב) הן הדגשה להיפך! ומשמע מזה, שס\"ל שחמץ בתוך הפסח הוא איסור חפצא (אף שחמץ שעבר עליו הפסח אסור רק מדרבנן — שם ר\"ס תמח). וצ\"ע."],["22","22","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">תניא ספ\"ו</a> ואילך (מע\"ח שמ\"ט)."],["23","23","שם (מע\"ח שם פ\"ו). שם רפל\"ז. וראה הנסמן בהערה 30."],["24","24","ראה ערלה פ\"א מ\"ז. תו\"כ כאן."],["25","25","להעיר מריש ערלה: רי\"א אפילו אמר הפנימי למאכל והחיצון לסייג הפנימי חייב והחיצון פטור."],["26","26","ספ\"ו."],["27","27","קיצורים והערות לתניא ע' קטו."]]],[1300221121,"זאגט אז (ניט בלויז זייער „נפשות\", נאר) אויך „קיום גופם\" איז פון ג' קליפות הטמאות — און איז מסביר: „שהרי גופם (פון ערלה כו') טהור כו'\".\nאיז לכאורה ניט פארשטאנדיק: פירות ערלה זיינען דאך אסור לעולם — דארף דאך דער „קיום גופם\" פון די פירות זיין פון ג' קליפות הטמאות; און אויב ווייל די פירות נעמען זיך פון דעם אילן וואס איז א דבר היתר — איז דאך אויך דער חיות הפירות פון (און דורך) דעם אילן?\nאיז דער ביאור אין דעם: דער חילוק פון „קיום גופם\" און „קיום וחיות\" איז:\nדער גוף וגשם פון א נברא איז באַ-שאפן געווארן בלויז איין מאל, און דער-נאך איז מען בלויז מקיים די פריער-דיקע מציאות, און דערפאר איז אין דעם ניט שייך א שינוי מזמן לזמן פון זיך אליין28 (אז עס זאל זיך בייטן דער ארט פון וואנעט עס קומט „קיום גופם\");\nדאקעגן דער חיות פון צומח ודומם ווערט כסדר נתחדש פון-דאס-ניי (כמבואר בכמה מקומות29 בפירוש „המחדש בטובו בכל יום תמיד מעשה בראשית\", אז „בכל יום\" ווערט נמשך א חיות חדש), און דערפאר קען ווערן א שינוי אין דעם חיות.\nאון דאס איז אויך דער ביאור באיסור ערלה: דער גוף וגשם האילן וואס איז א דבר טהור — בלייבט טהור, ווייל אין דעם קען קיין שינוי ניט ווערן (לגבי ווי עס איז געווען פריער):\nמשא\"כ דער חיות וכח מיט וועלכן דער אילן איז מצמיח די פירות און זיי זיינען יונק (פון אילן), איז במשך די שלש שני ערלה איז עס א חיות פון ג' קליפות הטמאות30 — און מצד דעם ווערן די פירות אן איסור חפצא31 (ואסורים לעולם);\nאון דערנאך ווערט נשפע ונמשך אין דעם אילן30 א חיות חדש32, וואס די פירות שלו (בשנה הרביעית) זיינען ניט נאר טהורים ומותרים, נאר אדרבה — „קדש הלולים לה'\"33.\n(משיחות אחרון של פסח וש\"פ קדושים תשל\"ו)",[["28","28","לבד כשהאדם עושהו אשרה וכיו\"ב. ועצ\"ע בנוגע לכלאי הכרם. ולהעיר מרמב\"ם הל' מאכא\"ס (פ\"י ה\"ו) „בין שעלו מאליהן . . אסורין\"."],["29","29","ראה בארוכה מאמרי חגה\"ש תרס\"ה והש\"ת."],["30","30","ראה לקו\"ת פרשתנו ד\"ה וכי תבואו פ\"ב. אוה\"ת עה\"פ. וש\"נ."],["31","31","אף ש„גופם טהור\" (כמו האילן). ויתירה מזו — האילן עצמו (גם החיות שבו) טהור, כי גופם דהפירות שייך לגופם דהאילן (גם בנוגע להיתר ואיסור), ולא להחיות שמשפיע האילן שאינו אלא בדוגמת מעבר, וי\"ל דוגמא לזה — יפה כח הבן מכח האב (שבועות מח, סע\"א), שהאפשריות לזה היא מפני דפנימיות הבן לוקח מפנימיות האב (אף שלא נתגלה באב) — ואח\"כ נתגלה בבן בכח הבן (ולפעמים אינו מגלה ואינו יפה)."],["32","32","אבל צ\"ע אם אפ\"ל כן בכל איסורים זמניים, כי דוחק לומר (ובפרט למ\"ד דחמץ לאחרי הפסח אסור מה\"ת) שיש שינוי בחיות של אותו הדבר (משא\"כ בנדו\"ד, שפירות ערלה אסורים לעולם)."],["33","33","פרשתנו יט, כד. וראה לקו\"ת ואוה\"ת שם."]]],[1300221122,"<h3>קדושים ב</h3>\nא. נאָך דעם ווי די תורה זאָגט אָן דעם דין פון ערלה און כרם רבעי1, שטייט אין פסוק2: ובשנה החמישית תאכלו את פריו להוסיף לכם תבואתו אני ה' אלקיכם.\nאיז רש\"י מעתיק די ווערטער \"להוסיף לכם תבואתו\" און מפרש: המצוה הזאת שתשמרו תהי' להוסיף לכם תבואתו שבשכרה אני מברך לכם פירות הנטיעות.\nבפשטות לערנט מען3, אז רש\"י קומט באווארענען אז די ווערטער \"להוסיף לכם תבואתו\" זיינען ניט א המשך (\"דבוק\") צו \"ובשנה החמישית תאכלו את פריו\" — ווייל ווי פאסט צו זאָגן אז צוליב \"תאכלו את פריו\" וועט זיין דער שכר פון \"להוסיף לכם תבואתו\"?! — נאָר דאָס איז דבוק צו די פריערדיקע פסוקים וואו עס רעדט זיך וועגן שמירת המצוה: \"המצוה הזאת שתשמרו תהי' להוסיף כו'\".\nעס איז אבער ניט פארשטאנדיק די אריכות הלשון אין פרש\"י — לכאורה האט ער געדארפט זאָגן בקיצור (ע\"ד ווי דער אבן עזרא<sup data-n=\"4\">4</sup> אז \"להוסיף לכם תבואתו\" איז \"דבק עם קדש הלולים\" (וכיו\"ב); אדער (ווי אין רשב\"ם<sup data-n=\"4\">4</sup> \"להוסיף לכם תבואתו — (לכך תזכו) אם תעשו כאשר צויתי\".\nאון אפילו אז מ'וועט איינטייטשן (בדוחק גדול), אז רש\"י וויל אויך קלאר מאכן דעם פירוש פון \"להוסיף לכם תבואתו\" — און דאָס מיינט \"בשכרה אני מברך לכם פירות הנטיעות\"5 — האט רש\"י געקענט זאָגן בקיצור: \"להוסיף לכם תבואתו — בשכר המצוה הזאת אני מברך לכם פירות הנטיעות\"?\nוואס איז די אריכות וכפל הלשון אין רש\"י: \"המצוה הזאת שתשמרו תהי' להוסיף לכם תבואתו (און דערנאָך) שבשכרה אני מברך לכם פירות הנטיעות\"?\nב. אויך זיינען פאראן נאָך כמה דיוקים בלשון רש\"י, ומהם:\nא) \"המצוה הזאת שתשמרו כו'\" — וואס איז די הוספת הדיוק \"הזאת\"? אז רש\"י וואלט געזאגט \"כשתשמרו המצוה\" (וכיו\"ב, אן דער הדגשה \"הזאת\") וואלט מען אויך געוואוסט אז עס רעדט זיך וועגן דער מצוה (וואס וועגן איר רעדט דער פסוק)?\nב) \"אני מברך לכם פירות הנטיעות\" — פארוואס איז רש\"י משנה פון לשון הפסוק \"תבואתו\"?\nאפילו אויב רש\"י דארף באווארענען אז דער טייטש פון \"תבואתו\" דא איז6 (ניט תבואת השדה, נאָר) נטיעות הכרם7 (וכהתחלת הענין8: ונטעתם כל עץ מאכל) — האט רש\"י געדארפט זאָגן (בקיצור) \"מברך לכם הפירות\" (אדער \"הנטיעות\"). וואס איז דער כפל הלשון \"פירות הנטיעות\"?",[["1","1","קדושים יט, כג־כד."],["2","2","שם, כה."],["3","3","ראה ס' זכרון, משכיל לדוד ובאר יצחק כאן."],["4","4","עה\"פ."],["5","5","ושולל בזה פי' ריה\"ג בתו\"כ כאן. ועוד."],["6","6","אבל דוחק, כי מסתימת לשון רש\"י שבהערה הבאה (וכן — ל' הכתוב תצא כב, ט) משמע שאין בפירוש זה חידוש."],["7","7","ראה רש\"י בהר כה, כ. וראה גם רד\"ק כאן."],["8","8","יט, כג."]]],[1300221123,"<h3>קדושים ב</h3>\nג. ווייטער איז רש\"י ממשיך: \"הי' ר' עקיבא אומר דברה תורה כנגד יצר הרע שלא יאמר אדם הרי ארבע שנים אני מצטער בו חנם לפיכך נאמר להוסיף לכם תבואתו\".\nצוליב וואס ברענגט רש\"י דעם מאמר פון ר' עקיבא?\nלערנען מפרשים9, אז דערמיט פאר־ענטפערט רש\"י פארוואס שטייט דער שכר נאכדעם ווי \"ובשנה החמישית תאכלו גו'\" און ניט פריער ביי שמירת המצוה (פאר וועלכער עס קומט דער שכר) — ברענגט רש\"י מאמר רע\"ק10, אז דער שכר קומט דערפאר וואס \"ארבע שנים אני מצטער בו חנם\" — וואס דער אדם האלט זיך אפ פון עסן די פירות ביז שנה החמישית11, \"וה\"ק9 מה שתאכלוהו בחמישית בלבד ולא כו' יהי' להוסיף\".\nאבער דער פירוש איז ניט גלאטיק, ווייל דאס וואס דער שכר מצוה שטייט ניט פריער איז מלכתחילה קיין שאלה ניט אין פשוטו של מקרא: בדרך כלל, דארט וואו ס'ווערט געזאגט אין תורה דער שכר מצוה, שטייט עס בסיום הענין. ועד\"ז בענינינו: פריער פאר־ענדיקט די תורה אלע פרטי המצוה (ווי דער אדם דארף זיך פירן מיט זיינע פירות) — \"שלש שנים . . לא יאכל.\nובשנה הרביעית יהי' כל פריו קודש . . (און אז דוקא נאכדעם) ובשנה חמישית (מעג זיין) תאכלו את פריו\" — און ערשט דערנאך ווערט אנגעזאגט שכר המצוה (וואס דער אויבערשטער וועט דערפאר געבן) \"להוסיף לכם תבואתו\"12.\nאויך דארף מען האבן א הסברה וואס רש\"י ברענגט דעם ענין בצירוף שם אומרו, וואס (ווי גערעדט פיל מאל) רש\"י טוט דאס נאר דארט וואו דאס איז מוסיף אין הבנת הפירוש.\nאון נאכמער: אין דעם גופא איז רש\"י מדייק \"הי' ר' עקיבא אומר\", אז ר' עקיבא פלעגט שטענדיק זאגן דעם מאמר — וואס גיט צו די הדגשה13 אין הבנת הענין?\nד. אין דעם מאמר גופא — וואס רש\"י ברענגט פון ר' עקיבא — איז ניט פארשטאנדיק:\nעס זיינען דא כו\"כ מצות, ביי וועלכע תורה זאגט־אן דעם שכר המצוה, און רש\"י איז ביי זיי ניט מפרש, אז דער טעם וואס תורה איז מבטיח שכר המצוה איז \"כנגד יצר הרע\" (דהיינו, אז לולא דעם שכר וועט דער יצר הרע ניט לאזן מקיים זיין די מצוה):\nפון וואנעט איז דער הכרח, אז דוקא דער שכר איז (אנדערש פון אן אנדער שכר מצוה, און איז) געזאגט געווארן \"כנגד יצר הרע\" (און ניט ווייל עס קומט דעם אדם דער שכר וויבאלד אז ער האט זיך מצטער געווען חנם ד' שנים)?",[["9","9","משכיל לדוד."],["10","10","תו\"כ עה\"פ."],["11","11","כלשון רש\"י (מתו\"כ) \"ארבע שנים אני מצטער בו חנם\". ולכאורה צ\"ע שהרי בשנה הרביעית מותר לאכול הפירות בירושלים וא\"כ אינו \"מצטער . . חנם\"? ומתורץ ע\"פ פרש\"י בפסוק שלפנ\"ז \"מה מע\"ש אינו נאכל כו' אלא בפדיון אף זה כן\", שמזה מובן שפירות רבעי אינם שלו כ\"א מה שמשולחן גבוה קזכי (וראה גם מפרשי התו\"כ כאן שזוהי פלוגתת ריה\"ג ורע\"ק, שלריה\"ג הם ממון בעלים ולרע\"ק — ממון גבוה)."],["12","12","ומש\"נ \"להוסיף גו'\" בסמיכות ל\"תאכל גו'\" אינה קושיה (כ\"כ). כמ\"ש בראב\"ע כאן \"ורבים כמוהם\"."],["13","13","ובפרט שבתו\"כ (לפנינו) איתא \"ר' עקיבא אומר\"."]]],[1300221124,"<h3>קדושים ב</h3>\nבשלמא ביי דער פרשה פון \"יפת תואר\", איז מובן וואס רש\"י זאגט14 אויף \"ולקחת לך לאשה\"15 אז \"לא דברה תורה אלא כנגד יצר הרע\" — ווייל, ווי רש\"י איז מבאר, \"אם אין הקב\"ה מתירה ישאנה באיסור\"; ד.ה. אז בעצם וואלט עס געדארפט זיין א דבר האסור16, נאר הקב\"ה מתירה. ובמילא — אן ענין וואס איז מוכח מתוכו אז דאס איז געזאגט געווארן נאר \"כנגד יצר הרע\"17.\nאבער בכלל איז ענין שכר פאר א מצוה געפינט מען בפירוש אין תורה ביי כו\"כ מצות (כנ\"ל) און דאס איז א יסוד בנוגע צו מצות (אז דער אויבערשטער גיט שכר מצות)18 — איז פארוואס איז אויסגעטיילט דער שכר (פאר דער מצוה פון ערלה און כרם רבעי), אז דוקא ער איז געזאגט געווארן \"כנגד יצר הרע\"19?\nה. ווייטער שטעלט זיך רש\"י אויף די ווערטער \"אני ה'\" און איז מפרש: \"אני ה' המבטיח על כך ונאמן לשמור הבטחתי\".\nאיז ניט מובן: דער לשון הרגיל בפרש\"י בכגון דא איז (בקיצור) \"נאמן לשלם שכר\"20. פארוואס איז רש\"י דא\nמאריך בלשונו — \"אני ה' המבטיח על כך ונאמן לשמור הבטחתי\"?\nנאך מער: ניט נאר עס איז אן אריכות הלשון, נאר אויך א שינוי: ניט \"נאמן לשלם שכר\", נאר \"נאמן לשמור הבטחתי\"21, ועוד, רש\"י איז משנה (אויך פון זיין פריערדיקן לשון בענינינו \"שב־שכרה אני מברך כו'\"), און זאגט אן ענין פון הבטחה (\"המבטיח . . לשמור הבטחתי\")?\nו. וי\"ל הביאור בזה:\nדי שאלה אין פסוק וואס רש\"י קומט פארענטפערן בפירושו איז [ניט בנוגע דעם ארט פון די ווערטער \"להוסיף לכם תבואתו\" — וכנ\"ל (סעיף ג) אז בפשוטו של מקרא איז דאס מלכתחילה קיין קשיא ניט — נאר] אין דעם פירוש התיבות:\nאויב תורה וואלט סתם געמיינט אנ־זאגן דעם שכר המצוה, האט געדארפט שטיין (ע\"ד ווי אין אנדערע ערטער<sup data-n=\"22\">22</sup> \"למען23 הוסיף לכם תבואתו\", אדער \"ואוסיף לכם תבואתו\" וכיו\"ב.\nדער לשון \"להוסיף לכם תבואתו\" (בלמ\"ד בתחלתה) ווייזט, אז דאס איז דער מכוון און תכלית פון דער מצוה — \"שלש שנים גו' לא יאכל. ובשנה הרביעית יהי' כל פריו קודש גו' (כדי) להוסיף לכם תבואתו\". ע\"ד \"זכור את יום השבת לקדשו\"24, וואס דער \"לקדשו\" איז (ניט א שכר, נאר) די מטרה און תכלית פון דעם \"זכור\".\nדערפון איז רש\"י מכריח, אז דער פשט אין פסוק איז: \"המצוה הזאת",[["14","14","תצא כא, יא (מקידושין כא, ב)."],["15","15","תצא שם."],["16","16","כפרש\"י תצא שם בד\"ה שלאח\"ז \"אפילו אשת איש\". וראה מפרשי רש\"י שם."],["17","17","ועד שאפילו אחרי ההיתר \"אם נשאה סופו . . בן סורר ומורה\" (פרש\"י שם ד\"ה ולקחת)."],["18","18","כמפורש בעשרה\"ד (יתרו כ, ו ובפרש\"י), ובכ\"מ. וראה בארוכה לעיל ע' 2־71."],["19","19","להעיר מפרש\"י ר\"פ צו \"ביותר צריך הכתוב לזרז במקום שיש בו חסרון כיס\", ומפורש לקמן בפ' בהר (כה, כ) \"וכי תאמר מה נאכל\". — אבל גם במקומות אלו לא כתב רש\"י \"דברה תורה כנגד יצר הרע\"."],["20","20","כפרש\"י ר\"פ וארא. פרשתנו לעיל יט, י. ועוד (ראה הנסמן לעיל ע' 97 הערה 15)."],["21","21","ע\"ד לשונו בפ' וארא שם (ו, ג. שם, ו)."],["22","22","ראה לדוגמא יתרו כ, יב."],["23","23","וראה תיב\"ע כאן: מטול כר."],["24","24","יתרו שם, ח."]]],[1300221125,"<h3>קדושים ב</h3>\nשתשמרו תהי' להוסיף לכם תבואתו\" — כאטש אז בכלל דארף מען מקיים זיין א מצוה דערפאר וואס אזוי האט דער אויבערשטער געהייסן, אבער ביי דער מצוה זאגט תורה, אז איר שמירה25 איז (מעג זיין) מלכתחילה מיט דער כוונה \"להוסיף לכם תבואתו\"26.\nאון דאס איז וואס רש\"י איז מאריך בלשונו: די ווערטער \"להוסיף לכם תבואתו\" זיינען ניט קיין אנזאג אויף דעם שכר המצוה, נאר די תורה רעדט דא (בעיקר) וועגן כוונת האדם — אז ער טוט די מצוה כדי \"להוסיף לכם תבואתו\". קומט אויס, אז אין פירש\"י ווערן ארויסגעבראכט צוויי ענינים: (א) דער פירוש פון \"להוסיף לכם תבואתו\" איז אז דאס רעדט זיך וועגן כוונת האדם — \"המצוה הזאת שתשמרו תהי' להוסיף לכם תבואתו\". (ב) דער טעם ווי אזוי קען דער אדם אזוי טראכטן — ווייל (דא האט דער אויבערשטער אנגעזאגט במיוחד אז) אזוי וועט עס זיין בפועל: \"שבשכרה אני מברך לכם פירות הנטיעות\".\nז. עפ\"ז ווערט די שאלה: ווען \"להוסיף לכם תבואתו\" וואלט געמיינט דעם אנזאג אויף שכר מצוה, וואלט קיין קשיא ניט געווען וואס די ווערטער שטייען בסיום הענין (כנ\"ל).\nאבער לויט פי' רש\"י, אז דאס באציט זיך (בעיקר) צו כוונת האדם בעת קיום (שמירת) המצוה — האט עס געדארפט שטיין בסמיכות צו די ווערטער וואס ריידן וועגן שמירת המצוה (\"לא יאכל\"\n— (מיט דער כוונה) להוסיף לכם תבואתו)?\nבאווארנט עס רש\"י דורך דעם וואס ער איז משנה פון לשון הכתוב \"תבואתו\" און זאגט \"פירות הנטיעות\": דורך שטעלן די ווערטער \"להוסיף לכם תבואתו\" נאך \"ובשנה החמישית גו'\" וויל דער פסוק אנדייטן אויפן אופן הברכה: דער פשט אין \"להוסיף לכם תבואתו\" איז ניט נאר אז דער אויבערשטער וועט געבן א תוספת ברכה אין דער צמיחה און וואוקס פון די פירות, נאר אז אויך נאכדעם ווי עס וועלן אויסוואקסן די \"פירות הנטיעות\" פון שנה החמישית (זייענדיק גרייט צו \"תאכלו את פריו\"), וועט אין זיי גופא חל זיין ברכת ה' באופן של הוספה וריבוי — \"אני מברך לכם פירות הנטיעות\" [ע\"ד ווי רש\"י זאגט אין פ' בהר27 \"אף בתוך המעים תהא בו ברכה\"].\nח. עס בלייבט אבער ניט פאר־שטאנדיק: מיט וואס איז די מצוה אנ־דערש פון אלע אנדערע מצות וואס דוקא בא איר, איז: א) תורה זאגט אן אז מען מעג מלכתחילה מקיים זיין די מצוה כדי \"להוסיף לכם תבואתו\"; ב) דער שכר עצמו איז אנדערש ווי דער שכר פון אנדערע מצות (אין אן אופן שלא בערך — א ברכה אין \"פירות הנטיעות\" כנ\"ל)?\nברענגט דערפאר רש\"י דעם מאמר פון ר' עקיבא — \"דברה תורה כנגד יצר הרע שלא יאמר אדם כו'\": וויבאלד ס'איז זייער שווער צו מקיים זיין די מצוה, וואָרום א מענטש קען דאך טענה'ן \"ארבע שנים אני מצטער בו",[["25","25","ועפ\"ז יל\"פ לשון רש\"י \"תהי' להוסיף לכם תבואתו\" — תהי' שמירתכם (ולא — תהי' המצוה)."],["26","26","דלא כמ\"ש בבאר מים חיים (לאחי המהר\"ל) כאן. וראה לקמן סעיף ח."],["27","27","כה, יט. ועד\"ז בפרש\"י בחוקותי כו, ה. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051134\" data-slug=\"likkutei-sichot\" data-id=\"1300051134\">לקו\"ש ח\"ה (ע' 122</a>) בפרש\"י תולדות (כו, יב) ד\"ה מאה שערים."]]],[1300221126,"<h3>קדושים ב</h3>\nחנם\" — האט מען \"מתיר\" געמאכט (\"כנגד יצר הרע\") צו האבן אין זינען דעם שכר המצוה בעת קיומה; און כדי צו \"באפרידיקן\" דעם יצה\"ר איז דער אויבערשטער מבטיח א שכר שלא ע\"ד הרגיל.\nועפ\"ז איז פארשטאנדיק בפשטות וואס רש\"י איז דערנאך ממשיך \"אני ה' — אני ה' המבטיח על כך ונאמן לשמור הבטחתי\": דא איז ניט מספיק דער זירוז \"נאמן לשלם שכר\" ווי בא אנדערע מצות — היות אז דא רעדט זיך וועגן א מצוה וואס דער אדם טוט מלכתחילה לשם שכרה, און לולא דעם וואלט דער יצר הרע אויסגעפירט, ניט דערלאזן צו מקיים זיין די מצוה —\nדעריבער איז דא דער פירוש פון \"אני ה'\" — \"המבטיח על כך ונאמן לשמור הבטחתי\": וויסנדיק אז דאס איז א הבטחה פון אויבערשטן און \"נאמן לשמור הבטחתי\", איז דאס מספיק אז אויך דער יצר הרע זאל מוזן מסכים זיין אויפן קיום המצוה28.\nט. ביי א תלמיד ממולח קען זיך אבער דערוועקן א שאלה: ווי קומט עס אז מ'זאל ביי דער מצוה אזויפיל משנה זיין פון אלע מצות — מתיר מאכן צו אפהיטן לשם שכר, און דערצו נאך מבטיח זיין א שכר בלתי טבעי ורגיל כלל — און דאס אלץ צוליב איינעם וואס איז אין אזא שפל המצב אז דער איינציקער וועג צו פועל'ן אויף אים איז צו באווארענען \"כנגד יצר הרע\"?\nזאגט רש\"י אז דאס זאגט ר' עקיבא — דער וואס האט געזאגט \"ואהבת לרעך\nכמוך . . זה כלל גדול בתורה\"29; אויך איז ר' עקיבא געווען דער וואס \"הי' רגיל לזכות את ישראל\"30. און לויט שיטת רע\"ק, אז געפינען א זכות אויף יעדן אידן און פרואוון אים העלפן כו', איז א כלל גדול בתורה — איז מובן פארוואס תורה פארנעמט זיך מיט יעדן אידן און באווארנט אויך אזא וואס דארף אנקומען צו \"דברה תורה כנגד יצר הרע\".\nדערביי איז רש\"י מדייק \"הי' ר' עקיבא אומר\", אז ער פלעגט דעם מאמר נאכאנאנד חזר'ן, וואס דאס באווייזט אז אין דער באווארעניש פון \"דברה תורה כנגד יצר הרע\" האט זיך \"ארויסגעזאגט\" א זאך, וואס איז במיוחד פארבונדן מיט מהותו ומעלתו של ר' עקיבא31 — און דערפאר האט דוקא ר' עקיבא גע'חזר'ט וועגן דער גרויסער תועלת דערפון:\nר' עקיבא האט די ערשטע פערציג יאר פון זיין לעבן ניט געלערנט קיין תורה32. ערשט דאן, ווען מען האט אים צוגעזאגט שכר אויב ער וועט גיין לערנען תורה, איז ער געגאנגען לערנען33.",[["28","28","וגם: הי' מקום לומר, שמכיון שמקיים המצוה בשביל לקבל פרס, לא יקבל השכר, ולכן מוכרחת ההוספה שהקב\"ה מבטיח על כך, שבכל אופן יקבל השכר."],["29","29","פרש\"י לעיל פסוק יח (מתו\"כ עה\"פ)."],["30","30","פרש\"י סנהדרין קי, ב ד\"ה שבקי'."],["31","31","להעיר מפי' כ\"ק מו\"ח אדמו\"ר בנוסח ההגדה \"חכם מה הוא — אומר\" (הגש\"פ עם לקוטי טעמים ומנהגים ע' יז)."],["32","32","אדר\"נ פ\"ו, ב."],["33","33","כתובות סב, סע\"ב ואילך*. — באדר\"נ שם ד\"ה תחלתו של רע\"ק . . פעם אחת הי' עומד על פי הבאר אמר מי חקק אבן זו . . מיד חזר ללמוד *) בנדרים (נ, א) דלאחרי שנשאת לו בת כלבא שבוע א\"ל זיל הוי בי רב. אבל בכדי שלא יסתור להא דכתובות, י\"ל שהתנתה עמו לפני הנישואין שילך ללמוד (וכדמוכח בחדא\"ג מהרש\"א כתובות שם). ובתוד\"ה ורבי יהושע (שבת קנ, א) שלא נשאה עד לאחר שלמד כ\"ד שנה."]]],[1300221127,"<h3>קדושים ב</h3>\nקומט אויס, אז ביי ר' עקיבא'ן איז גע־ווען כעין דעם מצב פון \"הרי ארבע שנים אני מצטער בו חנם\": זיין גיין לערנען תורה איז געווען פארבונדן מיט \"אוועקוואָרפן\" די ערשטע פערציג יאר פון זיין לעבן: דורך גיין לערנען תורה איז ער מדגיש אז די פריערדיקע יארן זיינען \"מצטער בו חנם\" (זיי זיינען אומ־זיסטע יארן):\nאון — ער איז געגאנגען לערנען תורה צוליב א שכר34 — ואעפ\"כ האט ער מצליח געווען אין לימוד התורה מיט אזא הצלחה מופלגה ועילוי נעלה כ\"כ35, ביז אז \"כולהו אליבא דר' עקיבא\"36.\nאון דעריבער \"הי' ר' עקיבא אומר דברה תורה כו'\" — ווייל כעין זה איז געווען דער מצב מיט אים: דורך הבטחת שכר האט ער אנגעהייבן לערנען תורה און סו\"ס — געקומען צו זיין מדריגה מעלת ר' עקיבא.\nיו\"ד. עס איז אבער נאך אלץ ניט גלאטיק (בפנימיות הענינים): סוף־סוף איז די נויטיקייט פון \"דברה תורה כנגד יצה\"ר\" בלויז פאר מתי מספר פון אידן וועלכע זיינען גאר בשפל המצב — פארוואס איז די מצוה אויסגעשטעלט געווארן באופן כזה פאר אלע אידן, אין אן אופן וואס איז מדגיש \"דברה תורה כנגד יצר הרע\"?\nאיז דער ביאור אין דעם: דער פירוש הפנימי אין \"דברה תורה כנגד יצה\"ר\" איז, אז די מצוה איז ענינה, וואס תורה וויל דערמיט איבערמאכן דעם יצר הרע (ע\"ד ואהבת גו' בכל לבבך בשני יצריך<sup data-n=\"37\">37</sup>, אז דער יצה\"ר מצד עצמו זאל וועלן טאן א מצוה38. און דערפאר איז דער שכר פון דער מצוה \"להוסיף לכם תבואתו\", וויל דוקא דורכן בירור (ואת־הפכא) פון יצה\"ר און נפש הבהמית ווערט די אמת'ע \"הוספה\" אין קדושה, כידוע הפירוש39 אין \"ורב תבואות בכח שור\"40, אז דער \"רב תבואות\" (הוספה ועילוי רב בקדושה) קומט \"בכח שור\" דוקא, דורכן בירור פון נפש הבהמית.\nאון מהטעמים דערויף איז, ווייל די עבודה איז פארבונדן מיט צער: עבודת הנשמה מצ\"ע איז מתוך עונג, אבער די עבודה פון בירור נפש הבהמית פא־דערט יגיעה צו דורכברעכן דעם העלם והסתר פון נה\"ב, דורך אתכפיא.\nאון דעריבער מוז פריער זיין דער צער פון ארבע שנים וואס דער נפש הבהמית האט ניט קיין הנאה41 פון דער תבואה,\nאון דורך דער אתכפיא ווערט דער־נאך אתהפכא, ביז עס ווערט \"להוסיף לכם תבואתו\" — ורב תבואות בכח שור.\n(משיחות ש\"פ אחו\"ק תשכ\"ח, ש\"פ קדושים תשל\"ו)",[["","","תורה\". אבל בפשטות, הי' זה לאחרי הסיפור דכתובות, אלא שחשב שלאחרי מ' שנה בלי תורה שוב לא יוכל ללמוד, עד שראה אבן כו' ודן ק\"ו בעצמו כו'. וכן משמע מנוסחא הב' באדר\"נ שם \"זה רע\"ק שבקש ללמוד תורה הלך וישב לו על באר אחת כו'\" [וראה בנין יהושע לאדר\"נ שם, שבזמן הסיפור דאדר\"נ כבר הי' לומד מקרא (וראה פירושו במש\"כ שם \"כתב לו א\"ב ולמדה\". ואכ\"מ)]."],["34","34","ראה גם עיון יעקב לע\"י כתובות שם."],["35","35","ראה אדר\"נ שם. נדרים וכתובות שם. ועוד."],["36","36","סנהדרין פו, א."],["37","37","משנה ברכות רפ\"ט (נד, א)."],["38","38","שלא בערך יותר ממלאך רע בעל כרחו יענה אמן (שבת קיט, ב)."],["39","39","לקו\"ת האזינו עה, ריש ע\"ד. ובכ\"מ. וראה בארוכה ס' הערכים־חב\"ד (כרך א) ע' אהבת ה' — ההוספה שבה כו'. וש\"נ."],["40","40","משלי יד, ד."],["41","41","ראה לעיל הערה 11."]]],[1300221128,"<h3>אמור</h3>\nא. די מצוה פון ספירת העומר, אויף וועלכער מ'איז נצטווה געווארן בפרשתנו1 „וספרתם לכם ממחרת השבת מיום הביאכם גו' עד ממחרת השבת השביעית תספרו חמשים יום\", איז עניַנה (לויט כמה מפרשים ופוסקים) — א הכנה והכשרה צו חג השבועות, זמן מתן תורתנו2. ובלשון החינוך3: „נצטוינו למנות ממחרת יום טוב של פסח עד יום נתינת התורה להראות בנפשנו החפץ הגדול אל היום הנכבד בלבינו כעבד ישאף צל4 וימנה תמיד מתי יבא העת הנכסף אליו שיצא לחירות כי המנין מראה באדם כי כל ישעו וכל חפצו להגיע אל הזמן ההוא\"5.\nדער תוכן ועניַן הנ\"ל פון ספה\"ע איז אויך נוגע להלכה, ווי עס ברענגט זיך ענין הנ\"ל בכמה פוסקים6, אלס איינער פון די טעמים וואס מ'מאכט ניט קיין שהחיינו אויף ספירת העומר.\nאעפ\"כ זעט מען אז די מצוה פון ספירת העומר איז א מצוה און — מיט א שלימות בהמצוה — בזמן הבית און אויך בזמן הזה (לויט די דיעות בזה, צי דאס איז מדאורייתא, אדער מדרבנן, זכר למקדש<sup data-n=\"7\">7</sup> — מ'מאכט אויף איר א ברכה און נאכמער — יעדן טאג, ביז אז דורך ספירת העומר וואס איז א מצוה על כל אחד ואחד מישראל „וספרתם לכם שתהא ספירה לכל אחד8 ואחד\", וערט אויפגעטאן אז ביום החמישים לעומר איז חג השבועות9.",[["1","1","כג, טו-טז."],["2","2","ראה מו\"נ ח\"ג פמ\"ג. חינוך מצוה שו. מדרש („הגדה\") הובא בעיטור (סוף הלכות מצה ומרור), ונעתק בשו\"ת הרשב\"א (ח\"ג סרפ\"ד). ר\"ן סוף פסחים. ועוד. וראה גם לבוש או\"ח סתפ\"ט סוס\"א. אברבנאל פרשתנו. וכ\"ה לפי המפרשים דלקמן הערה 5."],["3","3","שם."],["4","4","ערב לנוח ממלאכתו (איוב ז, ב ובמצו\"ד). — ואולי גם ירמוז לבסוכות (העשויות לצל) הושבתי את בנ\"י ביצי\"מ."],["5","5","לפי מ\"ש בהעיטור (הובא בשו\"ת הרשב\"א שם וברן שם בפירוש דברי המדרש הנ\"ל („מכאן קבעו חכמים לספירת העומר בזמן הזה\"•) „שהרי עכשיו אין אנו מביאין לא קרבן ולא עומר אלא שאנו מחשבין יום לשמחת התורה כמו שישראל מנו באותה שעה\" — מובן, שעניַן הנ\"ל בספה\"ע הוא בזמן הזה. אבל מדברי החינוך ועד\"ז המו\"נ (ושאר ספרים שבהערה 2) משמע שזהו שרש המצוה גם בזמן הבית. וראה גם דרשות מהראנ\"ח (הנותן אמרי שפר) — וויניציאה, ש\"צ (ועוד) — פרשתנו דרוש ב'. •) בהעיטור ושו\"ת הרשב\"א שם הובאו תיבות אלו („בזמן הזה\") בסיום דברי ה„הגדה\"; וברן שם ליתא, אלא כתבו בפירושו „כלומר בזמן הזה שאין אנו כו'\"."],["6","6","לבוש שם בטעם הב'. ובטעם הא' כתב „משום שהספירה הוא משום צורך יו\"ט (שבועות) וסמכינן אזמן דרגל\". ועד\"ז בצרור המור פרשתנו עה\"פ, ומוסיף „כדאמרינן בסוכה ובביעור חמץ\". ובעקידה פרשתנו (שער ס\"ז פ\"ד — הובא במט\"מ סתרס\"ט), שספירת הזמן מורה על הצער ההוא בהעדרו ועל התענוג המקווה בהוויתו כמו בכל ספירות ימי הטמאים והטמאות ושבעה שבועות הרי\"ז כדוגמת ז' נקיים דאשה כו'. „ולפי שהימים האלה לשלמי הבחינה הם ימי צער לפיכך לא קבעו לברך שהחיינו בתחלת מספרם . . אמנם קבעוהו תיכף מלאת ימי הטוהר כו'\". וראה מטה משה שם."],["7","7","ראה שו\"ע אדה\"ז או\"ח סתפ\"ט ס\"ב. וש\"נ. ולהעיר דאף שמסיים שם „וכן עיקר\", מ\"מ מתחיל הסימן: מצות עשה מן התורה שיספור כל אחד כו'. ואכ\"מ. — וראה לקו\"ש חה\"ש תנש\"א הערה 56 (סה\"ש תנש\"א ח\"א ע' 459 הערה 79)."],["8","8","מנחות סה, ב. וראה פרש\"י שם. שו\"ע אדה\"ז שם בריש הסימן. וראה הנסמן בחק יעקב או\"ח שם סק\"ד."],["9","9","ראה שו\"ע אדה\"ז שם ר\"ס תצד (משו\"ת •) ראה לקמן ס\"ה. וש\"נ."]]],[1300221129,"ב. ע\"פ הנ\"ל אין דעם גדר פון ספי־רת העומר, קען מען מבאר זיין דעם טעם וואס דער אלטער רבי האט גע־שטעלט ספירת העומר צום סוף פון זיין סידור.\nעס איז ידוע גודל הדיוק בסדר פון דעם אלטן רבי\"ן בכל עניניו, ובפרט אינעם „סדר תפלה\"10 וואס תוכנו איז „סדר תפלות מכל השנה\" — איז מובן, אז דער סדר אין דעם איז בתכלית הדיוק11. דער דיוק אינעם סדר איז נאכ־מער מודגש, ווען מ'פארגלייכט עס מיטן סדר אין סידור האריז\"ל12, וואס\nדעם אלטן רבי\"נס סידור איז דאך „ע\"פ נוסח האריז\"ל\"13 — וואס אין סידורי האריז\"ל (שראיתי) איז דער סיום (ניט מיט ספירת העומר14, נאר) מיט (די כוונות פון) שמע\"צ ושמח\"ת15.\nבפשטות יש לבאר דעם טעם וואס דער אלטער רבי האט משנה געווען בסידורו פון דעם סדר בסידור האריז\"ל, ווייל דעם אלטן רבי\"נס סידור איז, כידוע, א שווה לכל נפש, ניט ווי סידור האריז\"ל, וואס איז פאר יחידי סגולה. און ווי ס'איז אויך ידוע, אז מטעם זה האט דער אלטער רבי אין זיין סידור ניט אריינגעשטעלט די אלע כוונות פון אריז\"ל (בסידורו)16.\nדערפאר איז דער סדר אין סידור אדמו\"ר הזקן — תדיר קודם לשאינו תדיר — ובאינו תדיר, די מצות וואס קומען פ\"א17 בשנה וכו' שטייען זיי",[["","","הריב\"ש סי' צו). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300031257\" data-slug=\"likkutei-sichot\" data-id=\"1300031257\">לקו\"ש ח\"ג ע' 995</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081056\" data-slug=\"likkutei-sichot\" data-id=\"1300081056\">ח\"ח ע' 56</a> הערה 42."],["10","10","ראה הגהות כ\"ק אדמו\"ר (מוהרש\"ב) נ\"ע (נדפסו בסידורי הוצאת קהת: סידור עם דא\"ח (שכ, ד), תורה אור• (רלב, סע\"א)) עד היכן הדברים מגיעים, שכותב שהצ\"צ „דקדק שלא יהי' שום שינוי מהסידור של רבינו הגדול ז\"ל אף בדבר כזה שאינו נוגע לשום דבר בעצם הנוסחא [שלכן הגי' הצ\"צ ואדמו\"ר נ\"ע בהסידור „רצה ומודים כו' תמצא בשחרית\", במקום שנדפס שם כל הנוסח דרצה ומודים כו'] ולפי\"ז לא טוב עשה המו\"ל הזה [= של סידור תורה אור] מה ששינה בענינים האלו בהסידור הזה בכמה מקומות כמו אשרי קודם ובלצ\"ג וב\"ש ופסוה\"ז בשחרית דשבת, וכן אשרי קודם מוסף וקוה ועלינו כו' וכדומה, דהגם שאינו נוגע בעצם הנוסח מ\"מ אין לשנות ועד\"ז חייב אדם לומר בלשון רבו וגם שאפשר שיש בזה איזה כוונה כי גבהו דרכיו כו' . . בוודאי יש בזה כוונה מיוחדת\"."],["11","11","ובמיוחד ע\"פ מה שאמר הצ\"צ, אשר „הי' לפניו ששים סדורים מנוסחאות שונות ומכולם בירר וליבן את הנוסחא שבסידור שלו\" (בית רבי ח\"א פכ\"ז בהערה. וראה שם פ\"י)."],["12","12","הר\"ש מרשקוב — שנדפס לפני הדפסת סידור אדה\"ז בשנת תקס\"ג (נוסף עז שהי' בכת\"י כמה שנים לפנ\"ז). ועד\"ז בסידור האריז\"ל קול יעקב. וראה בפרטיות בהקדמת שער הכולל ע\"ד הסידורים ע\"פ קבלת האריז\"ל. וראה גם ע\"ד סידור אדה\"ז בהמובא בפתח דבר לסידור עם דא\"ח (קה\"ת תשכ\"ה. תשל\"א. תשמ\"א)."],["13","13","כנוסח השער דסידורי אדה\"ז."],["14","14","ועד\"ז הוא בפע\"ח ושער הכוונות, שאינם מסתיימים בעניני ספירת העומר (בפע\"ח מסיים בשער הלולב, ובשער הכוונות בענין חנוכה ובענין פורים)."],["15","15","ופרטי המצות „מזוזה חלה שחיטה ביקור חולים\" בסידור הר\"ש מרשקוב, לכאורה הם כמו הוספה, ולא חלק מהסידור. ועד\"ז ה„מעשה רב\" ו„סדר הנהגות ישרות\" שבסוף סידור קול יעקב."],["16","16","ראה שער הכולל שם. לקו\"ש ח\"ד ע' 1149."],["17","17","משא\"כ מצות מילה (ופדיון הבן) וכיו\"ב ש(אינם תלויים בזמני השנה ו)זמן קיומם בדרך כלל הוא בבוקר, ונסדרו אחרי תפילת שחרית דחול•. וברכות אירוסין ונישואין באות אגב גררא דברכת המזון (והם ג\"כ אינן תלויות בזמני השנה). ואכ\"מ. •) כ\"ה בסידור תורה אור. וכן מוכח מהגהות הצ\"צ להסידור (נדפסו בסידור תורה אור ו(בהוצאת קהת) בסידור עם דא\"ח שיח, א). משא\"כ בסידור עם דא\"ח שבאות לאחרי ברכת נישואין. ואכ\"מ. ובהגהות כ\"ק אדמו\"ר (מוהרש\"ב) נ\"ע שהקפיד •) הוצאת ברוקלין, תש\"א (ע\"י אגודת חסידי חב\"ד), ושלאחרי'."]]],[1300221130,"דארט לויטן סדר השנה: חנוכה, פורים, סדר קרבן פסח, הגדה של פסח, (ולאח\"ז) ספירת העומר.\nוויבאלד אבער אז דער אלטער רבי האט געשריבן סידורו בהתאם מיט דעת הפוסקים להלכה, און צוזאמען דערמיט אויך מברר ומלבן געווען דעם נוסח ע\"פ כוונות האריז\"ל18 (נאר די סודות וכוו־נות האט ער ניט מעתיק געווען, כדי אז עס זאל זיין שווה לכל נפש — אויך צו די וואס זיינען ניט שייך צו בפועל מכוין זיין די סודות<sup data-n=\"16\">16</sup>, איז מובן, אז אויך דער סדר אין סידור איז ניט נאר בהתאם צו פשטות הענינים, נאר ע\"פ תוכן הענין ווי ס'איז ע\"פ נגלה און מיט זייער תוכן בפנימיות הענינים.\nועפ\"ז יש לומר — וואס ספירת העומר קומט בסיום וחותם פון סידור, ווייל אין דער מצוה פון ספה\"ע קומט בהדגשה יתירה דער תוכן ונקודה עיקרית פון ענין התפלה — ע\"פ נגלה וע\"פ סוד, וכדלקמן.\nויש לומר אז אט דער ענין מיוחד פון ספירת העומר איז סיי אין דער „חפצא\" פון תפלה און ספירת העומר, סיי אין דעם „גברא\", כדלקמן בארוכה.\nג. די מצוה פון תפלה19 איז, ווי דער",[["18","18","הסכמת כ\"ק הרה\"ק כו' מהרי\"ל זצ\"ל מיאנאוויטש (אחי אדה\"ז) לסידור אדה\"ז — נדפסה בסידור עם דא\"ח — קהת — (שכג, ב), תו\"א (בהתחלתו), ועוד."],["19","19","ובמק\"א מדובר ע\"ד ב' הביאורים א) דעיקר התפלה — תפילת העמידה (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380604\" data-slug=\"likkutei-torah\" data-id=\"4001380604\">לקו\"ת בלק עא, ג</a>). ב) על השינויים בסי' תורה אור ומנה כמה מהם (כנ\"ל הערה 10), ולא הזכיר השינויים בהסדר הנ\"ל. וי\"ל שבזה לא שינה בסדור תו\"א מסידור אדה\"ז. וסידור עם דא\"ח עיקר הכוונה הי' להו\"ל את הדרושים דדא\"ח, וסדר הסידור טפל ולכן סיומו — בחה\"ש. — וראה שער הכולל שם אות ח. דעיקרה ק\"ש ושאר התפלה הוא ביאור הק\"ש כנודע (הקדמת אדה\"ז לסדורו)."],["20","20","ריש הל' תפילה."],["21","21","בכותרת להל' תפלה שם."],["22","22","ובסהמ\"צ שלו מ\"ע ה „שציונו לעבדו וכבר נכלל זה הציווי פעמים כו'\". אבל במנין המצות שבריש ספר היד כתב „להתפלל אליו שנאמר כו' ועבודה זו תפלה\". וראה כ\"מ (ומגדל עוז) הל' תפלה שם."],["23","23","הל' תפלה שם ה\"ב."],["24","24","בביאור גדר התפלה לדעת הרמב\"ם — ראה בארוכה במפרשי הרמב\"ם שם."],["25","25","סנהדרין סה, א."],["26","26","בסיפור יצי\"מ דליל פסח הרי למדו (מכילתא ס\"פ בא. רמב\"ם בסהמ\"צ שלו מ\"ע קנז. וראה גם הל' חמץ ומצה רפ\"ז) מוהגדת לבנך דצ\"ל הגדה וסיפור רמב\"ם20 זאגט: „מצות עשה להתפלל בכל יום שנאמר ועבדתם את ה' אלקיכם מפי השמועה למדו שעבודה זו היא תפלה שנאמר ולעבדו בכל לבבכם אמרו חכמים אי זו היא עבודה שבלב זו תפלה\". ובמקום אחר21 איז דער רמב\"ם מתאר די מצות עשה: „לעבוד את ה' בכל יום בתפלה\"22. איינעם פון די ביאורים ע\"פ נגלה אויף דעם וואס תפלה איז אן ענין פון עבודה (— עבודה שבלב), קען מען אריסלערנען פון לשון הרמב\"ם גופא23 „חיוב מצוה זו כך הוא שיהא אדם מתחנן ומתפלל בכל יום ומגיד שבחו של הקב\"ה ואחר כך שואל צרכיו שהוא צריך להם בבקשה ובתחנה ואח\"כ נותן שבח והודי' לה' על הטובה שהשפיע לו\"24. די הסברה בזה: מצות טיילן זיך בכלל אין צווי סוגים: מצות שבמעשה — צי אין אן עשי' כפשוטה בפועל ממש, ווי לבישת ציצית, הנחת תפלין, וכו', אדער בדיבור (מעשה זוטרתא25), ווי קריאת המגילה, סיפור ביצי\"מ וכיו\"ב, וואס עיקר קיום המצוה שבזה איז פעולת הדיבור והקריאה26; און מצות של חובות הלבבות ווי אהבת ה' יראת ה' כו', וואס עניַנם איז די כוונה ורגש האדם במחשבתו ולבו27."]]],[1300221131,"מצות התפלה איז מיוחד בזה28, אז אע\"פ אז תפלה מוז זיין בדיבור דוקא29, איז אבער די „מעשה\" המצוה פון תפלה — „שיהא אדם מתחנן ומתפלל בכל יום\": דער תוכן פון „מתחנן\" איז עבודה ורגש בלב האדם — ניט עשי' אדער דיבור.\nאון אע\"פ אז בכמה מצות איז דער דין אז די מצות של תורה „צריכות כוונה לצאת י\"ח בעשיית אותה מצוה\", און בשעת עס פעלט די כוונה „לא יצא ידי חובתו מן התורה\"30 — איז עס נאר אן ענין פון כוונת המצוה31, אבער ניט א חלק פון דער מצוה גופא32.\nבא תפלה אבער33 איז די חפצא פון מעשה התפלה — „מתחנן ומתפלל\", כוונת הלב (וכלשון הרמב\"ם לאח\"ז „ואחר כך שואל צרכיו34 שהוא צריך להם בבקשה ובתחנה\"), וואס לזה דארף זיין די הקדמה „שיפנה את לבו מכל המחשבות ויראה עצמו כאילו הוא עומד לפני השכינה\"35 (און דערנאך בשעת התפלה זאל בא אים זיין „בקשה",[["","","(ראה מנ\"ח מצוה כא. ועוד)•, הרי מובן דגדר המצוה הוא (הגדה—) דיבור. אבל ק\"ש „שאינה מצות עשי' אלא קבלת מ\"ש ועול מצות שהוא דבר התלוי בכוונת העניַן\" (שו\"ע אדה\"ז או\"ח סי' ס ס\"ה), הרי גם ק\"ש היא בכלל תפילה (אף שבפרט נחלקת לתפלת העמידה, ק\"ש, ברכות ק\"ש ועוד. וראה לעיל הערה 19), ופשיטא דהוה חלק מסידור תפלה (אף שנמנו כב' מצות במנין המצות). ולהעיר דהמצוה לקרות ק\"ש פעמיים ביום למדים ממ\"ש ודברת בם בשכבך ובקומך (סהמ\"צ להרמב\"ם (ובמנין המצות) מ\"ע יו\"ד) ולא כתפלה (העמידה) שלמדין (כנ\"ל ברמב\"ם) מועבדתם כו' שמזה משמע קצת, שק\"ש שייכת יותר לדבור מתפלה. ואכ\"מ."],["27","27","אלא שגם באהבת ה' יש „מעשה\" המצוה „שנחשוב ונתבונן במצותיו כו'\" — סהמ\"צ להרמב\"ם מ\"ע ג. וראה לשונו בספר היד ריש פ\"ב מהל' יסוה\"ת."],["28","28","ראה גם בית אלקים להמבי\"ט שער התפלה פ\"ג."],["29","29","ראה מג\"א או\"ח סי' קא סק\"ב. שו\"ע אדה\"ז שם ס\"ד. ובספרים המחלקים המצות לתלויות בראש כו'."],["30","30","שו\"ע אדה\"ז סי' ס שם. וש\"נ. וראה שד\"ח כללים מע' מ' כלל סא ואילך. •) וראה גבורות השם (למהר\"ל מפראג) סוף פס\"ב."],["31","31","וראה לקו\"ש ח\"ד ע' 1128 ואילך."],["32","32","וראה שו\"ע אדה\"ז או\"ח סתע\"ה סכ\"ח."],["33","33","ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310043\" data-slug=\"tanya\" data-id=\"3401310043\">תניא פל\"ח</a> „תפלה או שאר ברכה בלא כוונה הן כגוף בלא נשמה\", וי\"ל שכוונתו לכוונות ה„פרטיות\" שבתפלה שבדומה לשאר ברכות ומצות, משא\"כ הכוונה כללית (המבוארת בפנים). ובמיוחד הכוונה שבלעדה התפלה בטלה (רמב\"ם הל' תפלה פ\"ד הט\"ו, ראה לקמן הערה 36). וראה שו\"ע אדה\"ז סקפ\"ה ס\"ב. לקמן הערה 39."],["34","34","לכאורה זהו עיקר גדר מצות תפלה — בקשת צרכיו, משא\"כ שבחו של הקב\"ה ה\"ז בעיקר הקדמה לתפלה. וכפשטות לשון הגמ' (ברכות לב, א. — שהביא הכס\"מ לרמב\"ם שם ה\"ב) „לעולם יסדר אדם שבחו של הקב\"ה ואח\"כ יתפלל\"• (וראה בית אלקים שם פ\"ב ועוד. וראה עקידה שער נח). ולכאורה י\"ל שזהו דיוק לשון הרמב\"ם „ומגיד שבחו של הקב\"ה ואחר כך שואל צרכיו שהוא צריך להם בבקשה ובתחנה ואח\"כ נותן שבח והודי' לה' על הטובה שהשפיע לו\", דשבחו של הקב\"ה גדרו (בעיקר) „מגיד\", הגדה, משא\"כ בקשת צרכיו ושלאח\"ז, הוא עבודה ורגש שבלב. וכן משמע בחינוך מצוה תלג: גם הרמב\"ם ז\"ל . . אבל מ\"מ חיוב התורה הוא להתחנן לא-ל בכל יום ולהודות לפניו כו' (ואינו מזכיר סידור שבחיו בתחלה). אבל בשו\"ע אדה\"ז סי' קפה סוס\"ב „סידר שבחו של מקום . . שזהו עיקר מצות התפלה\". וכ\"מ בסי' ס שם. ואכ\"מ."],["35","35","רמב\"ם שם פ\"ד הט\"ז. וראה שו\"ע אדה\"ז או\"ח ר\"ס צח. •) בכס\"מ שם העתיק לשון הגמ' „ואח\"כ ישאל צרכיו כו'\", אבל כנראה שדייק „ישאל צרכיו\" במקום „יתפלל\" כדי לבאר מהו „יתפלל\" כמקור ללשון הרמב\"ם „ואח\"כ שואל צרכיו כו'\"."]]],[1300221132,"ותחנה\"), און בלא זה איז ניט נאר אז דער גברא איז ניט יוצא ידי חובת המצוה, נאר עס איז ניטאָ קיין חפצא, דער דיבור איז ניט קיין תפלה36.\nענין הנ\"ל שבתפלה, אז דוקא די ידיעה וכוונה מאכט די חפצא פון מצות התפלה און אן דעם הייסט עס ניט קיין חפצא פון תפלה37, איז בגלוי אין ספה\"ע: דער אלטער רבי פסק'נט38 „מותר לספור בכל לשון שמבין אבל אם אינו מבין הלשון שסיפר בו אפילו ספר בלשון הקודש אם אינו מבינו לא יצא דכיון שאינו יודע המנין אין זו ספירה כלל\"39.\nדאס הייסט, אז דער ענין פון מצות הספירה איז ניט די פעולה פון (ספירת הימים ב)דיבור (אע\"פ אז ספירה מוז זיין בדיבור<sup data-n=\"40\">40</sup>, נאר די ידיעת (מחשבת) האדם, און בלי דער ידיעת וכוונת האדם איז (ער ניט נאר ניט יוצא ידי חובת הספירה, נאר עס איז) בכלל ניטאָ קיין חפצא פון ספירה — „אין זו ספירה כלל\"41.\nד. ווי־באלד אז די מציאות פון תפלה וערט געשאפן ע\"י כוונת (עבודת) האדם, איז מובן, אז לכל לראש, איז דער שינוי וועלכער וערט אין דעם „גברא\" ע\"י התפלה והקדמתו לזה. און אויך אין דעם איז א נקודה משותפת פון תפלה און ספירת העומר (ניט נאר אין חפצא פון דער מצוה):\nתפלה, וואס עיקרה איז תפלת העמידה, איז וואס א איד איז עומד42, שטעלט זיך כעבדא קמי' מרי'43 פאר דעם אויבערשטן, „ויראה עצמו כאילו הוא עומד לפני השכינה\", וואס דע־מאלט איז ער „מתחנן ומתפלל\" — ער וערט א מציאות פון א מתפלל.\nבשעת אן אדם איז „מפנה את לבו מכל המחשבות כו'\" און איז מתחנן ומתפלל פאר דעם אויבערשטן, וערט ער מיט דעם גופא נשתנה און נתעלה ממצבו הקודם, ער שטייט אין א מעמד",[["36","36","בחדושי הגר\"ח על הרמב\"ם, דאם אין לבו פנוי ואינו רואה עצמו שעומד לפני ה' ומתפלל אין זה מעשה תפילה, כהרמב\"ם שם הט\"ו „כל תפלה שאינה בכוונה אינה תפילה\". עיי\"ש. אמנם כוונת הלב (שיפנה את לבו כו' ויראה עצמו כו' עומד לפני השכינה) ה\"ז בכלל „ה' דברים (ה)מעכבים את התפלה\" (רמב\"ם רפ\"ד שם). ולפי המבואר בפנים ג\"ז אינו מספיק שייקרא מעשה תפלה, אלא צריך להיות הרגש ד„מתחנן (ומתפלל)\" בשעת התפלה. וראה שו\"ע אדה\"ז שם סו\"ס קא „שתפלה בלא כוונה אינה כלום\" (ראה ספר חסידים סתקפ\"ח, תשפה. ובמג\"א שם סק\"ה), והמדובר שם בכוונה „שיבין מה שאומר\" שלכן מוטב שיתפלל בלשון שמבין\". ואולי הלשון „אינה כלום\" היינו שאינו יוצא בה ידי\"ח (ראה שו\"ע אדה\"ז שם סס\"ב ס\"ב), או שמה שכתב „בלא כוונת הלב שתפלה בלא כוונה אינה כלום\" ה\"ז הכוונה הכללית ולא פירוש המלות**. ודוחק. ועצ\"ע."],["37","37","יש לומר עד\"ז גם בענין התשובה — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171197\" data-slug=\"likkutei-sichot\" data-id=\"1300171197\">לקו\"ש חי\"ז ע' 197</a> ואילך."],["38","38","סתפ\"ט סעיף יו\"ד."],["39","39","ואף שגם בק\"ש וברכת המזון צריך לומר בלשון שמבין — ראה שו\"ע אדה\"ז ססי\"ב שם; סקפ\"ה ס\"א ורס\"ב (וש\"נ) — הרי גם ק\"ש וברהמ\"ז בכללות ה\"ז חלק או מעין התפילה (כנ\"ל הערה 26), ונוסף לזה: א) בק\"ש ישנו לימוד מיוחד (סוטה לב, ב — הובא בשו\"ע אדה\"ז ססי\"ב שם) שמע בכל לשון שאתה שומע, משא\"כ בספירה. ב) בברהמ\"ז הביא אדה\"ז בסי' קפה ס\"א „וי\"א שבלה\"ק יוצא אדם יי\"ח אע\"פ שאינו מבין הלשון כו' ולכן הנשים כו' יוצאין יי\"ח בשמיעה מהמברך בלה\"ק וכן נוהגין\". משא\"כ בספירה שלא הביא אדה\"ז דיעה אחרת בזה. וראה שו\"ע אדה\"ז סקפ\"ה ס\"ב. וראה שם ס\"ה חילוקים בין בהמ\"ז ותפלה."],["40","40","שו\"ע אדה\"ז שבהערה 8 (ועוד), עיי\"ש."],["41","41","ראה שו\"ת דבר אברהם ח\"א סל\"ד."],["42","42","ואמרז\"ל אין עמידה אלא תפלה (ברכות ו, ב)."],["43","43","שבת י, א. שו\"ע אדה\"ז סו\"ס צה. *) וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091269\" data-slug=\"likkutei-sichot\" data-id=\"1300091269\">לקו\"ש ח\"ט ע' 269</a>. אבל ראה לקו\"ש חי\"ד ע' 223. **) ולהעיר מאגרות קודש אדמו\"ר האמצעי ע' רפו וע' שיא. שער היחוד ה, א. ואכ\"מ."]]],[1300221133,"ומצב שונה לגמרי44, עס וערט א שינוי וחידוש אין דעם גברא.\nאון אויך דער ענין איז מודגש בספירת העומר, וואס יעדער איד זאגט בפשטות בתפלתו נאך דער ספירה פון יעדער נאכט: „אתה צויתנו כו' לספור ספירת העומר כדי לטהרנו מקליפותינו ומטומאתנו כמו שכתבת בתורתך כו' כדי שיטהרו נפשות עמך ישראל מזוהמתם\".\nה. די שייכות הנ\"ל איז אלץ מצד דער פעולה און עבודה פונעם אדם בתפלה ובספירת העומר. ס'איז דא נאך אן ענין מיט וועלכן תפלה טיילט זיך אויס פון רוב כל המצות — אין דער כוונה ומבוקש פון דער תפלה:\nרוב כל המצות איז עיקרן די מעשה המצוה (ובשלימות — מיט דער כוונת המצוה) און דערמיט האט זיך אפגעטאן אויך דער גמר המצוה מצד האדם.\nאנדערש איז מצות התפלה: פון איין זייט איז דער עצם גדר התפלה „שיהא אדם מתחנן ומתפלל\", „שואל צרכיו שהוא צריך להם בבקשה ובתחנה\", אז דער אויבערשטער זאל ממלא זיין בקשתו45; דאס איז ניט א צווייטע זאך לבד התפלה, נאר דאס איז דער תוכן כל מעשה התפלה. בעטן דעם אויבערשטן עס זאל זיין מילוי הבקשה;\nאבער צוזאמען דערמיט איז דער קיום המצוה פון תפלה ניט פארבונדן כלל מיטן מילוי בקשתו בפועל; מיט די\nתחנונים ותפלת האדם איז ער מקיים די מצות תפלה ובשלימותה46.\nועד\"ז איז בנוגע לספירת העומר: ספירת העומר איז א מצוה וואס איז א הכנה והכשרה צו חג השבועות, צו מתן תורה, כנ\"ל סעיף א' [ובפרט ע\"פ ביאור הזהר47 אז די ספירה פון די ז' שבועות איז ע\"ד ספירת ז' נקיים — אז דורך דעם זיינען אידן זיך מטהר בכדי להיכנס לחופה במתן תורה בחג השבועות]:\nוביחד עם זה וערט די ספירה אן ענין ומצוה (ובברכה (והמשכה)) בפ\"ע, אז די השתוקקות והכנה והכשרה גופא איז אן ענין פאר זיך, און אן ענין הכי עיקרי — ער איז דעם אידן, (כנ\"ל) מטהר מזוה־מתו; דאס איז מדגיש מעלת עבודת האדם מצד עצמה.\nו. עפ\"ז יש לבאר דעם חילוק צווישן דעם סידור האריז\"ל און דעם סידור פון אלטן רבי\"ן (כאטש אז דער סידור פון אלטן רבי\"ן איז מדויק ומכוון ע\"פ נוסח האריז\"ל), וואס דאס איז מודגש גלייך ביי די התחלות פון די סידורים:\nסידור האריז\"ל48 הויבט זיך אן מיט „כללות תיקון ועליות העולמות\"; דער סידור פון אלטן רבי\"ן פאנגט זיך אן מיט „מודעת זאת מעלת קימת חצות לילה כו' ע\"כ יתאמץ לקום בחצות באיזה לילה שיוכל ולהיות מכלל עבדי ה' כו'\" —\nדי הסברה בזה:\nלויט ווי פנימיות הענינים וערט ארויסגעבראכט אין סידור האריז\"ל,",[["44","44","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380580\" data-slug=\"likkutei-torah\" data-id=\"4001380580\">לקו\"ת חקת סו, א</a>. ובכ\"מ."],["45","45","וע\"ד ענין התשובה שהמבוקש דתשובה הוא — כפרת העון, כמובן ממה שהביא באגרת התשובה בתחלתה לשון הברייתא: אינו זז משם עד שמוחלין לו (ולא אמר בברייתא בקיצור „מוחלין מיד\"). וראה אגה\"ת רפ\"ב. וראה גם לקו\"ש חי\"ז שם."],["46","46","ראה בית אלקים שם פ\"ב."],["47","47","ח\"ג צז, סע\"א ואילך. וראה עקידה שב־הערה 6. צרור המור פרשתנו עה\"פ. אוה\"ח כג, טו. ובכ\"מ."],["48","48","ר\"ש מרשקוב."]]],[1300221134,"וואס דאס איז פאר יחידי סגולה וועל־כע זיינען מכוין די כוונות ויחודים, איז דער ענין התפלה כולל ניט נאר עבודת ועליית האדם, נאר אויך (ובעיקר —) דעם מבוקש ומטרה פון תפלה — דער תיקון ועליית העולמות, וואס דאס איז אויך דער מקור ההמשכות וועלכע וערן נמשך למטה אין ענינים רוחניים וגשמיים: רופא חולים ומברך השנים וכו'.\nאון דעריבער קומט ספירת העומר, וואס איז מדגיש עבודת האדם, ניט בסוף הסידור (אלס חותם ותכלית), נאר פריער — און לאח\"ז קומען תפלות וכוונות פון שלש רגלים כו' ר\"ה יוהכ\"פ כו' ביז שמע\"צ ושמח\"ת, וואס ענינם איז די שלימות אין די המשכות ווי זיי וערן נמשך למטה.\nאין סידור פון אלטן רבי\"ן, וועלכער איז געשריבן דוקא באופן השווה לכל נפש (די סודות וכוונות זיינען ניט בגלוי, כנ\"ל), איז דער סדר אויסגעשטעלט באופן אז אין דעם ענין התפלה איז מודגש די עבודה פונעם אדם, וכנ\"ל בארוכה (אז סיי די חפצא פון תפלה סיי די עליית האדם (גברא) איז אן ענין פון עבודת האדם).\nאון מהאי טעמא איז ער מקדים ומגדיר גלייך בההתחלה די מעלה פון קימה בחצות וואס דורכדעם איז מען אין כלל פון עבדי ה'. און דעריבער איז אויך דער סיום פון זיין סידור ניט מיט די תפלות כו' וואס זיינען פארבונדן מיט קדושת החג, נאר מיט ספירת העומר, וואס איז כולה פעולה ועבודת האדם (אין די אלע ענינים הנ\"ל).\nז. קען מען מיינען, אז די עבודה פון יעדן יחיד בישראל (און בפרט אן עבודה וואס באשטייט בלויז אין „ציילן די טעג\") איז ניט אויף אזויפיל בכח צו\nפועל זיין אין וועלט (תיקון העולמות) — איז ספירת העומר מדגיש, אז אין דעם זעט מען די פעולת העבודה מער ווי אין אנדער עבודה:\nקביעת יו\"ט בכלל איז תלוי אין בני ישראל — „דקדשינהו לזמנייהו\"49, אבער מיט ב\"ד דוקא, מיטן קדוש החודש של ב\"ד (א כלל)50, און די תפלות פון די אידן במשך הרגלים זיי־נען א תוצאה און ברענגען א הוספה אין קדושת היו\"ט. ועד\"ז בשבת, וואס איז „מקדשי וקיימי\"51, איז דא א הוספה דורך „לקדשו\" קידוש ותפילות בני ישראל.\nאבער בא ספירת העומר זעט מען, אז דורך דער ספירה פון יעדן יחיד בפ\"ע (ניט דורך ב\"ד) וערט אויפגעטאן דער חג השבועות52, ער איז ניט תלוי בקביעות דראש חודש (וואַרום „עצרת פעמים חמשה פעמים ששה פעמים שבעה\"<sup data-n=\"53\">53</sup>, נאר אין דעם יום החמישים לעומר, כנ\"ל.\nביז אז בכמה פרטים (בנוגע, לדוגמא, צו יו\"ט שני של גליות) איז חג השבועות הארבער ווי אנדערע יו\"ט, ווייל ער קומט ניט מצד הספק ווי אנדערע יו\"ט, נאר ער האט אין־זיך א כח של ודאי54.\nח. און דאס איז מדגיש די כללות מעלת עבודת האדם בתפלה:\nדער ענין פון תפלה איז ניט נאר צו",[["49","49","ברכות מט, א."],["50","50","כמו שלמדינן מאלה מועדי ה' גו' אשר תקראו אותם (פרשתנו כג, ד) אתם אפילו שוגגים אתם אפילו מזידים אתם אפילו מוטעין (ר\"ה כה, א)."],["51","51","ביצה יז, א."],["52","52","כנ\"ל הערה 9."],["53","53","ר\"ה ו, ב. שו\"ע אדה\"ז הנ\"ל הערה 9."],["54","54","ראה שו\"ת חת\"ס או\"ח סר\"ס קמה. וראה לקו\"ש ח\"ד ע' 1030."]]],[1300221135,"ממשיך זיין למטה אין וועלט דאס וואס איז שוין פארנאן למעלה אין איר שורש ומקור; דער אויפטו פון תפלה איז: „יהי רצון\", צו מאכן55 כביכול א רצון חדש56, וואס איז ניטא אין שורש ומקור, און דאס קומט אראפ אין וועלט און איז משנה נבראים „מכמות שהם, שיתרפא החולה וירד הגשם משמים לארץ ויולדה ויצמחה\". משא\"כ באַ תורה ומצות בכלל איז ניטא קיין שינוי אין קלף התפילין „ע\"י הנחתן בראש כו'\", כמבואר אין תניא57.\nט. ווי די פנימיות פון ענין התפלה וערט נתבאר דורכן אלטן רבי\"ן גופא — וועט נאך בעסער פארשטאנדיק ווערן די שייכות צווישן תפלה און ספירת העומר (ובהתאם להנ\"ל):\nדער אלטער רבי איז מבאר אין לקו\"ת58, אז תפלה וערט ניט אריינגערעכנט אין דעם מנין פון תרי\"ג מצות, ווייל תפלה איז די כוונה פון כל התורה והמצות „והוא העמוד המקיים כל התרי\"ג מצות דוגמת חוט השדרה\".\nדער עיקר ענין התפלה איז אז אוא\"ס ב\"ה וואס איז העכער פון השתלשלות אליו ולא למדותיו59 זאל נמשך ווערן\nלמטה, אין סדר השתלשלות. און די י\"ח ברכות פון שמו\"ע זיינען די „כלים\" צו דער המשכה למטה אז עס זאל זיין דער רופא חולים און מברך השנים.\nויש לומר, אז דער ענין איז מודגש במיוחד ביי ספירת העומר, ווי יעדער יחיד זאגט אין דעם „רבונו של עולם\" גלייך נאך ספירת העומר: „ועל ידי זה יושפע שפע רב בכל העולמות — דוגמת כללות המשכת אוא\"ס אין אלע עולמות דורך תפלה — (און אויך, בוא\"ו המוסיף —) ולתקן את נפשותינו ורוחותינו ונשמותינו מכל סיג ופגם\" — די המשכה כללית דער שפע רב — וערט נמשך אין פרטים, אין כלים, לשנות הנבראים כו', ע\"ד ווי גערעדט פריער בענין התפלה.\nאון דורך דעם וואס מ'איז זיך עוסק אין הלכות ספירת העומר און מ'רעט בעניני'\nדורך קיום מצות ספירת העומר ובשלימות האפשרית בזמן הזה שהוא זכר למקדש, כולל העסק בהלכות ספה\"ע בנגלה ובפנימיות התורה\nאיז דאס ממהר קיום התפלה גלייך נאך ספירת העומר: „יחזיר לנו עבודת בית המקדש למקומה60 (און מ'וועט מקיים זיין די מצוה כתיקונה)61 במהרה בימינו (ממש) אמן סלה\"62.\n(משיחות כ\"ד טבת ש\"פ וארא וש\"פ משפטים תשמ\"ב)",[["55","55","בלשון חז\"ל: עושין רצונו של מקום (כהפי' שעושין וממשיכים רצון חדש (ראה לקו\"ת פרשתנו לב, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380484\" data-slug=\"likkutei-torah\" data-id=\"4001380484\">שלח מג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380590\" data-slug=\"likkutei-torah\" data-id=\"4001380590\">בלק סח, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381125\" data-slug=\"likkutei-torah\" data-id=\"4001381125\">ברכה צט, ג</a>. ובכ\"מ)): וכמחז\"ל צדיק גוזר והקב\"ה מקיים (ראה תענית כג, א. זח\"ב טו, א. שבת נט, ב. וראה מפרשי המשנה (רע\"ב וכו') אבות פ\"ב מ\"ד. ב\"מ פה, א. ועוד. — ס' הליקוטים (מהצ\"צ) מע' צדיק. וש\"נ)."],["56","56","כידוע החילוק בין ברכה לתפלה (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380792\" data-slug=\"likkutei-torah\" data-id=\"4001380792\">לקו\"ת ראה יט, א</a>. ובכ\"מ). וראה לקו\"ת חקת שם. ועוד."],["57","57","קו\"א (קנה, א). וראה לקו\"ת בלק ע, ד ואילך."],["58","58","שם. וראה אוה\"ת שם ד\"ה לא הביט און (ע' תתקצד ואילך. ס\"ע תתקצז). ועוד."],["59","59","ספרי הובא ונתבאר בפרדס של\"ב פ\"ב. סידור שער הק\"ש ד\"ה איתא בספרי (פה, ב ואילך). ועוד."],["60","60","כי יבנה ביהמ\"ק „במקומו\" (רמב\"ם הל' מלכים ספי\"א)."],["61","61","תוס' מגילה כ, ב ד\"ה כל הלילה. שו\"ע אדה\"ז סתפ\"ט סי\"א."],["62","62","עבודת סלה שאין לה הפסק (עירובין נד, א) כי זהו ביהמ\"ק דכוננו ידיך — נצחי (זהר ח\"ג רכא, א)."]]]]});
